-- Curriculum outline generated from supabase/curriculum/*.json by scripts/curriculum/to-sql.mts.
-- 849 units, 3324 lessons. Do not edit by hand: edit the JSON and regenerate.

on conflict (id) do update set
  title = excluded.title,
  summary = excluded.summary,
  position = excluded.position;

on conflict (id) do update set
  title = excluded.title,
  objectives = excluded.objectives,
  position = excluded.position;
