insert into public.units (id, subject_id, grade, position, title, summary) values
('e49d1028-c688-5e1c-9fb9-3b98b4bfeb2b', 'art-design', 7, 1, '{"en":"Elements of art: line and shape","fr":"Éléments de l''art : ligne et forme","mfe":"Elman lar : liny ek form"}'::jsonb, '{"en":"Students explore how lines and shapes form the building blocks of visual art, experimenting with different line qualities and geometric and organic shapes.","fr":"Les élèves découvrent comment les lignes et les formes constituent les bases de l''art visuel, en expérimentant différentes qualités de lignes ainsi que des formes géométriques et organiques.","mfe":"Elev pou explor kouma liny ek form form baz lar vizyel, an eksperiment diferan kalite liny ek form geometrik ek organik."}'::jsonb),
('a55b9c51-82e3-5df9-99b5-5a9d6da91fc4', 'art-design', 7, 2, '{"en":"Understanding colour","fr":"Comprendre la couleur","mfe":"Konpran kouler"}'::jsonb, '{"en":"This unit introduces the colour wheel, primary and secondary colours, and how warm and cool colours create mood in artwork.","fr":"Cette unité présente le cercle chromatique, les couleurs primaires et secondaires, et la manière dont les couleurs chaudes et froides créent une ambiance dans une œuvre.","mfe":"Sa linite la introdir rou kouler, kouler primer ek segonder, ek kouma kouler so ek fre kree lanbyans dan enn zoev lar."}'::jsonb),
('802d27bb-33ad-5d52-ad6f-3ee672bbbfba', 'art-design', 7, 3, '{"en":"Observational drawing skills","fr":"Compétences en dessin d''observation","mfe":"Konpetans dessin obzervasyon"}'::jsonb, '{"en":"Students develop drawing skills by observing real objects, practising proportion, shading and still life composition.","fr":"Les élèves développent leurs compétences en dessin en observant des objets réels, en pratiquant les proportions, les ombrages et la composition de natures mortes.","mfe":"Elev devlop zot konpetans dessin par obzerv obze reel, pratik proporsyon, lonbraz ek konpozisyon natir mort."}'::jsonb),
('ba3b94a6-a66b-53ae-a06b-c8cdf7861233', 'art-design', 7, 4, '{"en":"Texture and pattern","fr":"Texture et motif","mfe":"Textir ek motif"}'::jsonb, '{"en":"This unit explores how texture and pattern are found in nature and everyday life, and how they can be used to enrich artwork.","fr":"Cette unité explore comment la texture et le motif se retrouvent dans la nature et la vie quotidienne, et comment ils peuvent enrichir une œuvre d''art.","mfe":"Sa linite la explor kouma textir ek motif ena dan lanatir ek lavi toulezour, ek kouma zot kapav anrisi enn zoev lar."}'::jsonb),
('95aa208f-b7d9-5a9f-abae-f0dcf0450577', 'art-design', 7, 5, '{"en":"Introduction to painting","fr":"Introduction à la peinture","mfe":"Introdiksyon lapentir"}'::jsonb, '{"en":"Students are introduced to basic painting techniques and materials, experimenting with brushwork and simple landscape painting.","fr":"Les élèves découvrent les techniques et matériaux de base de la peinture, en expérimentant les coups de pinceau et la peinture de paysages simples.","mfe":"Elev pou dekouver teknik ek materyo debaz lapentir, an eksperiment kout lapo pinso ek lapentir peyzaz sinp."}'::jsonb),
('2a1c0543-5ae9-5f82-9929-06b4f7d52343', 'art-design', 7, 6, '{"en":"Introduction to printmaking","fr":"Introduction à la gravure","mfe":"Introdiksyon linprimri"}'::jsonb, '{"en":"This unit introduces basic printmaking methods, including stamp printing and simple relief techniques, to create repeated designs.","fr":"Cette unité présente des méthodes de base de gravure, y compris l''impression au tampon et des techniques de relief simples, pour créer des motifs répétés.","mfe":"Sa linite la introdir metod debaz linprimri, ki inklir linprimri tanpon ek teknik relyef sinp, pou kree desin repete."}'::jsonb),
('13724dc9-82b3-5953-801d-d81428de4941', 'art-design', 7, 7, '{"en":"Mauritian arts and crafts","fr":"Arts et artisanat mauriciens","mfe":"Lar ek krafte moris"}'::jsonb, '{"en":"Students explore traditional Mauritian crafts and textile patterns, appreciating the island''s multicultural artistic heritage through a small project.","fr":"Les élèves explorent l''artisanat traditionnel mauricien et les motifs textiles, en appréciant l''héritage artistique multiculturel de l''île à travers un petit projet.","mfe":"Elev explor krafte tradisyonel moris ek motif tekstil, an apresie leritaz artistik multikiltirel zil atraver enn ti proze."}'::jsonb),
('32f0fa5c-fade-5a19-8bff-473ca323f1eb', 'art-design', 8, 1, '{"en":"Elements of art revisited","fr":"Les éléments de l''art revisités","mfe":"Elema lar rivizite"}'::jsonb, '{"en":"Students revise and deepen their understanding of the visual elements of art through observation and practice using Mauritian subjects.","fr":"Les élèves révisent et approfondissent leur compréhension des éléments visuels de l''art par l''observation et la pratique sur des sujets mauriciens.","mfe":"Bann elev revize ek apronfondi zot konpreansion bann elema vizyel lar par observasion ek pratik lor bann size morisien."}'::jsonb),
('875ca04d-b865-52ee-b71f-633525e0f14f', 'art-design', 8, 2, '{"en":"Principles of design","fr":"Principes du design","mfe":"Prensip design"}'::jsonb, '{"en":"This unit introduces students to the principles that guide composition, including balance, contrast, rhythm and emphasis.","fr":"Cette unité initie les élèves aux principes qui guident la composition, notamment l''équilibre, le contraste, le rythme et l''accent.","mfe":"Sa lini-la introdir bann elev bann prensip ki gid konpozision, ki inklir balans, kontras, ritm ek anfaz."}'::jsonb),
('26247b36-23c7-59cb-88b6-b97eae58372e', 'art-design', 8, 3, '{"en":"Drawing and observation skills","fr":"Compétences de dessin et d''observation","mfe":"Konpetans desen ek observasion"}'::jsonb, '{"en":"Students develop observational drawing skills by studying still life, people and everyday Mauritian objects.","fr":"Les élèves développent des compétences de dessin d''observation en étudiant la nature morte, les personnes et les objets quotidiens mauriciens.","mfe":"Bann elev devlop zot konpetans desen par observasion an etidye nati mort, dimounn ek bann obze ki servi toulezour Moris."}'::jsonb),
('c2e5077f-9154-51e0-8ede-896800c4ec67', 'art-design', 8, 4, '{"en":"Painting techniques","fr":"Techniques de peinture","mfe":"Teknik lapentir"}'::jsonb, '{"en":"This unit explores various painting media and techniques, encouraging experimentation and creative expression.","fr":"Cette unité explore diverses techniques et supports de peinture, encourageant l''expérimentation et l''expression créative.","mfe":"Sa lini-la explor bann diferan medyom ek teknik lapentir, ankouraz eksperimantasion ek ekspresion kreatif."}'::jsonb),
('e8fbe775-256c-5277-867b-18d9d2ce8989', 'art-design', 8, 5, '{"en":"Printmaking and pattern design","fr":"Gravure et conception de motifs","mfe":"Enprimri ek design motif"}'::jsonb, '{"en":"Students learn basic printmaking methods and design repeating patterns inspired by Mauritian heritage.","fr":"Les élèves apprennent des méthodes de gravure de base et conçoivent des motifs répétitifs inspirés du patrimoine mauricien.","mfe":"Bann elev aprann bann metod enprimri debaz ek design bann motif repete inspir par patrimwan morisien."}'::jsonb),
('e7a48eab-9ec0-59c7-aa22-146339f488f0', 'art-design', 8, 6, '{"en":"Sculpture and 3D design","fr":"Sculpture et design en 3D","mfe":"Skiltir ek design 3D"}'::jsonb, '{"en":"This unit introduces students to three-dimensional art making using accessible and recycled materials.","fr":"Cette unité initie les élèves à la création artistique tridimensionnelle en utilisant des matériaux accessibles et recyclés.","mfe":"Sa lini-la introdir bann elev kreasion lar an trwadimansion an servi bann materyo aksesib ek rekikle."}'::jsonb),
('3d459d45-c543-559b-8e57-13bb3e72b15e', 'art-design', 8, 7, '{"en":"Art history and appreciation","fr":"Histoire de l''art et appréciation","mfe":"Zistwar lar ek apresyasion"}'::jsonb, '{"en":"Students explore local and world art movements, developing skills in visual analysis and critical appreciation.","fr":"Les élèves explorent les mouvements artistiques locaux et mondiaux, développant des compétences d''analyse visuelle et d''appréciation critique.","mfe":"Bann elev explor bann mouvman lartistik lokal ek mondyal, devlop konpetans analiz vizyel ek apresyasion kritik."}'::jsonb),
('f2b8ee7b-e27c-50db-a864-dbaf3395c05f', 'art-design', 9, 1, '{"en":"Elements and principles of design","fr":"Éléments et principes du design","mfe":"Elema ek prensip design"}'::jsonb, '{"en":"Students revisit and deepen their understanding of the elements and principles of art, applying them with greater control and intention in compositions.","fr":"Les élèves révisent et approfondissent leur compréhension des éléments et principes de l''art, en les appliquant avec plus de contrôle et d''intention dans leurs compositions.","mfe":"Bann elev revize ek apronfondi zot konpreansion lor elema ek prensip lar, e aplik zot avek plis kontrol ek lintansion dan zot bann konpozision."}'::jsonb),
('3cce393b-1a10-5e77-90d9-10c8e6f128b3', 'art-design', 9, 2, '{"en":"Observational drawing skills","fr":"Compétences de dessin d''observation","mfe":"Konpetans desin observasion"}'::jsonb, '{"en":"Students strengthen accuracy and confidence in drawing from direct observation, including still life and natural forms found locally.","fr":"Les élèves renforcent leur précision et leur confiance dans le dessin d''observation, y compris les natures mortes et les formes naturelles locales.","mfe":"Bann elev renforsi zot presizion ek konfians dan desin observasion, enkli nati mort ek form natirel lokal."}'::jsonb),
('74eb27c8-cc9b-51cd-acb7-bfb57145733a', 'art-design', 9, 3, '{"en":"Painting and mixed media","fr":"Peinture et techniques mixtes","mfe":"Pentir ek teknik mikse"}'::jsonb, '{"en":"Students experiment with paint and combine materials to develop personal expression and technical versatility.","fr":"Les élèves expérimentent la peinture et combinent des matériaux pour développer une expression personnelle et une polyvalence technique.","mfe":"Bann elev eksperiment ar pentir e konbine bann materio pou devlop lekspresion personel ek versatilite teknik."}'::jsonb),
('26f0bff9-ed28-50d2-9fcb-2d3220b3b251', 'art-design', 9, 4, '{"en":"Printmaking basics","fr":"Bases de la gravure","mfe":"Baz gravir"}'::jsonb, '{"en":"Students learn simple printmaking methods to understand reproduction, pattern and design in art.","fr":"Les élèves apprennent des méthodes simples de gravure pour comprendre la reproduction, le motif et le design dans l''art.","mfe":"Bann elev aprann bann metod senp gravir pou konpran reprodiksion, motif ek design dan lar."}'::jsonb),
('bb0b6008-f151-573d-b38f-87e4b40802bc', 'art-design', 9, 5, '{"en":"Sculpture and three-dimensional design","fr":"Sculpture et design tridimensionnel","mfe":"Skiltir ek design trwadimansionel"}'::jsonb, '{"en":"Students explore form in three dimensions using clay, wire and recycled materials to build sculptural skills.","fr":"Les élèves explorent la forme en trois dimensions en utilisant l''argile, le fil de fer et des matériaux recyclés pour développer des compétences sculpturales.","mfe":"Bann elev explor form an trwa dimansion servi lagliz, fil fer ek materio rekikle pou devlop konpetans skiltiral."}'::jsonb),
('446f6e6c-114d-5868-a1aa-83e3af6c5191', 'art-design', 9, 6, '{"en":"Graphic design and digital art","fr":"Design graphique et art numérique","mfe":"Design grafik ek lar numerik"}'::jsonb, '{"en":"Students are introduced to graphic design principles and basic digital tools relevant to visual communication.","fr":"Les élèves découvrent les principes du design graphique et les outils numériques de base pertinents pour la communication visuelle.","mfe":"Bann elev dekouver prensip design grafik ek bann zouti numerik debaz pou komunikasion vizyel."}'::jsonb),
('53ff7f39-edd2-53dc-98b9-63693458e287', 'art-design', 9, 7, '{"en":"Art history and cultural heritage","fr":"Histoire de l''art et patrimoine culturel","mfe":"Listwar lar ek patrimwann kiltirel"}'::jsonb, '{"en":"Students study Mauritian and world art movements, developing appreciation of cultural diversity and heritage in art.","fr":"Les élèves étudient les mouvements artistiques mauriciens et mondiaux, développant une appréciation de la diversité culturelle et du patrimoine dans l''art.","mfe":"Bann elev etidie mouvman artistik morisien ek mondial, devlop apresiasion divertsite kiltirel ek patrimwann dan lar."}'::jsonb),
('3ea0c15d-ad29-50d4-a6cb-515fe50b255f', 'art-design', 9, 8, '{"en":"Personal project and portfolio building","fr":"Projet personnel et constitution de portfolio","mfe":"Proze personel ek konstriksion portfolyo"}'::jsonb, '{"en":"Students plan, develop and present a personal art project, building skills needed for future portfolio work at SC level.","fr":"Les élèves planifient, développent et présentent un projet artistique personnel, développant les compétences nécessaires pour le travail de portfolio au niveau SC.","mfe":"Bann elev planifie, devlope ek prezant enn proze lar personel, batir konpetans neseser pou travay portfolyo nivo SC."}'::jsonb),
('b8b75649-3f3c-5df8-b1f9-47718114c2d7', 'art-design', 10, 1, '{"en":"Foundations of observational drawing","fr":"Fondements du dessin d''observation","mfe":"Baz disegn lobzervasyon"}'::jsonb, '{"en":"Students revisit and strengthen core drawing skills, focusing on accurate observation, proportion and tonal control using local objects and scenes as subject matter.","fr":"Les élèves revisitent et renforcent les compétences de base en dessin, en se concentrant sur l''observation précise, les proportions et le contrôle des tons à partir d''objets et de scènes locales.","mfe":"Elev revize ek ranforsi bann konpetans baz dan disegn, konsantre lor lobzervasyon presi, propor��syon ek kontrol ton avek bann obze ek sennn lokal kouma sizet."}'::jsonb),
('f44b5b78-c9b0-5af9-b127-5d0f47689a2f', 'art-design', 10, 2, '{"en":"Colour theory and painting media","fr":"Théorie des couleurs et médiums de peinture","mfe":"Teori koulir ek medyom lapentir"}'::jsonb, '{"en":"This unit explores colour relationships and introduces practical experience with watercolour, acrylic and mixed media painting techniques.","fr":"Cette unité explore les relations entre les couleurs et propose une expérience pratique avec l''aquarelle, l''acrylique et les techniques de médiums mixtes.","mfe":"Sa lini-la explor bann relasyon koulir ek introdir lexperyans pratik avek akwarel, akrilik ek teknik medyom mikst."}'::jsonb),
('3c3ee8dc-4aec-5d7e-8fde-9ddbae019280', 'art-design', 10, 3, '{"en":"Design principles and composition","fr":"Principes de conception et composition","mfe":"Prinsip disenn ek konpozisyon"}'::jsonb, '{"en":"Students study the formal elements and principles of art and design, applying them to create balanced and effective compositions.","fr":"Les élèves étudient les éléments formels et les principes de l''art et du design, en les appliquant pour créer des compositions équilibrées et efficaces.","mfe":"Elev etidye bann element formel ek prinsip lar ek disenn, aplik zot pou kree konpozisyon balanse ek efikas."}'::jsonb),
('8e9464ca-df2e-5db6-aec5-4f55d0a5f79d', 'art-design', 10, 4, '{"en":"Printmaking techniques","fr":"Techniques de gravure","mfe":"Teknik gravir"}'::jsonb, '{"en":"Students are introduced to relief and stencil printmaking methods, exploring pattern, repetition and surface texture.","fr":"Les élèves sont initiés aux méthodes de gravure en relief et au pochoir, en explorant le motif, la répétition et la texture de surface.","mfe":"Elev fer konesans avek metod gravir relyef ek stensil, explor motif, repetisyon ek tekstir sirfas."}'::jsonb),
('83a5a2d8-ca24-5936-86ae-7e55dd946cc7', 'art-design', 10, 5, '{"en":"Three-dimensional design and sculpture","fr":"Design tridimensionnel et sculpture","mfe":"Disenn trwadimansyonel ek skiltir"}'::jsonb, '{"en":"This unit introduces students to working in three dimensions using clay, found materials and simple construction methods.","fr":"Cette unité initie les élèves au travail en trois dimensions à l''aide d''argile, de matériaux trouvés et de méthodes de construction simples.","mfe":"Sa lini-la introdir elev travay an trwa dimansyon avek larzil, materyo trouve ek metod konstriksyon senp."}'::jsonb),
('7b466ab0-3e01-59e6-8473-d0768f5ea603', 'art-design', 10, 6, '{"en":"Art history and critical studies","fr":"Histoire de l''art et études critiques","mfe":"Zistwar lar ek etid kritik"}'::jsonb, '{"en":"Students explore selected art movements and Mauritian artists, developing skills in visual analysis and critical writing.","fr":"Les élèves explorent des mouvements artistiques sélectionnés et des artistes mauriciens, en développant des compétences en analyse visuelle et en écriture critique.","mfe":"Elev explor bann mouvman ar select ek artis Morisyen, devlop konpetans an analiz vizyel ek ekritir kritik."}'::jsonb),
('6c0b8806-aa04-5ad4-84e6-b757f758eab9', 'art-design', 10, 7, '{"en":"Developing a personal coursework project","fr":"Développer un projet personnel de contrôle continu","mfe":"Devlop enn projet personel kour"}'::jsonb, '{"en":"Students begin an extended coursework project, applying research, experimentation and reflective practice towards a personal outcome.","fr":"Les élèves commencent un projet de contrôle continu élargi, en appliquant la recherche, l''expérimentation et la pratique réflexive vers un résultat personnel.","mfe":"Elev koumans enn projet kour elarzi, aplik rerses, esperimantasyon ek pratik reflesif ver enn rezilta personel."}'::jsonb),
('a771b24c-e66b-539e-95f1-5c2680471be2', 'art-design', 11, 1, '{"en":"Observation and recording skills","fr":"Compétences d''observation et de dessin","mfe":"Konpetans lobzervasion ek desine"}'::jsonb, '{"en":"Students strengthen observational drawing through still life, natural forms and everyday Mauritian objects, building confidence in accurate recording before developing personal coursework themes.","fr":"Les élèves renforcent le dessin d''observation à travers des natures mortes, des formes naturelles et des objets mauriciens du quotidien, gagnant en confiance avant de développer leurs thèmes personnels.","mfe":"Bann elev ranforsi zot desine lobzervasion atraver nati mort, form natirel ek zobze kotidien Moris, pou gagn plis konfians avan devlop zot ler tem personel."}'::jsonb),
('d29b4b5e-d338-533e-a00b-5c1a22d7181a', 'art-design', 11, 2, '{"en":"Developing a personal coursework theme","fr":"Développer un thème personnel de travail","mfe":"Devlop enn tem personel travay"}'::jsonb, '{"en":"Learners choose and research a personal theme, gathering primary and secondary sources to guide sustained coursework development for the O Level portfolio.","fr":"Les élèves choisissent et explorent un thème personnel, rassemblant des sources primaires et secondaires pour guider leur travail de portfolio pour le O Level.","mfe":"Bann elev swazir ek fer resers lor enn tem personel, ramas sours primer ek segonder pou gid zot devlopman portfolio pou O Level."}'::jsonb),
('15e60a26-4d65-56bf-9c3f-e61163b85144', 'art-design', 11, 3, '{"en":"Colour, composition and design principles","fr":"Couleur, composition et principes de design","mfe":"Kouler, konpozisyon ek prinsip design"}'::jsonb, '{"en":"Students explore colour theory, composition and design principles to strengthen visual decision-making in their developing coursework pieces.","fr":"Les élèves explorent la théorie des couleurs, la composition et les principes de design pour renforcer leurs choix visuels dans leurs travaux en cours.","mfe":"Bann elev explor teori kouler, konpozisyon ek prinsip design pou ranforsi zot desizion vizyel dan zot travay ki pe devlope."}'::jsonb),
('07ce63fd-0436-5f7a-9a84-6b411dc887b1', 'art-design', 11, 4, '{"en":"Printmaking and surface techniques","fr":"Gravure et techniques de surface","mfe":"Enprimri ek teknik siperfisi"}'::jsonb, '{"en":"Learners experiment with printmaking methods such as relief and mono printing to add texture and variety to their coursework outcomes.","fr":"Les élèves expérimentent des méthodes de gravure telles que le relief et le monotype pour enrichir leurs travaux de texture et de variété.","mfe":"Bann elev fer lexperyans ek metod enprimri kouma relief ek mono print pou azout textir ek varyete dan zot travay."}'::jsonb),
('2c25e0c8-a791-587c-ad32-2ab34b59d06b', 'art-design', 11, 5, '{"en":"Mixed media exploration","fr":"Exploration des médias mixtes","mfe":"Explorasyon medya mixte"}'::jsonb, '{"en":"Students combine drawing, paint, collage and found materials to expand technical range and personal expression within coursework.","fr":"Les élèves combinent dessin, peinture, collage et matériaux trouvés pour élargir leur registre technique et leur expression personnelle.","mfe":"Bann elev konbinn desine, lapentir, collage ek materyo trouve pou elarzi zot gamm teknik ek expresyon personel."}'::jsonb),
('7c8415b3-c2ea-5966-8b45-b554a2bc7b3a', 'art-design', 11, 6, '{"en":"Building the coursework portfolio","fr":"Construire le dossier de travail","mfe":"Konstrir dosye travay"}'::jsonb, '{"en":"Learners consolidate sketchbook studies and experiments into a final coursework portfolio, focusing on development and resolution of ideas.","fr":"Les élèves rassemblent leurs études et expérimentations en un dossier de travail final, en développant et en résolvant leurs idées.","mfe":"Bann elev rasembl zot letid ek lexperyans dan enn dosye travay final, konsantre lor devlopman ek rezolisyon lide."}'::jsonb),
('4c767e18-4498-573d-98f3-ffd4ff5f06d4', 'art-design', 11, 7, '{"en":"Preparing for the examination paper","fr":"Se préparer à l''épreuve d''examen","mfe":"Prepar pou lepev lexame"}'::jsonb, '{"en":"Students prepare for the O Level controlled test by practising exam themes, planning under time constraints and refining technical skills for the final assessment.","fr":"Les élèves se préparent à l''épreuve contrôlée du O Level en s''exerçant sur des thèmes d''examen, en planifiant sous contrainte de temps et en perfectionnant leurs compétences techniques.","mfe":"Bann elev prepar pou test kontrole O Level par pratik tem lexame, planifikasyon avek letan limite ek amelior zot konpetans teknik pou levalyasion final."}'::jsonb),
('256d7fda-b446-5894-b2ff-8d0237cd80b3', 'art-design', 12, 1, '{"en":"Introduction to AS Level art and design","fr":"Introduction aux arts plastiques niveau AS","mfe":"Introdiksion ar Art ek Design nivo AS"}'::jsonb, '{"en":"An orientation to the Cambridge AS & A Level Art & Design course, its assessment objectives, coursework structure and expectations for independent practice.","fr":"Une orientation au cours Art & Design AS & A Level de Cambridge, ses objectifs d''évaluation, la structure des travaux pratiques et les attentes en matière de pratique autonome.","mfe":"Enn lorientasion lor kour Cambridge AS & A Level Art & Design, so bann obzektif levaliasion, striktir travay prosedir ek atant pou pratik endepandan."}'::jsonb),
('6649188a-7a99-5694-a0b3-8d2236b7d9ea', 'art-design', 12, 2, '{"en":"Observation and recording skills","fr":"Compétences d''observation et de dessin","mfe":"Konpetans lobzervasion ek anrezistreman"}'::jsonb, '{"en":"Developing accurate observational drawing skills using a variety of subjects, media and viewpoints found in the Mauritian environment.","fr":"Développer des compétences de dessin d''observation précises en utilisant divers sujets, médiums et points de vue de l''environnement mauricien.","mfe":"Devlop bann konpetans desin lobzervasion presi avek diferan size, medyom ek pwennvi dan lanvironnman morisien."}'::jsonb),
('9eed5961-73ab-5e79-91e1-67e8b6c0bffc', 'art-design', 12, 3, '{"en":"Developing a personal theme","fr":"Développer un thème personnel","mfe":"Devlop enn tem personel"}'::jsonb, '{"en":"Guiding students to select, research and develop a personal theme that will underpin their AS coursework project.","fr":"Guider les élèves pour choisir, rechercher et développer un thème personnel qui soutiendra leur projet de travaux pratiques AS.","mfe":"Gid bann etidian pou swazir, rod ek devlop enn tem personel ki pou sipport zot proze travay prosedir AS."}'::jsonb),
('52d457f2-f944-5359-bac5-e348c26d4bb3', 'art-design', 12, 4, '{"en":"Materials, techniques and processes","fr":"Matériaux, techniques et procédés","mfe":"Materyo, teknik ek prosedir"}'::jsonb, '{"en":"Exploring a range of traditional and contemporary materials and processes to expand technical range and confidence.","fr":"Explorer une gamme de matériaux et procédés traditionnels et contemporains pour élargir la maîtrise technique et la confiance.","mfe":"Explor enn ranz materyo ek prosedir tradisionel ek kontanporen pou agrandi kapasite teknik ek konfians."}'::jsonb),
('fe1a2052-bc7f-57b8-b29f-675953d58cca', 'art-design', 12, 5, '{"en":"Critical and contextual studies","fr":"Études critiques et contextuelles","mfe":"Letid kritik ek kontekstyel"}'::jsonb, '{"en":"Analysing the work of artists and movements to understand context, meaning and influence on personal practice.","fr":"Analyser le travail d''artistes et de mouvements pour comprendre le contexte, le sens et l''influence sur la pratique personnelle.","mfe":"Analiz travay bann artis ek mouvman pou konpran kontex, sinifikasion ek lenflians lor pratik personel."}'::jsonb),
('b8ef607e-d540-51ef-b2c2-af12440d7096', 'art-design', 12, 6, '{"en":"Two-dimensional media exploration","fr":"Exploration des médiums bidimensionnels","mfe":"Explorasion medyom de dimansion"}'::jsonb, '{"en":"Developing skills in painting, drawing and mixed 2D media to produce resolved compositions linked to the personal theme.","fr":"Développer des compétences en peinture, dessin et médiums 2D mixtes pour produire des compositions abouties liées au thème personnel.","mfe":"Devlop konpetans dan pentir, desin ek medyom 2D melanze pou prodir konpozision fini ki lie ar tem personel."}'::jsonb),
('50219cd1-8981-56fc-9652-103ee5dae88d', 'art-design', 12, 7, '{"en":"Three-dimensional and mixed media exploration","fr":"Exploration tridimensionnelle et techniques mixtes","mfe":"Explorasion trwa dimansion ek medyom melanze"}'::jsonb, '{"en":"Introducing sculptural and installation approaches, encouraging experimentation with form, space and found materials.","fr":"Introduire des approches sculpturales et d''installation, encourageant l''expérimentation de la forme, de l''espace et des matériaux trouvés.","mfe":"Introdir bann laprosh skilptiral ek lenstalasion, ankouraz lesperimantasion form, lespas ek materyo trouve."}'::jsonb),
('b77e4401-ebbe-505d-b134-a699f244d6d3', 'art-design', 12, 8, '{"en":"Building the personal investigation portfolio","fr":"Constituer le portfolio d''investigation personnelle","mfe":"Konstrir portfolio lanket personel"}'::jsonb, '{"en":"Consolidating a term''s work into a coherent coursework portfolio that demonstrates development, experimentation and a resolved outcome.","fr":"Consolider le travail du trimestre en un portfolio cohérent démontrant développement, expérimentation et une réalisation aboutie.","mfe":"Konsolid travay term dan enn portfolio koeran ki montre devlopman, esperimantasion ek enn rezilta fini."}'::jsonb),
('6b170409-b0c1-542e-ab27-58f59e95169b', 'art-design', 13, 1, '{"en":"Launching the personal investigation","fr":"Lancer l''investigation personnelle","mfe":"Lansman lenketa personel"}'::jsonb, '{"en":"Students identify a sustained theme for their A2 personal investigation, drawing on personal interests, Mauritian culture and global art movements to establish a clear direction for the year''s work.","fr":"Les élèves identifient un thème durable pour leur investigation personnelle A2, en s''appuyant sur leurs intérêts personnels, la culture mauricienne et les mouvements artistiques mondiaux pour définir une direction claire pour le travail de l''année.","mfe":"Bann elev idantifie enn tem soutenu pou zot lenketa personel A2, ki baze lor zot lentere personel, kiltir morisien ek mouvman lar mondyal pou etabli enn direksyon kler pou travay lane a.mfe"}'::jsonb),
('4ce0faa4-2b24-59ed-8a1b-65c82ba1b051', 'art-design', 13, 2, '{"en":"Critical and contextual research skills","fr":"Compétences de recherche critique et contextuelle","mfe":"Konpetans rese kritik ek kontekstyel"}'::jsonb, '{"en":"Students deepen their ability to analyse artworks, artists and movements in social and historical context, building the critical foundation needed for the personal study.","fr":"Les élèves approfondissent leur capacité à analyser des œuvres, des artistes et des mouvements dans leur contexte social et historique, construisant la base critique nécessaire pour l''étude personnelle.","mfe":"Bann elev developpe zot kapasite pou analiz zoev lar, artis ek mouvman dan zot kontekst sosyal ek istorik, pou bati fondasyon kritik neseser pou letid personel."}'::jsonb),
('ac5eb84e-99f4-5107-94d6-5a01869c0a6d', 'art-design', 13, 3, '{"en":"Experimentation with media and processes","fr":"Expérimentation avec les médias et procédés","mfe":"Esperimantasyon ar bann medya ek prose"}'::jsonb, '{"en":"Students explore a wide range of media, techniques and processes to test possibilities for their personal investigation and build technical confidence.","fr":"Les élèves explorent une large gamme de médias, techniques et procédés pour tester des possibilités pour leur investigation personnelle et développer leur confiance technique.","mfe":"Bann elev explor enn larz gam medya, teknik ek prose pou teste bann posibilite pou zot lenketa personel ek bati konfyans teknik."}'::jsonb),
('806d6e3b-e7d0-5b8f-bdbe-562408d5e969', 'art-design', 13, 4, '{"en":"Sustained development of ideas","fr":"Développement soutenu des idées","mfe":"Devlopman soutenu bann lide"}'::jsonb, '{"en":"Students refine and develop chosen ideas through a sustained process of experimentation, review and decision-making, moving towards resolved outcomes.","fr":"Les élèves affinent et développent les idées choisies à travers un processus soutenu d''expérimentation, de révision et de prise de décision, vers des résultats aboutis.","mfe":"Bann elev rafinn ek devlop bann lide swazi atraver enn prosesis soutenu esperimantasyon, revizyon ek pran desizyon, pou aboutir ver bann rezilta finalize."}'::jsonb),
('6d9f01e7-fa20-510c-932a-d4f76bac18f5', 'art-design', 13, 5, '{"en":"Producing the personal study","fr":"Rédiger l''étude personnelle","mfe":"Prodwir letid personel"}'::jsonb, '{"en":"Students plan, draft and complete the written personal study, linking critical research to their practical investigation with clear structure and argument.","fr":"Les élèves planifient, rédigent et complètent l''étude personnelle écrite, reliant la recherche critique à leur investigation pratique avec une structure et un argument clairs.","mfe":"Bann elev planifye, ekrir ek konpli letid personel ekrir, ki relie rese kritik ar zot lenketa pratik avek enn striktir ek argiman kler."}'::jsonb),
('292650db-5beb-520f-bd1b-3cb124f2b54a', 'art-design', 13, 6, '{"en":"Preparing for the controlled test","fr":"Préparer l''épreuve contrôlée","mfe":"Prepar pou legzamen kontrole"}'::jsonb, '{"en":"Students prepare for the timed practical examination by researching a set theme, developing preparatory studies and planning their final response.","fr":"Les élèves se préparent à l''épreuve pratique chronométrée en recherchant un thème imposé, en développant des études préparatoires et en planifiant leur réponse finale.","mfe":"Bann elev prepar pou lekzamen pratik ki gard tan par fer rese lor enn tem donnen, devlop letid preparatwar ek planifye zot repons final."}'::jsonb),
('e632a4dc-8ed2-50a4-bc67-19665d838955', 'art-design', 13, 7, '{"en":"Realising and finishing final pieces","fr":"Réaliser et finaliser les œuvres finales","mfe":"Realiz ek fini bann pyes final"}'::jsonb, '{"en":"Students bring together research and experimentation to produce resolved final pieces for both the personal investigation and the examination unit.","fr":"Les élèves rassemblent recherche et expérimentation pour produire des œuvres finales abouties pour l''investigation personnelle et l''épreuve d''examen.","mfe":"Bann elev rasanble rese ek esperimantasyon pou prodwir bann pyes final byen fini pou lenketa personel ek linite lekzamen."}'::jsonb),
('842d484a-21ea-57fc-bc10-07e75cebaa0e', 'art-design', 13, 8, '{"en":"Presentation, evaluation and exhibition","fr":"Présentation, évaluation et exposition","mfe":"Prezantasyon, evalyasyon ek ekspozisyon"}'::jsonb, '{"en":"Students prepare their coursework for assessment, evaluate their overall journey and present their work professionally in a final exhibition.","fr":"Les élèves préparent leur travail pour l''évaluation, évaluent leur parcours global et présentent leur travail de manière professionnelle lors d''une exposition finale.","mfe":"Bann elev prepar zot travay pou levalyasyon, evalue zot parkour global ek prezant zot travay dan enn fason profesyonel dan enn ekspozisyon final."}'::jsonb),
('05480d2b-c76f-54f0-a4fa-829d0fadec25', 'biology', 7, 1, '{"en":"Characteristics of living things","fr":"Caractéristiques des êtres vivants","mfe":"Karakteristik bann kreatir vivan"}'::jsonb, '{"en":"Students explore what distinguishes living things from non-living things and learn the basic classification of organisms.","fr":"Les élèves découvrent ce qui distingue les êtres vivants des objets non vivants et apprennent la classification de base des organismes.","mfe":"Bann elev explor seki diferansie bann kreatir vivan ar bann kitsoz non-vivan ek aprann klasifikasion baz bann organism."}'::jsonb),
('a906f739-f7c5-5b7a-8cba-6e067f2f01fb', 'biology', 7, 2, '{"en":"Cells: the basic units of life","fr":"Les cellules : unités de base de la vie","mfe":"Selil: linite baz lavi"}'::jsonb, '{"en":"Students learn about cell structure, the differences between plant and animal cells, and how cells form tissues and organs.","fr":"Les élèves étudient la structure cellulaire, les différences entre cellules végétales et animales, et comment les cellules forment des tissus et des organes.","mfe":"Bann elev aprann lor striktir selil, diferans ant selil plant ek selil zanimo, ek kouma selil form tisi ek organ."}'::jsonb),
('24165335-060c-51c6-b28e-0ea8d8d65722', 'biology', 7, 3, '{"en":"Nutrition and the digestive system","fr":"La nutrition et le système digestif","mfe":"Nitrisyon ek sistenm dizestif"}'::jsonb, '{"en":"Students learn about food groups, a balanced diet, and how the human digestive system breaks down and absorbs food.","fr":"Les élèves apprennent les groupes alimentaires, une alimentation équilibrée et comment le système digestif humain décompose et absorbe les aliments.","mfe":"Bann elev aprann lor group manze, enn dyet ekilibre, ek kouma sistenm dizestif imin kraze ek absorb manze."}'::jsonb),
('0f29f7f4-ede8-589c-a79a-1ffff2c48879', 'biology', 7, 4, '{"en":"Green plants and photosynthesis","fr":"Les plantes vertes et la photosynthèse","mfe":"Plant ver ek fotosentez"}'::jsonb, '{"en":"Students study plant structure and discover how plants make their own food through photosynthesis.","fr":"Les élèves étudient la structure des plantes et découvrent comment elles fabriquent leur propre nourriture par photosynthèse.","mfe":"Bann elev etidie striktir plant ek dekouver kouma plant fabrik zot prop manze par fotosentez."}'::jsonb),
('ded77647-3203-5576-8b12-f63bd791d444', 'biology', 7, 5, '{"en":"Transport and breathing in humans","fr":"Le transport et la respiration chez l''homme","mfe":"Transpor ek respirasion lor imin"}'::jsonb, '{"en":"Students explore how the human body transports substances through blood and how the respiratory system supplies oxygen for the body.","fr":"Les élèves explorent comment le corps humain transporte les substances par le sang et comment le système respiratoire fournit l''oxygène au corps.","mfe":"Bann elev explor kouma lekor imin transport bann sibstans par disan ek kouma sistenm respiratwar donn lekor oksizenn."}'::jsonb),
('49bfdd4e-16c5-5b90-bd96-5eafd655b15b', 'biology', 7, 6, '{"en":"Ecosystems and interdependence","fr":"Écosystèmes et interdépendance","mfe":"Ekosistenm ek enterdepandans"}'::jsonb, '{"en":"Students investigate how organisms depend on each other and their environment, using Mauritian ecosystems as examples.","fr":"Les élèves examinent comment les organismes dépendent les uns des autres et de leur environnement, avec des écosystèmes mauriciens comme exemples.","mfe":"Bann elev examinn kouma bann organism depann lor kanmarad ek lor zot lanviron, servi bann ekosistenm morisien kouma lexanp."}'::jsonb),
('f3d3e604-d578-5cc6-bf99-0c064a0601cd', 'biology', 7, 7, '{"en":"Health, hygiene and growth","fr":"Santé, hygiène et croissance","mfe":"Lasante, ladiziyenn ek kwasans"}'::jsonb, '{"en":"Students learn about personal hygiene, common diseases, and the basics of human growth and development.","fr":"Les élèves apprennent l''hygiène personnelle, les maladies courantes et les bases de la croissance et du développement humain.","mfe":"Bann elev aprann ladiziyenn personel, bann maladi kouran, ek baz kwasans ek devlopman imin."}'::jsonb),
('efe01b5f-c694-56d6-b3b1-9d8cacf26ede', 'biology', 8, 1, '{"en":"Cells: building blocks of life","fr":"Les cellules : unités de base de la vie","mfe":"Selil: bann element debaz lavi"}'::jsonb, '{"en":"Students explore the structure of plant and animal cells, use microscopes, and understand how cells organise into tissues, organs and systems.","fr":"Les élèves explorent la structure des cellules végétales et animales, utilisent des microscopes et comprennent comment les cellules s''organisent en tissus, organes et systèmes.","mfe":"Bann etidian pou explor lastrikti selil plant ek zanimo, servi mikroskop, ek konpran kouman selil form tisi, organn ek sistenm."}'::jsonb),
('d614b8ad-2608-511d-a968-a51cc89c5cc2', 'biology', 8, 2, '{"en":"Classifying living organisms","fr":"Classification des êtres vivants","mfe":"Klasifikasion bann letr vivan"}'::jsonb, '{"en":"Learners discover why scientists classify organisms and explore the main groups of living things found in Mauritius and beyond.","fr":"Les élèves découvrent pourquoi les scientifiques classifient les organismes et explorent les grands groupes d''êtres vivants présents à Maurice et ailleurs.","mfe":"Bann aprenan dekouver kifer bann syantifik klasifie bann organism ek explor bann gran group letr vivan ki ena Moris ek aiyer."}'::jsonb),
('ce6e7229-3bb5-5415-bf3e-87f203403f0c', 'biology', 8, 3, '{"en":"Nutrition in plants","fr":"La nutrition chez les plantes","mfe":"Nitrision dan plant"}'::jsonb, '{"en":"Students investigate how plants make their own food through photosynthesis and how leaf structure supports this process.","fr":"Les élèves étudient comment les plantes fabriquent leur propre nourriture par la photosynthèse et comment la structure de la feuille favorise ce processus.","mfe":"Bann etidian etidie kouman plant fabrike zot prop manze atraver fotosintez ek kouman lastrikti fey ed dan sa prosesis la."}'::jsonb),
('9fc861e8-2d01-5113-9d0a-0b4715a865fb', 'biology', 8, 4, '{"en":"Nutrition in humans","fr":"La nutrition chez l''humain","mfe":"Nitrision dan limin"}'::jsonb, '{"en":"This unit covers balanced diets, the human digestive system and the importance of dental care for good health.","fr":"Cette unité aborde l''alimentation équilibrée, le système digestif humain et l''importance des soins dentaires pour une bonne santé.","mfe":"Sa linite la kouver alimantasion ekilibre, sistenm dizestif limin ek linportans swin dan pou enn bon lasante."}'::jsonb),
('065a9c6f-5b0b-59ae-8fcf-bb1aa9383399', 'biology', 8, 5, '{"en":"Transport systems in living things","fr":"Systèmes de transport chez les êtres vivants","mfe":"Sistenm transpor dan letr vivan"}'::jsonb, '{"en":"Learners study how blood circulates in humans and how water and nutrients move through plants.","fr":"Les élèves étudient comment le sang circule chez l''humain et comment l''eau et les nutriments se déplacent dans les plantes.","mfe":"Bann aprenan etidie kouman disan sirkile dan limin ek kouman delo ek nitriman deplase dan plant."}'::jsonb),
('5d8d93be-bbeb-5121-9f51-d5ff75a0cf4b', 'biology', 8, 6, '{"en":"Respiration and gas exchange","fr":"La respiration et les échanges gazeux","mfe":"Respirasion ek lesanz gaz"}'::jsonb, '{"en":"Students learn how humans breathe, exchange gases, and how cellular respiration releases energy from food.","fr":"Les élèves apprennent comment les humains respirent, échangent des gaz et comment la respiration cellulaire libère de l''énergie à partir des aliments.","mfe":"Bann etidian aprann kouman limin respire, fer lesanz gaz, ek kouman respirasion seliler lib lenerzi depi manze."}'::jsonb),
('1a0bc242-8409-52c5-b6c1-7f602d8cd3b8', 'biology', 8, 7, '{"en":"Reproduction in flowering plants","fr":"La reproduction chez les plantes à fleurs","mfe":"Reprodiksion dan plant ki ena fler"}'::jsonb, '{"en":"This unit explores flower structure, pollination, fertilisation and how seeds are formed and dispersed.","fr":"Cette unité explore la structure des fleurs, la pollinisation, la fécondation et la formation et dispersion des graines.","mfe":"Sa linite la explor lastrikti fler, polinizasion, fertilizasion ek kouman lagrenn form ek disperse."}'::jsonb),
('6a8ec3b3-d4c6-5e50-95c0-c038d9264e0f', 'biology', 8, 8, '{"en":"Ecosystems and interdependence","fr":"Écosystèmes et interdépendance","mfe":"Ekosistenm ek lentedepandans"}'::jsonb, '{"en":"Learners examine how organisms interact within ecosystems and how human activities affect the environment in Mauritius.","fr":"Les élèves examinent comment les organismes interagissent au sein des écosystèmes et comment les activités humaines affectent l''environnement à Maurice.","mfe":"Bann aprenan examinn kouman organism entéazir dan ekosistenm ek kouman aktivite imin afekte lanvironman Moris."}'::jsonb),
('6bdeda32-225d-5b99-84dd-2cb792191e1f', 'biology', 9, 1, '{"en":"Cell structure and organisation","fr":"Structure et organisation cellulaire","mfe":"Striktir ek organizasyon selil"}'::jsonb, '{"en":"Students revisit cell theory and explore the structure and function of plant and animal cells, tissues and organ systems, using the microscope as a key tool of investigation.","fr":"Les élèves révisent la théorie cellulaire et explorent la structure et la fonction des cellules végétales et animales, des tissus et des systèmes d''organes, en utilisant le microscope comme outil clé d''investigation.","mfe":"Elev revize teori seliler ek explor striktir ek fonksyon selil plant ek zanimo, tisi ek sistem organ, an itiliz mikroskop kouma enn zouti kle pou investigasyon."}'::jsonb),
('5c5a70ec-2fc1-5a2c-91bb-f365113e6738', 'biology', 9, 2, '{"en":"Nutrition in plants and animals","fr":"La nutrition chez les plantes et les animaux","mfe":"Nitrisyon dan plant ek zanimo"}'::jsonb, '{"en":"This unit covers photosynthesis in plants and the human digestive system, linking nutrient requirements to a balanced diet and common nutritional issues in Mauritius.","fr":"Cette unité couvre la photosynthèse chez les plantes et le système digestif humain, en reliant les besoins nutritionnels à une alimentation équilibrée et aux problèmes nutritionnels courants à Maurice.","mfe":"Sa linite la kouver fotosentez dan plant ek sistem dizestif imen, ek li lye bezwen nitrisyonel ar enn regim ekilibre ek problem nitrisyonel kouran dan Moris."}'::jsonb),
('42352316-082a-559d-bd12-d7b24542a841', 'biology', 9, 3, '{"en":"Transport systems in living organisms","fr":"Systèmes de transport chez les organismes vivants","mfe":"Sistem transpor dan bann organism vivan"}'::jsonb, '{"en":"Students explore how substances move within plants and the human circulatory system, including the heart, blood vessels and blood components.","fr":"Les élèves explorent comment les substances se déplacent dans les plantes et dans le système circulatoire humain, y compris le cœur, les vaisseaux sanguins et les composants du sang.","mfe":"Elev explor kouma bann sibstans deplase dan plant ek dan sistem sirkilatwar imen, ki inklir leker, tiyo disan ek konpozan disan."}'::jsonb),
('1cf44e5b-69ff-5441-9b9d-6fb3499d4d33', 'biology', 9, 4, '{"en":"Respiration and gas exchange","fr":"Respiration et échange gazeux","mfe":"Respirasyon ek sanz gaz"}'::jsonb, '{"en":"This unit examines the human respiratory system, gas exchange, and the difference between breathing and cellular respiration, with attention to respiratory health.","fr":"Cette unité examine le système respiratoire humain, les échanges gazeux, et la différence entre la respiration et la respiration cellulaire, avec une attention portée à la santé respiratoire.","mfe":"Sa linite la examinn sistem respiratwar imen, sanz gaz, ek diferans ant respire ek respirasyon seliler, ek li met lasante respiratwar an valer."}'::jsonb),
('c2d422d1-0f91-5eac-b988-3ed38d37e7f4', 'biology', 9, 5, '{"en":"Reproduction in living organisms","fr":"La reproduction chez les organismes vivants","mfe":"Reprodiksyon dan organism vivan"}'::jsonb, '{"en":"Students learn about sexual and asexual reproduction in plants and animals, and study human reproductive systems, puberty and reproductive health.","fr":"Les élèves apprennent la reproduction sexuée et asexuée chez les plantes et les animaux, et étudient les systèmes reproducteurs humains, la puberté et la santé reproductive.","mfe":"Elev aprann reprodiksyon sexyel ek asexyel dan plant ek zanimo, ek etidye sistem reprodiktif imen, pibert ek lasante reprodiktif."}'::jsonb),
('9986850e-8148-52cb-a28d-04b36bc6c25e', 'biology', 9, 6, '{"en":"Ecosystems and interdependence","fr":"Écosystèmes et interdépendance","mfe":"Ekosistem ek enterdepandans"}'::jsonb, '{"en":"This unit explores food chains, food webs, energy flow and the interdependence of organisms within Mauritian ecosystems such as forests, lagoons and coral reefs.","fr":"Cette unité explore les chaînes alimentaires, les réseaux alimentaires, le flux d''énergie et l''interdépendance des organismes dans les écosystèmes mauriciens tels que les forêts, les lagons et les récifs coralliens.","mfe":"Sa linite la explor lasenn alimanter, rezo alimanter, fli lenerzi ek enterdepandans ant organism dan ekosistem morisyen kouma forè, lagon ek resif koralyen."}'::jsonb),
('df8c1839-4810-5d14-be3b-f0d2930f74d3', 'biology', 9, 7, '{"en":"Health, disease and immunity","fr":"Santé, maladies et immunité","mfe":"Lasante, maladi ek imunite"}'::jsonb, '{"en":"Students study pathogens, transmission of disease, the body''s defence mechanisms and the importance of vaccination and hygiene in preventing illness.","fr":"Les élèves étudient les agents pathogènes, la transmission des maladies, les mécanismes de défense du corps et l''importance de la vaccination et de l''hygiène dans la prévention des maladies.","mfe":"Elev etidye pathozèn, transmisyon maladi, mekanism defans lekor ek linportans vaksinasyon ek ladigyenn pou anpes maladi."}'::jsonb),
('b5ecabc6-27f3-5170-8685-05723851df78', 'biology', 10, 1, '{"en":"Characteristics and classification of living organisms","fr":"Caractéristiques et classification des êtres vivants","mfe":"Karakteristik ek klasifikasyon bann kreatir vivan"}'::jsonb, '{"en":"Explore the features that define living things and how scientists organise the diversity of life into groups.","fr":"Explorer les caractéristiques qui définissent les êtres vivants et comment les scientifiques organisent la diversité du vivant en groupes.","mfe":"Explor bann karakteristik ki defini bann kreatir vivan ek kouma bann syantis organiz divers form lavi an group."}'::jsonb),
('eb24abc5-8d5c-58fc-b3d1-383583254bb7', 'biology', 10, 2, '{"en":"Cell structure and organisation","fr":"Structure et organisation cellulaire","mfe":"Striktir ek organizasyon selil"}'::jsonb, '{"en":"Study the basic unit of life, comparing plant and animal cells and how cells build up tissues and organs.","fr":"Étudier l''unité de base du vivant, en comparant les cellules végétales et animales et comment elles forment tissus et organes.","mfe":"Etidye linite de baz lavi, konpar selil plant ek zanimo ek kouma bann selil form tisi ek organ."}'::jsonb),
('849eef7b-dd47-53d5-aaba-3b38e2f8badb', 'biology', 10, 3, '{"en":"Movement of substances into and out of cells","fr":"Mouvement des substances dans et hors des cellules","mfe":"Mouvman sibstans dan ek andeor selil"}'::jsonb, '{"en":"Understand how materials move across cell membranes through diffusion, osmosis and active transport.","fr":"Comprendre comment les substances traversent les membranes cellulaires par diffusion, osmose et transport actif.","mfe":"Konpran kouma bann sibstans travers manbran selil atraver difizyon, osmoz ek transpor aktiv."}'::jsonb),
('ce0e726d-9f39-5838-9e90-e32531a98378', 'biology', 10, 4, '{"en":"Biological molecules and enzymes","fr":"Molécules biologiques et enzymes","mfe":"Molekil byolozik ek anzim"}'::jsonb, '{"en":"Investigate the main nutrient groups and how enzymes control the chemical reactions of life.","fr":"Étudier les principaux groupes de nutriments et comment les enzymes contrôlent les réactions chimiques du vivant.","mfe":"Investig bann group nitriman prinsipal ek kouma anzim kontrol bann reaksyon kimik lavi."}'::jsonb),
('09180738-c737-56c1-aa2a-b7d756265725', 'biology', 10, 5, '{"en":"Plant nutrition","fr":"Nutrition des plantes","mfe":"Nitrisyon plant"}'::jsonb, '{"en":"Examine how plants make their own food through photosynthesis and obtain minerals from the soil.","fr":"Examiner comment les plantes fabriquent leur propre nourriture par la photosynthèse et obtiennent des minéraux du sol.","mfe":"Examin kouma plant fabrik zot prop manze par fotosintez ek gagn mineral depi later."}'::jsonb),
('5cde1745-0a5e-581c-ad05-999f6e742914', 'biology', 10, 6, '{"en":"Human nutrition","fr":"Nutrition humaine","mfe":"Nitrisyon imin"}'::jsonb, '{"en":"Learn about a balanced diet and the structures and processes involved in human digestion.","fr":"Apprendre l''alimentation équilibrée et les structures et processus de la digestion humaine.","mfe":"Aprann lo enn dyet ekilibre ek bann striktir ek prosesis dizesyon imin."}'::jsonb),
('56fe72a5-8e5e-5f72-96a4-52af885f7f2e', 'biology', 10, 7, '{"en":"Transport in plants","fr":"Transport chez les plantes","mfe":"Transpor dan plant"}'::jsonb, '{"en":"Discover how water, minerals and food substances move through plant tissues.","fr":"Découvrir comment l''eau, les minéraux et les substances alimentaires se déplacent dans les tissus végétaux.","mfe":"Dekouver kouma delo, mineral ek substans alimanter deplas dan tisi plant."}'::jsonb),
('89796ba0-dc7e-5d0c-ace4-369fb3a4f2bc', 'biology', 10, 8, '{"en":"Transport in animals","fr":"Transport chez les animaux","mfe":"Transpor dan zanimo"}'::jsonb, '{"en":"Explore the human circulatory system and how blood transports substances around the body.","fr":"Explorer le système circulatoire humain et comment le sang transporte les substances dans le corps.","mfe":"Explor sistem sirkilatwar imin ek kouma disan transport substans dan lekor."}'::jsonb),
('829fa4c5-c9d7-5ca8-b454-e05f80f03b64', 'biology', 11, 1, '{"en":"Respiration","fr":"La respiration","mfe":"Respirasyon"}'::jsonb, '{"en":"Explores how living organisms release energy from food through aerobic and anaerobic respiration, and how respiration rate can be measured and compared.","fr":"Explore comment les organismes vivants libèrent de l''énergie à partir des aliments par la respiration aérobie et anaérobie, et comment le taux de respiration peut être mesuré et comparé.","mfe":"Explor kouma bann organism vivan lib enerzi apartir manze atraver respirasyon aerobik ek anaerobik, ek kouma ou kapav mezir ek konpar to respirasyon."}'::jsonb),
('c5e63e78-6b70-519e-bef9-369549a3ec74', 'biology', 11, 2, '{"en":"Gas exchange in humans and plants","fr":"Les échanges gazeux chez l''homme et les plantes","mfe":"Lesanz gaz kot dimoun ek plant"}'::jsonb, '{"en":"Covers the structures and mechanisms used by humans and plants to exchange gases, and the effects of smoking on the respiratory system.","fr":"Couvre les structures et mécanismes utilisés par les humains et les plantes pour échanger des gaz, ainsi que les effets du tabagisme sur le système respiratoire.","mfe":"Kouver bann striktir ek mekanism ki dimoun ek plant servi pou fer lesanz gaz, ek bann lefe fime lor sistenm respiratwar."}'::jsonb),
('98b35433-16ec-5e46-b699-91c46531a68b', 'biology', 11, 3, '{"en":"Excretion and homeostasis","fr":"L''excrétion et l''homéostasie","mfe":"Ekskresyon ek omeostazi"}'::jsonb, '{"en":"Examines how the human body removes waste products and maintains a stable internal environment through kidney function and control mechanisms.","fr":"Examine comment le corps humain élimine les déchets et maintient un environnement interne stable grâce à la fonction rénale et aux mécanismes de régulation.","mfe":"Examinn kouma lekor imen elimin dese ek gard enn lanvironnman intern stab atraver fonksyon rin ek mekanism kontrol."}'::jsonb),
('25588734-a6a0-5fba-a533-323130ad745a', 'biology', 11, 4, '{"en":"Coordination: nerves and hormones","fr":"La coordination : nerfs et hormones","mfe":"Kordinasyon: nerf ek ormonn"}'::jsonb, '{"en":"Investigates how the nervous system and hormones enable organisms to detect and respond to changes in their environment.","fr":"Étudie comment le système nerveux et les hormones permettent aux organismes de détecter et de répondre aux changements de leur environnement.","mfe":"Investig kouma sistenm nerve ek ormonn permet organism detekte ek reponn a bann sanzman dan zot lanvironnman."}'::jsonb),
('9e021f1b-3710-5276-8e6e-3fd8fc829aae', 'biology', 11, 5, '{"en":"Reproduction in plants and humans","fr":"La reproduction chez les plantes et les humains","mfe":"Reprodiksion kot plant ek dimoun"}'::jsonb, '{"en":"Covers sexual and asexual reproduction, flower structure and pollination, and the human reproductive systems including fertilisation and development.","fr":"Couvre la reproduction sexuée et asexuée, la structure des fleurs et la pollinisation, ainsi que les systèmes reproducteurs humains, y compris la fécondation et le développement.","mfe":"Kouver reprodiksion seksyel ek aseksyel, striktir flerdibwa ek polinizasyon, ek sistenm reprodiktif imen ki inklir fertilizasyon ek devlopman."}'::jsonb),
('4e86143d-a82a-5030-b3c0-d72d2ccbba9e', 'biology', 11, 6, '{"en":"Inheritance and variation","fr":"L''hérédité et la variation","mfe":"Eredite ek variasyon"}'::jsonb, '{"en":"Introduces chromosomes, genes and DNA, cell division, patterns of inheritance, and how variation contributes to evolution by natural selection.","fr":"Introduit les chromosomes, les gènes et l''ADN, la division cellulaire, les modes d''hérédité, et comment la variation contribue à l''évolution par sélection naturelle.","mfe":"Introdir kromozom, zenn ek ADN, divizyon selil, bann pater eredite, ek kouma variasyon kontribye dan levolisyon par seleksyon natirel."}'::jsonb),
('f8d0cbfa-1294-55c8-ac0e-f95d35696be3', 'biology', 11, 7, '{"en":"Organisms and their environment","fr":"Les organismes et leur environnement","mfe":"Organism ek zot lanvironnman"}'::jsonb, '{"en":"Explores relationships between organisms and their environment, energy flow through ecosystems, and cycling of nutrients.","fr":"Explore les relations entre les organismes et leur environnement, le flux d''énergie à travers les écosystèmes et le cycle des nutriments.","mfe":"Explor relasyon ant organism ek zot lanvironnman, kouler enerzi atraver bann ekosistenm, ek sikl nitriman."}'::jsonb),
('d3b46eca-04bf-5b42-b00f-069cd6624280', 'biology', 11, 8, '{"en":"Human influences on the environment","fr":"Les influences humaines sur l''environnement","mfe":"Lenfliyans dimoun lor lanvironnman"}'::jsonb, '{"en":"Considers how human activities affect ecosystems in Mauritius and globally, including pollution, deforestation and conservation efforts.","fr":"Examine comment les activités humaines affectent les écosystèmes à Maurice et dans le monde, y compris la pollution, la déforestation et les efforts de conservation.","mfe":"Konsider kouma bann aktivite dimoun afekte ekosistenm dan Moris ek dan lemonn, ki inklir polisyon, deforestasyon ek zefor konservasyon."}'::jsonb),
('76927852-c37e-5b26-876d-b4231480e3c4', 'biology', 12, 1, '{"en":"Cell structure and organisation","fr":"Structure et organisation cellulaire","mfe":"Striktir ek organizasion selil"}'::jsonb, '{"en":"Explore the fine structure of eukaryotic and prokaryotic cells as revealed by light and electron microscopy, and relate organelle structure to function.","fr":"Explorer la structure fine des cellules eucaryotes et procaryotes révélée par la microscopie optique et électronique, et relier la structure des organites à leur fonction.","mfe":"Explor striktir fin selil ekarnot ek prokarnot ki mikroskop lalimyer ek elektron montre, ek relye striktir organel ar zot fonksion."}'::jsonb),
('db00327a-5c4f-507a-8770-cfbedd819feb', 'biology', 12, 2, '{"en":"Biological molecules","fr":"Molécules biologiques","mfe":"Molekil byolozik"}'::jsonb, '{"en":"Study the structure and roles of water, carbohydrates, lipids and proteins in living organisms, and learn tests used to identify them.","fr":"Étudier la structure et les rôles de l''eau, des glucides, des lipides et des protéines chez les organismes vivants, et apprendre les tests permettant de les identifier.","mfe":"Etidye striktir ek rol dilo, karboidrat, lipid ek proteinn dan bann leta vivan, ek aprann bann test pou idantifye zot."}'::jsonb),
('3aa2a341-973d-5ceb-8ecc-3debe4af14ac', 'biology', 12, 3, '{"en":"Enzymes","fr":"Les enzymes","mfe":"Bann enzim"}'::jsonb, '{"en":"Investigate how enzymes catalyse reactions, the factors affecting their activity, and the mechanisms of inhibition.","fr":"Étudier comment les enzymes catalysent les réactions, les facteurs affectant leur activité et les mécanismes d''inhibition.","mfe":"Anket kouma enzim katalize reaksion, bann fakter ki afekte zot aktivite, ek mekanism inibision."}'::jsonb),
('b1dc18f0-1fd7-5439-8ca1-08646904073d', 'biology', 12, 4, '{"en":"Cell membranes and transport","fr":"Membranes cellulaires et transport","mfe":"Manbran seliler ek transport"}'::jsonb, '{"en":"Examine the fluid mosaic model of membrane structure and the mechanisms by which substances move across membranes.","fr":"Examiner le modèle de la mosaïque fluide de la structure membranaire et les mécanismes de déplacement des substances à travers les membranes.","mfe":"Egzamine model mozaik fliyid pou striktir manbran ek bann mekanism ki substans deplase atraver manbran."}'::jsonb),
('d10aeb33-88ba-5778-a3d8-00bffdd43fd5', 'biology', 12, 5, '{"en":"Cell division and genetic material","fr":"Division cellulaire et matériel génétique","mfe":"Divizion selil ek materyo zenetik"}'::jsonb, '{"en":"Study the mitotic cell cycle, the structure of nucleic acids, and how genetic information is expressed through protein synthesis.","fr":"Étudier le cycle cellulaire mitotique, la structure des acides nucléiques et comment l''information génétique s''exprime par la synthèse des protéines.","mfe":"Etidye sik seliler mitotik, striktir asid nikleik, ek kouma linformasion zenetik eksprime atraver sintez proteinn."}'::jsonb),
('3bd0a776-718d-5f96-8d45-9cb9b40a6b4d', 'biology', 12, 6, '{"en":"Transport in plants","fr":"Transport chez les plantes","mfe":"Transport dan bann plant"}'::jsonb, '{"en":"Understand how water and organic substances are transported through vascular tissues in flowering plants, and how plants adapt to their water environment.","fr":"Comprendre comment l''eau et les substances organiques sont transportées dans les tissus vasculaires des plantes à fleurs, et comment les plantes s''adaptent à leur environnement hydrique.","mfe":"Konpran kouma dilo ek substans organik transporte dan tisi vaskiler bann plant a fler, ek kouma plant adapte ar zot lanvironnman dilo."}'::jsonb),
('c5382ec2-9f15-5904-9a22-453833732c43', 'biology', 12, 7, '{"en":"Transport in mammals","fr":"Transport chez les mammifères","mfe":"Transport dan mamifer"}'::jsonb, '{"en":"Study the mammalian circulatory system, the structure and function of the heart, and the formation of tissue fluid.","fr":"Étudier le système circulatoire des mammifères, la structure et la fonction du cœur, ainsi que la formation du liquide interstitiel.","mfe":"Etidye sistem sirkilasion mamifer, striktir ek fonksion leker, ek formasion likid tisilaire."}'::jsonb),
('de5a7526-96ee-56e1-a037-6742ef5c0b85', 'biology', 12, 8, '{"en":"Gas exchange, disease and immunity","fr":"Échanges gazeux, maladies et immunité","mfe":"Lesanz gaz, maladi ek imunite"}'::jsonb, '{"en":"Explore the structure of the gas exchange system, effects of smoking, transmission of infectious diseases, and the body''s immune response.","fr":"Explorer la structure du système d''échanges gazeux, les effets du tabagisme, la transmission des maladies infectieuses et la réponse immunitaire du corps.","mfe":"Explor striktir sistem lesanz gaz, lefe fime, transmision maladi infeksye, ek repons imin lekor."}'::jsonb),
('519597c7-6d35-5afb-a707-6c84d8a91f1b', 'biology', 13, 1, '{"en":"Energy and respiration","fr":"Énergie et respiration","mfe":"Lenerzi ek respirasyon"}'::jsonb, '{"en":"Explores how living organisms release energy from respiratory substrates through glycolysis, the Krebs cycle and oxidative phosphorylation, and how ATP is used and produced.","fr":"Explore comment les organismes vivants libèrent de l''énergie à partir de substrats respiratoires par la glycolyse, le cycle de Krebs et la phosphorylation oxydative, et comment l''ATP est utilisé et produit.","mfe":"Explor kouman bann organism vivan lib lenerzi apartir bann sibstra respiratwar par glikoliz, sik Krebs ek fosforilasyon oksidativ, ek kouman ATP servi ek prodwir."}'::jsonb),
('4da5b404-e3c6-59e3-a117-a4ee842058f5', 'biology', 13, 2, '{"en":"Photosynthesis","fr":"Photosynthèse","mfe":"Fotosintez"}'::jsonb, '{"en":"Examines the structure of the chloroplast and the light-dependent and light-independent reactions of photosynthesis, and factors limiting its rate.","fr":"Examine la structure du chloroplaste ainsi que les réactions photochimiques et biochimiques de la photosynthèse, et les facteurs limitant son taux.","mfe":"Examinn striktir kloroplast ek bann reaksyon depandan-lalimyer ek non-depandan-lalimyer dan fotosintez, ek bann fakter ki limit so vites."}'::jsonb),
('a4270e53-8f60-5ed0-96c2-a2f93a504203', 'biology', 13, 3, '{"en":"Homeostasis and excretion","fr":"Homéostasie et excrétion","mfe":"Omeostazi ek eksekresyon"}'::jsonb, '{"en":"Covers the principles of homeostasis, control of blood glucose, kidney structure and function, and osmoregulation through hormonal control.","fr":"Couvre les principes de l''homéostasie, la régulation de la glycémie, la structure et le fonctionnement du rein, et l''osmorégulation par contrôle hormonal.","mfe":"Kouver bann prensip omeostazi, kontrol niso glikoz dan disan, striktir ek fonksyon rin, ek osmoregilasyon par kontrol ormonal."}'::jsonb),
('b8acc434-b1fe-596f-b9f8-1a7017f5cbac', 'biology', 13, 4, '{"en":"Coordination and response","fr":"Coordination et réponse","mfe":"Kordinasyon ek repons"}'::jsonb, '{"en":"Studies nervous and hormonal coordination in mammals, the structure and function of neurones and synapses, and coordination in plants through tropisms.","fr":"Étudie la coordination nerveuse et hormonale chez les mammifères, la structure et le fonctionnement des neurones et synapses, et la coordination chez les plantes par les tropismes.","mfe":"Etidye kordinasyon nerve ek ormonal dan mamifer, striktir ek fonksyon nerone ek sinaps, ek kordinasyon dan plant atraver tropizm."}'::jsonb),
('28505477-912c-5436-97ef-014f71234a81', 'biology', 13, 5, '{"en":"Inherited change","fr":"Changement héréditaire","mfe":"Sanzman erediter"}'::jsonb, '{"en":"Focuses on DNA and chromosome structure, meiosis, patterns of inheritance, gene mutation and sex determination.","fr":"Se concentre sur la structure de l''ADN et des chromosomes, la méiose, les modes d''hérédité, la mutation génétique et la détermination du sexe.","mfe":"Konsantre lor striktir ADN ek kromozom, meyoz, model erediter, mitasyon zenetik ek determinasyon seks."}'::jsonb),
('4571499d-6d90-5259-9039-2b7efbc90fa4', 'biology', 13, 6, '{"en":"Selection and evolution","fr":"Sélection et évolution","mfe":"Selesyon ek levolisyon"}'::jsonb, '{"en":"Examines the mechanisms of natural selection, types of selection, speciation and the evidence supporting evolutionary theory.","fr":"Examine les mécanismes de la sélection naturelle, les types de sélection, la spéciation et les preuves soutenant la théorie de l''évolution.","mfe":"Examinn mekanism selesyon natirel, diferan tip selesyon, spesyasyon ek prev ki soutenir teori levolisyon."}'::jsonb),
('825b725c-0bd5-55a9-95f3-020f12b10365', 'biology', 13, 7, '{"en":"Biodiversity, classification and conservation","fr":"Biodiversité, classification et conservation","mfe":"Biodiversite, klasifikasyon ek konservasyon"}'::jsonb, '{"en":"Explores classification systems, methods of measuring biodiversity, and the conservation of species with reference to Mauritius''s unique ecosystems.","fr":"Explore les systèmes de classification, les méthodes de mesure de la biodiversité et la conservation des espèces en référence aux écosystèmes uniques de Maurice.","mfe":"Explor sistem klasifikasyon, metod pou mezire biodiversite, ek konservasyon lespes an referans avek bann ekosistem inik Moris."}'::jsonb),
('5eec41c9-70dc-5635-96f6-35bb17abbbd5', 'biology', 13, 8, '{"en":"Gene technology and biotechnology","fr":"Technologie génique et biotechnologie","mfe":"Teknolozi zenetik ek bioteknolozi"}'::jsonb, '{"en":"Introduces recombinant DNA technology, techniques such as PCR and gel electrophoresis, applications of genetic engineering, and related ethical issues.","fr":"Introduit la technologie de l''ADN recombinant, des techniques telles que la PCR et l''électrophorèse sur gel, les applications du génie génétique et les questions éthiques associées.","mfe":"Introdir teknolozi ADN rekombinan, teknik kouma PCR ek elektroforez zele, aplikasyon zeni zenetik, ek problem etik ki asosye ar li."}'::jsonb),
('8af2d0a6-5754-536b-bf63-e6426f35e001', 'business', 7, 1, '{"en":"Understanding business basics","fr":"Comprendre les bases du commerce","mfe":"Konpran bann baz biznes"}'::jsonb, '{"en":"An introduction to what business is, why people engage in business activities, and how businesses satisfy needs and wants in society.","fr":"Une introduction à ce qu''est le commerce, pourquoi les gens s''engagent dans des activités commerciales, et comment les entreprises satisfont les besoins et désirs dans la société.","mfe":"Enn introdiksion lor ki eski biznes, kifer dimoun fer aktivite biznes, ek kouma biznes satisfer bann bezwin ek dezir dan lasosiete."}'::jsonb),
('cedb1e02-dd66-512f-957c-6b023bc2a46a', 'business', 7, 2, '{"en":"Introducing entrepreneurship","fr":"Introduction à l''entrepreneuriat","mfe":"Introdiksion a lantreprenerya"}'::jsonb, '{"en":"Students explore what entrepreneurship means, the qualities of successful entrepreneurs, and inspiring examples from Mauritius.","fr":"Les élèves explorent ce que signifie l''entrepreneuriat, les qualités des entrepreneurs qui réussissent, et des exemples inspirants de Maurice.","mfe":"Bann etidian explor ki lantreprenerya vedir, bann kalite bon entreprener, ek bann lexanp ki inspire depi Moris."}'::jsonb),
('f531ad0f-2f81-5473-890e-6f0e5dc54239', 'business', 7, 3, '{"en":"Money and its uses","fr":"L''argent et ses usages","mfe":"Kas ek so lizaz"}'::jsonb, '{"en":"This unit introduces the concept of money, its functions, and how people manage money through saving and spending decisions.","fr":"Cette unité présente le concept de l''argent, ses fonctions, et comment les gens gèrent l''argent à travers l''épargne et les dépenses.","mfe":"Sa lekol la introdir konsep kas, so bann fonksion, ek kouma dimoun jere kas atraver sparyen ek depans."}'::jsonb),
('5f9f03c2-f90c-5500-a952-ee184214a241', 'business', 7, 4, '{"en":"Types of business activity","fr":"Types d''activités commerciales","mfe":"Diferan tip aktivite biznes"}'::jsonb, '{"en":"Students learn to classify business activities into primary, secondary and tertiary sectors, with examples from the Mauritian economy.","fr":"Les élèves apprennent à classer les activités commerciales en secteurs primaire, secondaire et tertiaire, avec des exemples de l''économie mauricienne.","mfe":"Etidian aprann klasifie aktivite biznes an sekter primer, sekonder ek tertyer, avek lexanp depi lekonomi morisien."}'::jsonb),
('abc47c96-2538-58c1-96fa-a43783bf5f45', 'business', 7, 5, '{"en":"Setting up a simple business","fr":"Créer une petite entreprise","mfe":"Kree enn ti biznes"}'::jsonb, '{"en":"An introduction to the basic steps and decisions involved in starting a very small business, using simple, relatable examples.","fr":"Une introduction aux étapes de base et aux décisions impliquées dans le démarrage d''une très petite entreprise, avec des exemples simples et pertinents.","mfe":"Enn introdiksion bann etap debaz ek desizion ki bezin kan demar enn tre ti biznes, avek lexanp senp ek relevan."}'::jsonb),
('c3655c83-0129-5ad3-b008-6189c16e15a0', 'business', 7, 6, '{"en":"Working together in business","fr":"Travailler ensemble en entreprise","mfe":"Travay ansam dan biznes"}'::jsonb, '{"en":"This unit explores teamwork, division of labour, and the different roles people play within a business.","fr":"Cette unité explore le travail d''équipe, la division du travail, et les différents rôles que les gens jouent dans une entreprise.","mfe":"Sa lekol la explor travay lekip, divizyon travay, ek bann diferan rol dimoun zwe dan enn biznes."}'::jsonb),
('2c1c3463-67da-5ae8-95d3-43090543b510', 'business', 7, 7, '{"en":"Business and the community","fr":"L''entreprise et la communauté","mfe":"Biznes ek kominote"}'::jsonb, '{"en":"Students consider how businesses affect and are affected by the local community, including responsibility towards people and the environment.","fr":"Les élèves examinent comment les entreprises affectent et sont affectées par la communauté locale, y compris la responsabilité envers les gens et l''environnement.","mfe":"Etidian konsider kouma biznes afekte ek gagn afekte par kominote lokal, ansam ar responsabilite anver dimoun ek anvironnman."}'::jsonb),
('7aac9e4e-9a17-53b8-9bb0-4262fdf53050', 'business', 8, 1, '{"en":"Understanding entrepreneurship","fr":"Comprendre l''entrepreneuriat","mfe":"Konpran lantreprenerya"}'::jsonb, '{"en":"Students explore what entrepreneurship means, the qualities of successful entrepreneurs, and how new business ideas are born in Mauritius.","fr":"Les élèves explorent la signification de l''entrepreneuriat, les qualités des entrepreneurs prospères et la naissance des idées d''affaires à Maurice.","mfe":"Bann elev explor sinifikasyon lantreprenerya, bann kalite bann antreprener ki reisi, ek kouma bann nouvo lide biznes ne dan Moris."}'::jsonb),
('e52bdd1f-d522-59f8-91df-dfc2128667ba', 'business', 8, 2, '{"en":"Forms of business ownership","fr":"Formes de propriété d''entreprise","mfe":"Bann form propriete biznes"}'::jsonb, '{"en":"Learners study the main types of business ownership found in Mauritius, from sole traders to companies, and compare their advantages and disadvantages.","fr":"Les apprenants étudient les principaux types de propriété d''entreprise à Maurice, du commerçant individuel aux sociétés, et comparent leurs avantages et inconvénients.","mfe":"Bann aprenan etidye bann prinsipal tip propriete biznes ki ena Moris, depi komersan endividyel ziska konpayni, ek konpar zot avantaz ek dezavantaz."}'::jsonb),
('2d03b14a-be33-5a8b-8f79-587e2d0ee5ad', 'business', 8, 3, '{"en":"Business functions and organisation","fr":"Fonctions et organisation de l''entreprise","mfe":"Fonksyon ek organizasyon biznes"}'::jsonb, '{"en":"This unit introduces the main departments of a business and how they work together, along with simple organisational structures.","fr":"Cette unité présente les principaux départements d''une entreprise et leur collaboration, ainsi que des structures organisationnelles simples.","mfe":"Sa linite prezante bann prinsipal depatman enn biznes ek kouma zot travay ansam, ansam ar bann striktir organizasyonel senp."}'::jsonb),
('8411eb27-a3ec-5466-ae3a-d525557b2def', 'business', 8, 4, '{"en":"Marketing in business","fr":"Le marketing dans l''entreprise","mfe":"Marketing dan biznes"}'::jsonb, '{"en":"Students learn how businesses identify customer needs and promote their products, focusing on the basics of the marketing mix.","fr":"Les élèves apprennent comment les entreprises identifient les besoins des clients et promeuvent leurs produits, en se concentrant sur les bases du marketing mix.","mfe":"Bann elev aprann kouma biznes idantifie bezwin kliyan ek promot zot prodwi, ar lasans lor baz marketing miks."}'::jsonb),
('758ec9bb-0e79-50e4-8181-c2187491db17', 'business', 8, 5, '{"en":"Money, finance and record keeping","fr":"Argent, finance et tenue de comptes","mfe":"Larzan, finans ek gard rekor"}'::jsonb, '{"en":"Learners explore how businesses manage money, including basic bookkeeping, income and expenses, and the role of banks.","fr":"Les apprenants explorent comment les entreprises gèrent l''argent, y compris la comptabilité de base, les revenus et dépenses, et le rôle des banques.","mfe":"Bann aprenan explor kouma biznes zer larzan, ki inklir konptabilite baz, revenir ek depans, ek rol labank."}'::jsonb),
('5a7177d5-c0b1-56fa-8757-98dfe8f81e40', 'business', 8, 6, '{"en":"Production and operations","fr":"Production et opérations","mfe":"Prodiksyon ek operasyon"}'::jsonb, '{"en":"This unit looks at how goods and services are produced, the resources needed, and the importance of quality and efficiency.","fr":"Cette unité examine comment les biens et services sont produits, les ressources nécessaires, et l''importance de la qualité et de l''efficacité.","mfe":"Sa linite get kouma bann bien ek servis prodwir, bann resours neseser, ek linportans kalite ek lefikasite."}'::jsonb),
('c85c65f3-40be-5eb7-ac37-cf759daba83a', 'business', 8, 7, '{"en":"Business, society and environment","fr":"Entreprise, société et environnement","mfe":"Biznes, sosyete ek lanvironnman"}'::jsonb, '{"en":"Students examine the responsibilities businesses have towards society, consumers and the environment in the Mauritian context.","fr":"Les élèves examinent les responsabilités des entreprises envers la société, les consommateurs et l''environnement dans le contexte mauricien.","mfe":"Bann elev examine bann responsabilite biznes anver sosyete, konsomater ek lanvironnman dan kontekst morisien."}'::jsonb),
('c0f3a1be-425c-5aef-b649-9e3c3f5a17ee', 'business', 9, 1, '{"en":"Entrepreneurship and the Mauritian economy","fr":"L''entrepreneuriat et l''économie mauricienne","mfe":"Lantreprenaria ek lekonomi Moris"}'::jsonb, '{"en":"Students explore what makes someone an entrepreneur and how small businesses contribute to Mauritius''s economy.","fr":"Les élèves explorent ce qui fait un entrepreneur et comment les petites entreprises contribuent à l''économie mauricienne.","mfe":"Bann elev explor ki fer enn dimoun vinn enn lantreprener ek kouma bann piti lantrepriz kontribie dan lekonomi Moris."}'::jsonb),
('20baeafb-ac64-5fda-b79a-eee405223c98', 'business', 9, 2, '{"en":"Forms of business ownership","fr":"Les formes de propriété d''entreprise","mfe":"Bann form propriete biznes"}'::jsonb, '{"en":"This unit compares different ways a business can be owned and organised in Mauritius.","fr":"Cette unité compare les différentes façons dont une entreprise peut être détenue et organisée à Maurice.","mfe":"Sa linite-la konpar diferan fason enn biznes kapav ete posede ek organize dan Moris."}'::jsonb),
('49b64906-47d3-5dc6-8b02-863e722a89eb', 'business', 9, 3, '{"en":"Setting up a business","fr":"Créer une entreprise","mfe":"Kree enn biznes"}'::jsonb, '{"en":"Students learn the practical steps and choices involved in starting a small business.","fr":"Les élèves apprennent les étapes pratiques et les choix impliqués dans la création d''une petite entreprise.","mfe":"Bann elev aprann bann letap pratik ek desizion pou kree enn piti biznes."}'::jsonb),
('f410ed9b-bbbd-5376-814c-83b6d793e0ec', 'business', 9, 4, '{"en":"Marketing and the customer","fr":"Le marketing et le client","mfe":"Marketing ek kliyan"}'::jsonb, '{"en":"This unit introduces how businesses identify customer needs and promote their products.","fr":"Cette unité présente comment les entreprises identifient les besoins des clients et promeuvent leurs produits.","mfe":"Sa linite-la introdir kouma bann biznes idantifie bezwin kliyan ek promot zot prodwi."}'::jsonb),
('8d6fb6c4-3463-5e7f-95fe-47626c06c37f', 'business', 9, 5, '{"en":"Production and operations","fr":"Production et opérations","mfe":"Prodiksion ek operasion"}'::jsonb, '{"en":"Students explore how goods and services are produced and how businesses manage resources.","fr":"Les élèves explorent comment les biens et services sont produits et comment les entreprises gèrent les ressources.","mfe":"Bann elev explor kouma bann bien ek servis prodwir ek kouma biznes zer resours."}'::jsonb),
('d2272f71-1bbb-5129-aead-9a250d79fb9c', 'business', 9, 6, '{"en":"Money and financial records","fr":"L''argent et les registres financiers","mfe":"Larzan ek rezis finansie"}'::jsonb, '{"en":"This unit introduces basic money management and record keeping for small businesses.","fr":"Cette unité présente la gestion de base de l''argent et la tenue de registres pour les petites entreprises.","mfe":"Sa linite-la introdir zesyon debaz larzan ek gard rezis pou piti biznes."}'::jsonb),
('c8550397-6179-5519-a817-4904a5b1a320', 'business', 9, 7, '{"en":"Business, ethics and society","fr":"Entreprise, éthique et société","mfe":"Biznes, letik ek lasosiete"}'::jsonb, '{"en":"Students consider the wider responsibilities businesses have towards people and the environment in Mauritius.","fr":"Les élèves examinent les responsabilités plus larges des entreprises envers les personnes et l''environnement à Maurice.","mfe":"Bann elev konsider bann responsabilite pli larz biznes anver dimoun ek lanvironnman dan Moris."}'::jsonb),
('c89d8f4a-639f-5acf-b73e-87ce397382a3', 'business', 10, 1, '{"en":"Business activity and enterprise","fr":"Activité commerciale et esprit d''entreprise","mfe":"Aktivite biznes ek lespri antreprener"}'::jsonb, '{"en":"Introduces why businesses exist, how scarcity shapes choices, and the role of entrepreneurs in creating value in Mauritius and beyond.","fr":"Introduit les raisons d''être des entreprises, comment la rareté influence les choix et le rôle des entrepreneurs dans la création de valeur à Maurice et ailleurs.","mfe":"Introdir kifer biznes existe, kouma rarte influans desizyon, ek rol antreprener dan kre valer Moris ek partou."}'::jsonb),
('38149354-bdf2-5c23-bc67-51de320d05de', 'business', 10, 2, '{"en":"Classification and forms of business","fr":"Classification et formes d''entreprises","mfe":"Klasifikasyon ek form biznes"}'::jsonb, '{"en":"Explores how businesses are classified by sector and size, and compares legal structures available to entrepreneurs.","fr":"Explore comment les entreprises sont classées par secteur et taille, et compare les structures juridiques disponibles.","mfe":"Explor kouma biznes klasifye par sekter ek gran, ek konpar strikitir legal ki disponib."}'::jsonb),
('2164cfb0-5bef-5e75-a3a8-d43b6ad9421a', 'business', 10, 3, '{"en":"Business growth and integration","fr":"Croissance et intégration des entreprises","mfe":"Kwasans ek integrasyon biznes"}'::jsonb, '{"en":"Examines how and why businesses grow, methods of integration, and the challenges of scale and failure.","fr":"Examine comment et pourquoi les entreprises se développent, les méthodes d''intégration, et les défis liés à la taille et à l''échec.","mfe":"Examinn kouma ek kifer biznes grandi, metod integrasyon, ek difikilte lie ar gran ek fayit."}'::jsonb),
('39430788-9ebf-577e-af63-6c8e5fdad279', 'business', 10, 4, '{"en":"Motivating and organising people","fr":"Motiver et organiser le personnel","mfe":"Motive ek organiz dimounn"}'::jsonb, '{"en":"Covers organisational structures, leadership styles and motivation theories that help businesses manage people effectively.","fr":"Couvre les structures organisationnelles, les styles de leadership et les théories de motivation pour bien gérer le personnel.","mfe":"Kouver strikitir organizasyonel, stil lidership ek teori motivasyon pou byin zer dimounn."}'::jsonb),
('dcd35884-bbc8-5aef-a423-bdc468411dc0', 'business', 10, 5, '{"en":"Human resource management","fr":"Gestion des ressources humaines","mfe":"Zestion resours imin"}'::jsonb, '{"en":"Focuses on recruiting, training, appraising and rewarding employees to build an effective workforce.","fr":"Se concentre sur le recrutement, la formation, l''évaluation et la rémunération des employés pour bâtir une main-d''œuvre efficace.","mfe":"Fokis lor rekritman, formasyon, evalyasyon ek remin­nerasyon anplwaye pou konstrir enn lafors travay efikas."}'::jsonb),
('b284be59-9a85-56b8-9898-9e72c78e936f', 'business', 10, 6, '{"en":"Marketing fundamentals","fr":"Principes fondamentaux du marketing","mfe":"Baz fondaman marketing"}'::jsonb, '{"en":"Introduces the purpose of marketing, market research methods and how businesses target customer segments.","fr":"Introduit le but du marketing, les méthodes d''étude de marché et le ciblage des segments de clientèle.","mfe":"Introdir bi marketing, metod resers marse ek kouma biznes vize segman kliyantel."}'::jsonb),
('57783173-964b-5fb4-abbc-4ec3127326cd', 'business', 10, 7, '{"en":"The marketing mix in practice","fr":"Le marketing mix en pratique","mfe":"Melanz marketing dan pratik"}'::jsonb, '{"en":"Explores how product, price, promotion and place decisions combine to satisfy customers and achieve business goals.","fr":"Explore comment les décisions de produit, prix, promotion et distribution se combinent pour satisfaire les clients.","mfe":"Explor kouma desizyon prodwi, pri, promosyon ek plas kombine pou satisfer kliyan."}'::jsonb),
('59e7a780-9f72-5bd1-8385-3bd6419ed0a0', 'business', 11, 1, '{"en":"Marketing strategy and the marketing mix","fr":"Stratégie marketing et le marketing mix","mfe":"Stratezi marketing ek marketing mix"}'::jsonb, '{"en":"Building on Grade 10 basics, students explore how businesses develop marketing strategies using market research, segmentation and the marketing mix to compete effectively in Mauritian and global markets.","fr":"En s''appuyant sur les bases de la Grade 10, les élèves explorent comment les entreprises développent des stratégies marketing en utilisant l''étude de marché, la segmentation et le marketing mix pour rivaliser efficacement sur les marchés mauriciens et mondiaux.","mfe":"An baze lor bann baz Grade 10, bann elev explor kouma bann antrepriz devlop stratezi marketing par servi rises marse, segmantasyon ek marketing mix pou konkirans efikasman lor marse Moris ek internasyonal."}'::jsonb),
('ce7dc289-1467-564f-ba27-e371fa9d78a3', 'business', 11, 2, '{"en":"Operations management","fr":"Gestion des opérations","mfe":"Zestion operasyon"}'::jsonb, '{"en":"Students learn how businesses organise production, manage quality and control costs to operate efficiently, using examples from Mauritian manufacturing and services.","fr":"Les élèves apprennent comment les entreprises organisent la production, gèrent la qualité et contrôlent les coûts pour fonctionner efficacement, avec des exemples issus de l''industrie et des services mauriciens.","mfe":"Bann elev aprann kouma bann antrepriz organiz prodiksyon, zer kalite ek kontrol depans pou operer efikasman, avek bann exanp dan lindistri ek servis Moris."}'::jsonb),
('54d44dce-c5a4-5d9d-b9a5-0a9560636453', 'business', 11, 3, '{"en":"Financial information and decision making","fr":"Information financière et prise de décision","mfe":"Lenformasyon finansye ek prizdesizyon"}'::jsonb, '{"en":"Students develop skills to interpret financial statements, calculate costs and profits, and use financial information to support business decisions.","fr":"Les élèves développent des compétences pour interpréter les états financiers, calculer les coûts et les profits, et utiliser l''information financière pour appuyer les décisions commerciales.","mfe":"Bann elev devlop konpetans pou interprete deklarasyon finansye, kalkil depans ek profi, ek servi lenformasyon finansye pou siport desizyon biznes."}'::jsonb),
('3218fd16-baf0-5917-99f4-c179c507a223', 'business', 11, 4, '{"en":"Human resource management","fr":"Gestion des ressources humaines","mfe":"Zestion resours imin"}'::jsonb, '{"en":"Students examine how businesses recruit, train, motivate and manage employees to build an effective workforce in Mauritius''s diverse workplace.","fr":"Les élèves examinent comment les entreprises recrutent, forment, motivent et gèrent les employés pour constituer une main-d''œuvre efficace dans le milieu de travail diversifié de Maurice.","mfe":"Bann elev examinn kouma bann antrepriz rekrit, form, motiv ek zer anplway pou konstrir enn lafors travay efikas dan milye travay divers Moris."}'::jsonb),
('a5ade9c2-4060-543c-9589-74fb73b49531', 'business', 11, 5, '{"en":"External influences on business","fr":"Influences externes sur les entreprises","mfe":"Lenflians externn lor biznes"}'::jsonb, '{"en":"Students investigate how economic, legal, environmental and government factors shape business decisions and operations in Mauritius and beyond.","fr":"Les élèves étudient comment les facteurs économiques, juridiques, environnementaux et gouvernementaux façonnent les décisions et les opérations des entreprises à Maurice et ailleurs.","mfe":"Bann elev anket kouma bann fakter ekonomik, legal, anvironmantal ek gouvernman fason bann desizyon ek operasyon biznes dan Moris ek aletranze."}'::jsonb),
('24babfa7-f62d-5262-8d2d-005604fd6f0c', 'business', 11, 6, '{"en":"Business organisation, growth and strategy","fr":"Organisation, croissance et stratégie des entreprises","mfe":"Organizasyon, kwasans ek stratezi biznes"}'::jsonb, '{"en":"Students consolidate understanding of business structures, growth strategies and decision making as firms expand and adapt to change.","fr":"Les élèves consolident leur compréhension des structures d''entreprise, des stratégies de croissance et de la prise de décision à mesure que les entreprises se développent et s''adaptent au changement.","mfe":"Bann elev konsolid konpreansyon lor striktir biznes, stratezi kwasans ek prizdesizyon kan bann konpayni agrandi ek adapte ar sanzman."}'::jsonb),
('449f0d78-7aea-5893-9204-a3a50bb20e6c', 'business', 11, 7, '{"en":"Examination preparation and case study skills","fr":"Préparation aux examens et compétences en étude de cas","mfe":"Preparasyon lexame ek konpetans etid ka"}'::jsonb, '{"en":"Students consolidate the full syllabus, practise applying business concepts to case studies and develop exam techniques for the O Level examination.","fr":"Les élèves consolident l''ensemble du programme, s''entraînent à appliquer des concepts commerciaux à des études de cas et développent des techniques d''examen pour l''examen O Level.","mfe":"Bann elev konsolid tout program, pratik applik konsep biznes lor etid ka ek devlop teknik lexame pou lexame O Level."}'::jsonb),
('f5761daf-d2e9-5e8b-bc4c-543c6b559171', 'business', 12, 1, '{"en":"Enterprise and business structures","fr":"Entrepreneuriat et structures d''entreprise","mfe":"Lantreprenaria ek striktir biznes"}'::jsonb, '{"en":"An introduction to why businesses exist, the qualities of successful entrepreneurs, and the main legal forms of business ownership used in Mauritius and internationally.","fr":"Une introduction sur les raisons d''existence des entreprises, les qualités des entrepreneurs performants et les principales formes juridiques d''entreprise utilisées à Maurice et à l''international.","mfe":"Enn lentrodiksion lor kifer biznes existe, bann kalite bon entrepreneur, ek bann prinsipal form legal proprieter biznes servi Moris ek internasional."}'::jsonb),
('ff3db48a-66de-56bc-8b55-29e8672f7c20', 'business', 12, 2, '{"en":"Business objectives and stakeholders","fr":"Objectifs de l''entreprise et parties prenantes","mfe":"Lobzektif biznes ek parti prenant"}'::jsonb, '{"en":"Explores how businesses set aims and objectives, the different groups with an interest in a business, and the growing importance of ethical and socially responsible behaviour.","fr":"Explore comment les entreprises fixent leurs buts et objectifs, les différents groupes ayant un intérêt dans l''entreprise, et l''importance croissante d''un comportement éthique et socialement responsable.","mfe":"Explor kouma biznes etabli bi ek lobzektif, diferan group ki ena lintere dan enn biznes, ek limportans ki pe grandi lor konportman etik ek responsabilite sosial."}'::jsonb),
('d048c0cb-24a3-5533-af4d-94faa0770f4f', 'business', 12, 3, '{"en":"The external business environment","fr":"L''environnement externe de l''entreprise","mfe":"Lanvironnman ekstern biznes"}'::jsonb, '{"en":"Examines how economic conditions, government policy, social change, technology and competition shape business decision-making.","fr":"Examine comment les conditions économiques, la politique gouvernementale, les changements sociaux, la technologie et la concurrence influencent les décisions de l''entreprise.","mfe":"Examinn kouma kondision ekonomik, politik gouvernman, sanzman sosial, teknolozi ek konkirans influans desizion biznes."}'::jsonb),
('964ef110-a7a3-5ec9-9a62-c07bbc977a79', 'business', 12, 4, '{"en":"Marketing","fr":"Le marketing","mfe":"Marketing"}'::jsonb, '{"en":"Covers the role of marketing, market research techniques, and how businesses use the marketing mix to meet customer needs and achieve objectives.","fr":"Couvre le rôle du marketing, les techniques d''étude de marché et l''utilisation du marketing mix par les entreprises pour répondre aux besoins des clients et atteindre leurs objectifs.","mfe":"Kouver rol marketing, teknik letid marse, ek kouma biznes servi marketing mix pou satisfer bezwen kliyan ek atenn lobzektif."}'::jsonb),
('c9012ad4-fb76-588c-8843-faac20644b43', 'business', 12, 5, '{"en":"Operations management","fr":"Gestion des opérations","mfe":"Zestion operasion"}'::jsonb, '{"en":"Looks at how businesses organise production, manage quality, choose locations and control stock to operate efficiently.","fr":"Étudie comment les entreprises organisent la production, gèrent la qualité, choisissent l''emplacement et contrôlent les stocks pour fonctionner efficacement.","mfe":"Get kouma biznes organiz prodiksion, zer kalite, swazir lokasyon ek kontrol stok pou opere efikasman."}'::jsonb),
('e15712a8-b376-5c10-94c4-742adf936933', 'business', 12, 6, '{"en":"Human resource management","fr":"Gestion des ressources humaines","mfe":"Zestion resours imin"}'::jsonb, '{"en":"Examines how businesses structure their workforce, recruit and motivate employees, and manage training and performance.","fr":"Examine comment les entreprises structurent leur main-d''œuvre, recrutent et motivent leurs employés, et gèrent la formation et la performance.","mfe":"Examinn kouma biznes striktir zot travayer, rekrit ek motiv anplwaye, ek zer formasion ek performans."}'::jsonb),
('88943d10-d5cf-5b0a-88f1-6750f26a8626', 'business', 12, 7, '{"en":"Finance and accounting","fr":"Finance et comptabilité","mfe":"Finans ek kontabilite"}'::jsonb, '{"en":"Introduces sources of finance, costing, budgeting and financial statements that help businesses plan, control and evaluate their performance.","fr":"Introduit les sources de financement, les coûts, la budgétisation et les états financiers qui aident les entreprises à planifier, contrôler et évaluer leur performance.","mfe":"Introdir sours finansman, kalkil kou, bidzet ek deklarasion finansye ki ed biznes planifie, kontrole ek evalie zot performans."}'::jsonb),
('a1d26b6d-eb02-5deb-ba57-97364886398a', 'business', 13, 1, '{"en":"Strategic analysis and position","fr":"Analyse et position stratégique","mfe":"Analiz ek pozisyon stratezik"}'::jsonb, '{"en":"Students learn how businesses assess their current strategic position by analysing internal resources and the external environment, using models to inform strategic decisions.","fr":"Les élèves apprennent comment les entreprises évaluent leur position stratégique actuelle en analysant les ressources internes et l''environnement externe, à l''aide de modèles pour éclairer les décisions stratégiques.","mfe":"Bann elev aprann kouma bann biznes evalie zot pozisyon stratezik aktyel par analize resours intern ek lanvironnman ekstern, servi bann model pou eklerer desizion stratezik."}'::jsonb),
('4f295437-cd31-5dd9-aff9-880288081eec', 'business', 13, 2, '{"en":"Strategic choice","fr":"Choix stratégique","mfe":"Swa stratezik"}'::jsonb, '{"en":"This unit examines how businesses select strategies, including competitive strategies, growth options and decision-making techniques to evaluate alternatives.","fr":"Cette unité examine comment les entreprises sélectionnent des stratégies, y compris les stratégies concurrentielles, les options de croissance et les techniques de prise de décision pour évaluer les alternatives.","mfe":"Sa linite-la examinn kouma bann biznes swazir zot stratezi, ki inklir stratezi konkirans, opsyon kwasans ek teknik pran desizion pou evalie bann alternativ."}'::jsonb),
('566f54b5-9c5a-565c-822a-19973bb3e70a', 'business', 13, 3, '{"en":"Strategic implementation","fr":"Mise en œuvre stratégique","mfe":"Mizanplas stratezik"}'::jsonb, '{"en":"Students explore how strategies are implemented, the management of change, and the factors that determine success or failure of strategic plans.","fr":"Les élèves explorent comment les stratégies sont mises en œuvre, la gestion du changement et les facteurs qui déterminent le succès ou l''échec des plans stratégiques.","mfe":"Bann elev explor kouma bann stratezi implimante, gestion sanzman, ek bann fakter ki determinn sikse ouswa ek bann plan stratezik."}'::jsonb),
('81ef4e46-236d-5ec4-a89d-567830e2daa7', 'business', 13, 4, '{"en":"Marketing strategy","fr":"Stratégie marketing","mfe":"Stratezi marketing"}'::jsonb, '{"en":"This unit develops strategic marketing planning, segmentation and positioning, and digital marketing approaches used by businesses to compete effectively.","fr":"Cette unité développe la planification marketing stratégique, la segmentation et le positionnement, ainsi que les approches de marketing numérique utilisées par les entreprises pour rivaliser efficacement.","mfe":"Sa linite-la devlop planifikasyon marketing stratezik, segmentasyon ek pozisyonnman, ek bann laprosh marketing dizital ki bann biznes servi pou konpetitif efikasman."}'::jsonb),
('6a896fe7-6e52-58eb-82aa-126c08f79a93', 'business', 13, 5, '{"en":"Operations strategy","fr":"Stratégie des opérations","mfe":"Stratezi operasyon"}'::jsonb, '{"en":"Students study strategic operational decisions including innovation, quality management, location, and supply chain strategies that support competitiveness.","fr":"Les élèves étudient les décisions opérationnelles stratégiques, notamment l''innovation, la gestion de la qualité, la localisation et les stratégies de chaîne d''approvisionnement qui soutiennent la compétitivité.","mfe":"Bann elev etidie bann desizion operasyonel stratezik ki inklir inovasyon, zestion kalite, lokalizasyon, ek stratezi sipla-chain ki soutenir konpetitivite."}'::jsonb),
('a3324f49-6cf0-57df-99ce-3ebbc739d93b', 'business', 13, 6, '{"en":"Finance strategy","fr":"Stratégie financière","mfe":"Stratezi finansye"}'::jsonb, '{"en":"This unit covers strategic financial objectives, sources of finance, investment appraisal, and the use of financial information to support strategic decisions.","fr":"Cette unité couvre les objectifs financiers stratégiques, les sources de financement, l''évaluation des investissements et l''utilisation de l''information financière pour appuyer les décisions stratégiques.","mfe":"Sa linite-la kouver obzektif finansye stratezik, sours finansman, evalyasyon lenvestisman, ek servis linformasyon finansye pou soutenir desizion stratezik."}'::jsonb),
('54284336-3497-5494-8448-8987f1377cff', 'business', 13, 7, '{"en":"Human resource strategy","fr":"Stratégie des ressources humaines","mfe":"Stratezi resours imin"}'::jsonb, '{"en":"Students examine strategic human resource decisions including workforce planning, organisational structure, leadership and managing culture and change.","fr":"Les élèves examinent les décisions stratégiques en matière de ressources humaines, notamment la planification des effectifs, la structure organisationnelle, le leadership et la gestion de la culture et du changement.","mfe":"Bann elev examinn desizion stratezik resours imin ki inklir planifikasyon lame-douv, striktir organizasyonel, leadership ek zestion kiltir ek sanzman."}'::jsonb),
('e12ea7d2-8424-5bca-a5b1-69ad7b6d3f63', 'business', 13, 8, '{"en":"Globalisation and international strategy","fr":"Mondialisation et stratégie internationale","mfe":"Globalizasyon ek stratezi internasyonal"}'::jsonb, '{"en":"This unit explores globalisation, multinational business strategy, trade policy, exchange rates and ethical considerations in international business.","fr":"Cette unité explore la mondialisation, la stratégie des entreprises multinationales, la politique commerciale, les taux de change et les considérations éthiques dans les affaires internationales.","mfe":"Sa linite-la explor globalizasyon, stratezi biznes miltinasyonal, politik komers, to sanz, ek konsiderasyon etik dan biznes internasyonal."}'::jsonb),
('a6dba2ba-cba7-5448-b741-cf3b4548de8e', 'chemistry', 7, 1, '{"en":"Introducing science and the laboratory","fr":"Introduction à la science et au laboratoire","mfe":"Introdiksyon a lasyans ek laboratwar"}'::jsonb, '{"en":"Students learn what science is, how scientists work, and how to stay safe while using laboratory equipment.","fr":"Les élèves découvrent ce qu''est la science, comment travaillent les scientifiques, et comment rester en sécurité en utilisant le matériel de laboratoire.","mfe":"Bann etidyan aprann ki lasyans ete, kouma bann syantis travay, ek kouma reste an sekirite kan zot servi materyel laboratwar."}'::jsonb),
('359c5075-c7ef-5be7-90d7-90910023f2dc', 'chemistry', 7, 2, '{"en":"Matter and its states","fr":"La matière et ses états","mfe":"Matyer ek so leta"}'::jsonb, '{"en":"Students explore the properties of solids, liquids and gases and how matter changes state.","fr":"Les élèves explorent les propriétés des solides, liquides et gaz et comment la matière change d''état.","mfe":"Bann etidyan explor propriete solid, likid ek gaz ek kouma matyer sanz leta."}'::jsonb),
('1578fd5a-9662-5992-8b38-b5b9a8d921a6', 'chemistry', 7, 3, '{"en":"Elements, compounds and mixtures","fr":"Éléments, composés et mélanges","mfe":"Element, konpoze ek melanz"}'::jsonb, '{"en":"Students distinguish between elements, compounds and mixtures and learn to represent substances using symbols.","fr":"Les élèves font la distinction entre éléments, composés et mélanges et apprennent à représenter les substances par des symboles.","mfe":"Bann etidyan diferansye element, konpoze ek melanz ek aprann reprezant sibstans avek senbol."}'::jsonb),
('a101d2bf-386c-5715-9018-091cdcb422f4', 'chemistry', 7, 4, '{"en":"Separating mixtures","fr":"Séparer les mélanges","mfe":"Separ melanz"}'::jsonb, '{"en":"Students learn practical techniques used to separate different kinds of mixtures.","fr":"Les élèves apprennent les techniques pratiques utilisées pour séparer différents types de mélanges.","mfe":"Bann etidyan aprann bann teknik pratik pou separ diferan tip melanz."}'::jsonb),
('f0694826-4f4f-5218-bae8-3f666670d9dc', 'chemistry', 7, 5, '{"en":"Acids, bases and indicators","fr":"Acides, bases et indicateurs","mfe":"Asid, baz ek endikater"}'::jsonb, '{"en":"Students investigate the properties of acids and bases and how indicators are used to identify them.","fr":"Les élèves étudient les propriétés des acides et des bases et comment les indicateurs sont utilisés pour les identifier.","mfe":"Bann etidyan gete propriete asid ek baz ek kouma endikater servi pou idantifye zot."}'::jsonb),
('623e151b-dd6b-511e-8f01-b1f552d022dd', 'chemistry', 7, 6, '{"en":"Introducing chemical reactions","fr":"Introduction aux réactions chimiques","mfe":"Introdiksyon a reaksyon sime"}'::jsonb, '{"en":"Students learn to recognise chemical changes and represent simple reactions.","fr":"Les élèves apprennent à reconnaître les changements chimiques et à représenter des réactions simples.","mfe":"Bann etidyan aprann rekonet sanzman sime ek reprezant reaksyon senp."}'::jsonb),
('50ccd985-e025-5d2a-b480-45b008e181ef', 'chemistry', 7, 7, '{"en":"Metals and non-metals","fr":"Métaux et non-métaux","mfe":"Metal ek non-metal"}'::jsonb, '{"en":"Students compare the properties of metals and non-metals and explore their everyday uses.","fr":"Les élèves comparent les propriétés des métaux et des non-métaux et explorent leurs usages quotidiens.","mfe":"Bann etidyan konpar propriete metal ek non-metal ek explor zot lizaz o zour lezour."}'::jsonb),
('618095b8-ba38-5711-b23e-4056fd2ba169', 'chemistry', 8, 1, '{"en":"States of matter and particle theory","fr":"Les états de la matière et la théorie particulaire","mfe":"Leta lamater ek teori partikil"}'::jsonb, '{"en":"Students explore the three states of matter and use the particle model to explain heating, cooling, melting and boiling.","fr":"Les élèves explorent les trois états de la matière et utilisent le modèle particulaire pour expliquer le chauffage, le refroidissement, la fusion et l''ébullition.","mfe":"Bann elev explor le trwa leta lamater ek servi model partikil pou explik sofaz, refrwadisman, fonn ek bwiyaz."}'::jsonb),
('0b18b892-98ba-5831-8941-696e1fa23fa4', 'chemistry', 8, 2, '{"en":"Elements, compounds and mixtures","fr":"Éléments, composés et mélanges","mfe":"Elman, konpoze ek melanz"}'::jsonb, '{"en":"This unit introduces elements, compounds and mixtures and how to classify materials found in everyday Mauritian life.","fr":"Cette unité présente les éléments, les composés et les mélanges ainsi que la classification des matériaux du quotidien mauricien.","mfe":"Sa linite-la introdir elman, konpoze ek melanz ek kimanyer klasifie materyo dan lavi kotidyen Moris."}'::jsonb),
('0e783549-5a1d-5717-afc3-553edf0efca5', 'chemistry', 8, 3, '{"en":"Separating mixtures","fr":"La séparation des mélanges","mfe":"Separasyon melanz"}'::jsonb, '{"en":"Students learn practical techniques used to separate mixtures, linking methods to properties of the substances involved.","fr":"Les élèves apprennent des techniques pratiques pour séparer les mélanges, en reliant les méthodes aux propriétés des substances.","mfe":"Bann elev aprann teknik pratik pou separe melanz, an lyene metod ar propriete sibstans."}'::jsonb),
('228ec4da-9f79-577e-90d6-34ec0de114bd', 'chemistry', 8, 4, '{"en":"Atoms and the periodic table","fr":"Les atomes et le tableau périodique","mfe":"Zatom ek tablo periodik"}'::jsonb, '{"en":"This unit introduces the basic structure of atoms and how elements are arranged in the periodic table.","fr":"Cette unité présente la structure de base des atomes et l''organisation des éléments dans le tableau périodique.","mfe":"Sa linite-la introdir striktir debaz zatom ek kimanyer elman aranze dan tablo periodik."}'::jsonb),
('0da6686e-fbd3-5f0d-b572-6084b01f4f71', 'chemistry', 8, 5, '{"en":"Acids, bases and indicators","fr":"Acides, bases et indicateurs","mfe":"Asid, baz ek endikater"}'::jsonb, '{"en":"Students investigate acids and bases, use indicators to test substances and relate pH to everyday materials.","fr":"Les élèves étudient les acides et les bases, utilisent des indicateurs pour tester des substances et relient le pH aux matériaux du quotidien.","mfe":"Bann elev examinn asid ek baz, servi endikater pou teste sibstans ek lyene pH ar materyo lavi toulezour."}'::jsonb),
('2910afdd-e25a-5a94-b37c-28982c2e7289', 'chemistry', 8, 6, '{"en":"Metals and non-metals","fr":"Métaux et non-métaux","mfe":"Metal ek non-metal"}'::jsonb, '{"en":"This unit compares physical and chemical properties of metals and non-metals and looks at simple metal reactions.","fr":"Cette unité compare les propriétés physiques et chimiques des métaux et des non-métaux et examine des réactions simples des métaux.","mfe":"Sa linite-la konpar propriete fizik ek kimik metal ek non-metal ek gete reaksyon senp metal."}'::jsonb),
('82dd7059-c043-5161-a1f6-94b09bb2ab60', 'chemistry', 8, 7, '{"en":"Physical and chemical changes","fr":"Changements physiques et chimiques","mfe":"Sanzman fizik ek kimik"}'::jsonb, '{"en":"Students distinguish between physical and chemical changes and learn to recognise signs of chemical reactions.","fr":"Les élèves distinguent les changements physiques et chimiques et apprennent à reconnaître les signes des réactions chimiques.","mfe":"Bann elev distenge sanzman fizik ek kimik ek aprann rekonet siyn reaksyon kimik."}'::jsonb),
('2a82120a-c29d-5b51-844c-6123d4caa1a5', 'chemistry', 9, 1, '{"en":"The particulate nature of matter","fr":"La nature particulaire de la matière","mfe":"Nature partikilaire lamater"}'::jsonb, '{"en":"Students explore how matter is made of tiny particles, explaining states of matter, diffusion and changes of state using the kinetic particle theory.","fr":"Les élèves découvrent comment la matière est constituée de minuscules particules, en expliquant les états de la matière, la diffusion et les changements d''état grâce à la théorie cinétique des particules.","mfe":"Bann elev explor kouma lamater fer ar bann tigit partikil, e explik bann eta lamater, difizyon ek sanzman eta ar teori sinetik bann partikil."}'::jsonb),
('4b332b5a-cc5c-5fc4-b2e1-0449a4765e86', 'chemistry', 9, 2, '{"en":"Atoms, elements and the periodic table","fr":"Les atomes, les éléments et le tableau périodique","mfe":"Bann atom, elman ek tablo peryodik"}'::jsonb, '{"en":"This unit introduces atomic structure, subatomic particles and isotopes, and shows how elements are arranged in the periodic table according to their properties.","fr":"Cette unité introduit la structure atomique, les particules subatomiques et les isotopes, et montre comment les éléments sont organisés dans le tableau périodique selon leurs propriétés.","mfe":"Sa linite-la introdir striktir atomik, bann partikil sou-atomik ek izotop, e montre kouma bann elman aranze dan tablo peryodik selon zot prop."}'::jsonb),
('ba4320de-2ca9-5f0e-919d-f062a78e57d0', 'chemistry', 9, 3, '{"en":"Mixtures, elements and compounds","fr":"Mélanges, éléments et composés","mfe":"Melanz, elman ek konpoze"}'::jsonb, '{"en":"Students distinguish elements, compounds and mixtures, and learn practical techniques for separating substances found in everyday and local contexts.","fr":"Les élèves distinguent les éléments, les composés et les mélanges, et apprennent des techniques pratiques pour séparer des substances dans des contextes quotidiens et locaux.","mfe":"Bann elev distingie elman, konpoze ek melanz, e aprann bann teknik pratik pou separ substans dan kontex tou-le-zour ek lokal."}'::jsonb),
('bee2a519-9fe3-5302-ba7d-fd9a584b9584', 'chemistry', 9, 4, '{"en":"Chemical bonding","fr":"La liaison chimique","mfe":"Lyezon simik"}'::jsonb, '{"en":"This unit explains how atoms combine through ionic and covalent bonding and links bonding type to the physical properties of substances.","fr":"Cette unité explique comment les atomes se combinent par des liaisons ioniques et covalentes et relie le type de liaison aux propriétés physiques des substances.","mfe":"Sa linite-la explik kouma bann atom kombine par lyezon ionik ek kovalan, e lir tip lyezon ar prop fizik bann substans."}'::jsonb),
('96254e89-9efc-5c3b-99ad-e5e28aa27201', 'chemistry', 9, 5, '{"en":"Chemical reactions and equations","fr":"Les réactions chimiques et les équations","mfe":"Reaksyon simik ek ekwasyon"}'::jsonb, '{"en":"Students learn to represent chemical reactions using word and symbol equations, and explore different types of chemical change.","fr":"Les élèves apprennent à représenter les réactions chimiques à l''aide d''équations en mots et en symboles, et explorent différents types de changements chimiques.","mfe":"Bann elev aprann reprezant reaksyon simik ar ekwasyon mo ek senbol, e explor diferan tip sanzman simik."}'::jsonb),
('37d7b176-c4e2-511b-8338-f100bcb6b350', 'chemistry', 9, 6, '{"en":"Acids, bases and salts","fr":"Acides, bases et sels","mfe":"Asid, baz ek sel"}'::jsonb, '{"en":"This unit covers the properties of acids and bases, the pH scale, neutralisation and simple methods of preparing salts.","fr":"Cette unité couvre les propriétés des acides et des bases, l''échelle de pH, la neutralisation et des méthodes simples de préparation des sels.","mfe":"Sa linite-la kouver prop asid ek baz, lesel pH, netralizasyon ek metod senp pou prepar sel."}'::jsonb),
('275515bf-e1f9-5153-b92a-de4134e61482', 'chemistry', 9, 7, '{"en":"Metals and their reactivity","fr":"Les métaux et leur réactivité","mfe":"Metal ek zot reaktivite"}'::jsonb, '{"en":"Students study the physical properties of metals, compare their reactivity, and get an introduction to how metals are extracted from ores.","fr":"Les élèves étudient les propriétés physiques des métaux, comparent leur réactivité et découvrent une introduction à l''extraction des métaux à partir de leurs minerais.","mfe":"Bann elev etidye prop fizik metal, konpar zot reaktivite, e gagn enn introdiksyon lor kouma metal ekstre depi minre."}'::jsonb),
('1e9a9a30-bf89-5ac5-bc92-5699dd72eb64', 'chemistry', 9, 8, '{"en":"Air, water and environmental chemistry","fr":"L''air, l''eau et la chimie environnementale","mfe":"Ler, delo ek simi lanvironnman"}'::jsonb, '{"en":"This unit examines the composition of air and water, methods of testing purity, and the chemistry behind environmental issues relevant to Mauritius.","fr":"Cette unité examine la composition de l''air et de l''eau, les méthodes de test de pureté, et la chimie derrière les problèmes environnementaux pertinents pour Maurice.","mfe":"Sa linite-la examin konpozision ler ek delo, metod pou teste pirte, ek simi ki dan problem lanvironnman relevan pou Moris."}'::jsonb),
('940d92d2-cbfd-55f4-b7da-6c8aa94c21ad', 'chemistry', 10, 1, '{"en":"States of matter and experimental techniques","fr":"États de la matière et techniques expérimentales","mfe":"Leta lamater ek teknik esperimantal"}'::jsonb, '{"en":"This unit revises the three states of matter through kinetic particle theory and introduces key laboratory techniques used to separate and purify substances.","fr":"Cette unité révise les trois états de la matière à travers la théorie cinétique des particules et présente les principales techniques de laboratoire utilisées pour séparer et purifier des substances.","mfe":"Sa linite-la fer revizyon lor trwa leta lamater atraver teori sinetik patikil ek prezant bann teknik laboratwar inportan pou separ ek pirifye bann sibstans."}'::jsonb),
('8cf0031b-4e6b-5435-8251-42017289a422', 'chemistry', 10, 2, '{"en":"Atomic structure and periodic table","fr":"Structure atomique et tableau périodique","mfe":"Striktir atomik ek tablo periodik"}'::jsonb, '{"en":"Learners explore the structure of atoms, electron arrangement, isotopes and how these determine an element''s position and properties in the periodic table.","fr":"Les élèves explorent la structure des atomes, la disposition des électrons, les isotopes et comment ceux-ci déterminent la position et les propriétés d''un élément dans le tableau périodique.","mfe":"Bann elev pou explor striktir bann atom, arangman elektron, izotop ek kouma sa bann kitsoz-la determinn pozision ek proprite enn elman dan tablo periodik."}'::jsonb),
('437bbae5-a435-5270-9e6c-b1e0b191cae7', 'chemistry', 10, 3, '{"en":"Chemical bonding","fr":"Liaisons chimiques","mfe":"Lyezon simik"}'::jsonb, '{"en":"This unit explains how atoms combine through ionic, covalent and metallic bonding, and links bonding types to the physical properties of substances.","fr":"Cette unité explique comment les atomes se combinent par liaisons ioniques, covalentes et métalliques, et relie les types de liaisons aux propriétés physiques des substances.","mfe":"Sa linite-la explik kouma bann atom kombine par lyezon ionik, kovalan ek metalik, ek li relye tip lyezon ar proprite fizik bann sibstans."}'::jsonb),
('24ef936b-5000-55b8-934d-ae407e86a3f4', 'chemistry', 10, 4, '{"en":"Stoichiometry and chemical formulae","fr":"Stœchiométrie et formules chimiques","mfe":"Stekyometri ek formil simik"}'::jsonb, '{"en":"Students learn to calculate relative masses, use the mole concept, and apply chemical equations to solve quantitative problems in chemistry.","fr":"Les élèves apprennent à calculer les masses relatives, à utiliser le concept de mole et à appliquer les équations chimiques pour résoudre des problèmes quantitatifs en chimie.","mfe":"Bann elev aprann kalkil mas relatif, servi konsep mol, ek aplik ekwasyon simik pou rezoud problem kantitatif dan simi."}'::jsonb),
('e662ce32-dfdc-5f42-9a74-53eea289ba30', 'chemistry', 10, 5, '{"en":"Chemical energetics","fr":"Énergétique chimique","mfe":"Enerzetik simik"}'::jsonb, '{"en":"This unit examines energy changes during chemical reactions, distinguishing exothermic and endothermic processes and explaining them using bond energies.","fr":"Cette unité examine les changements d''énergie lors des réactions chimiques, en distinguant les processus exothermiques et endothermiques et en les expliquant à l''aide des énergies de liaison.","mfe":"Sa linite-la examine sanzman enerzi pandan reaksyon simik, distinge prosesis exotermik ek andotermik ek explik zot atraver enerzi lyezon."}'::jsonb),
('f642f68b-3922-560d-86da-73e3ad572c6d', 'chemistry', 10, 6, '{"en":"Rates of reaction","fr":"Vitesse de réaction","mfe":"Vites reaksyon"}'::jsonb, '{"en":"Learners investigate the factors that affect how fast chemical reactions occur and explain these effects using collision theory.","fr":"Les élèves étudient les facteurs qui influencent la vitesse des réactions chimiques et expliquent ces effets à l''aide de la théorie des collisions.","mfe":"Bann elev investige bann fakter ki afekte vites reaksyon simik ek explik zot par teori kolizyon."}'::jsonb),
('f1f9b77b-7844-5d14-965f-fd3d21f04a07', 'chemistry', 10, 7, '{"en":"Acids, bases and salts","fr":"Acides, bases et sels","mfe":"Asid, baz ek sel"}'::jsonb, '{"en":"This unit covers the properties of acids and bases, the pH scale, neutralisation, and methods for preparing common salts.","fr":"Cette unité couvre les propriétés des acides et des bases, l''échelle de pH, la neutralisation et les méthodes de préparation des sels courants.","mfe":"Sa linite-la kouver proprite asid ek baz, lesel pH, netralizasyon, ek metod pou prepar bann sel komen."}'::jsonb),
('5ff879a7-9e54-564c-9ae3-6484e9b90785', 'chemistry', 10, 8, '{"en":"Electrochemistry","fr":"Électrochimie","mfe":"Elektrosimi"}'::jsonb, '{"en":"Students learn the principles of electrolysis, including the electrolysis of molten compounds and aqueous solutions, and its industrial applications.","fr":"Les élèves apprennent les principes de l''électrolyse, y compris l''électrolyse des composés fondus et des solutions aqueuses, ainsi que ses applications industrielles.","mfe":"Bann elev aprann prinsip elektrolis, ki inklir elektrolis konpoze fonn ek solisyon akeu, ek zot aplikasyon endistriyel."}'::jsonb),
('83e9f6db-0f48-5098-9ff3-3a072d943a61', 'chemistry', 11, 1, '{"en":"Acids, bases and salts","fr":"Acides, bases et sels","mfe":"Lasid, baz ek sel"}'::jsonb, '{"en":"Students study the properties of acids and bases, the pH scale, and methods for preparing and identifying salts, building on qualitative reactions from Grade 10.","fr":"Les élèves étudient les propriétés des acides et des bases, l''échelle de pH, ainsi que les méthodes de préparation et d''identification des sels, en s''appuyant sur les réactions qualitatives vues en 4e.","mfe":"Bann elev etidie proprite lasid ek baz, lesel pH, ek bann metod pou prepar ek idantifie sel, an sapui lor bann reaksion kalitatif ki finn get dan Grade 10."}'::jsonb),
('66c3d38d-3c5c-5375-a0f1-fa2700d8e907', 'chemistry', 11, 2, '{"en":"Redox reactions and electrolysis","fr":"Réactions redox et électrolyse","mfe":"Reaksion redoks ek elektroliz"}'::jsonb, '{"en":"Students explore oxidation and reduction in terms of electron transfer, and examine electrolysis of molten and aqueous compounds with industrial applications.","fr":"Les élèves explorent l''oxydation et la réduction en termes de transfert d''électrons, et étudient l''électrolyse de composés fondus et aqueux avec leurs applications industrielles.","mfe":"Bann elev explor oksidasion ek reduksion an term transfer elektron, ek examine elektroliz konpoze fonn ek akez avek zot lapikasion endistriel."}'::jsonb),
('6824a53a-c695-5f1c-b2fc-5d8ea685bd93', 'chemistry', 11, 3, '{"en":"The periodic table","fr":"Le tableau périodique","mfe":"Tablo periodik"}'::jsonb, '{"en":"This unit examines the arrangement of the periodic table and trends in properties across periods and down groups, focusing on Groups I, VII and transition elements.","fr":"Cette unité examine l''organisation du tableau périodique et les tendances des propriétés à travers les périodes et les groupes, en se concentrant sur les groupes I, VII et les métaux de transition.","mfe":"Sa linite-la examine kouma tablo periodik organize ek bann tandans proprite atraver period ek group, ki fokis lor Group I, VII ek bann metal transision."}'::jsonb),
('d32bdbcf-f7e2-57d4-9afd-e1e7792cf349', 'chemistry', 11, 4, '{"en":"Metals and reactivity","fr":"Métaux et réactivité","mfe":"Metal ek reaktivite"}'::jsonb, '{"en":"Students study the reactivity series of metals, methods of extraction, common alloys, and how corrosion can be prevented.","fr":"Les élèves étudient la série de réactivité des métaux, les méthodes d''extraction, les alliages courants et les moyens de prévenir la corrosion.","mfe":"Bann elev etidie seri reaktivite metal, metod ekstraksion, bann aliaz komin ek kouma prevenir korozion."}'::jsonb),
('6dca8610-67a0-5b31-8b10-b42810491888', 'chemistry', 11, 5, '{"en":"Air, water and the environment","fr":"Air, eau et environnement","mfe":"Ler, delo ek lanvironnman"}'::jsonb, '{"en":"This unit covers the composition of air, causes and effects of pollution, water treatment, and key natural chemical cycles relevant to Mauritius.","fr":"Cette unité couvre la composition de l''air, les causes et effets de la pollution, le traitement de l''eau et les principaux cycles chimiques naturels pertinents pour Maurice.","mfe":"Sa linite-la kouver konpozision ler, koz ek lefe polision, tretman delo, ek bann sik simik natirel enportan pou Moris."}'::jsonb),
('79b246e5-cce0-5e66-9621-8be9cc9ca7d3', 'chemistry', 11, 6, '{"en":"Organic chemistry","fr":"Chimie organique","mfe":"Simi organik"}'::jsonb, '{"en":"Students are introduced to hydrocarbons, alcohols and carboxylic acids, and learn about polymers, laying the foundation for organic chemistry at higher levels.","fr":"Les élèves découvrent les hydrocarbures, les alcools et les acides carboxyliques, et étudient les polymères, posant les bases de la chimie organique pour les niveaux supérieurs.","mfe":"Bann elev dekouver idrokarbir, alkol ek lasid karboksilik, ek aprann lor polimer, ki poz bann baz pou simi organik dan bann nivo pli o."}'::jsonb),
('a54b5c44-70e5-5d78-a4f6-67951ba57ab7', 'chemistry', 11, 7, '{"en":"Industrial chemistry and analysis","fr":"Chimie industrielle et analyse","mfe":"Simi endistriel ek analiz"}'::jsonb, '{"en":"This final unit examines major industrial processes such as the Haber and Contact processes, qualitative analysis techniques, and revision of key stoichiometric calculations for the SC examination.","fr":"Cette dernière unité examine les principaux procédés industriels tels que les procédés Haber et Contact, les techniques d''analyse qualitative, ainsi qu''une révision des calculs stœchiométriques clés pour l''examen du SC.","mfe":"Sa dernie linite-la examine bann gran prosesis endistriel kouma prosesis Haber ek Contact, teknik analiz kalitatif, ek revizion bann kalkil stekiometrik kle pou lexame SC."}'::jsonb),
('2a7b1a00-f288-5ef5-a96f-fce1d61b7329', 'chemistry', 12, 1, '{"en":"Atomic structure","fr":"Structure atomique","mfe":"Striktir atomik"}'::jsonb, '{"en":"Explore the structure of the atom, isotopes, electron arrangement and periodic trends in ionisation energy, building the foundation for AS Level chemistry.","fr":"Explorer la structure de l''atome, les isotopes, la disposition des électrons et les tendances périodiques de l''énergie d''ionisation, base de la chimie de niveau AS.","mfe":"Explor striktir atom, izotop, arondisman elektron ek tandans periodik dan energi ionizasion, ki form baz kimi AS Level."}'::jsonb),
('5f44e040-fa36-58db-b689-6567f743cdbe', 'chemistry', 12, 2, '{"en":"Atoms, moles and stoichiometry","fr":"Atomes, moles et stœchiométrie","mfe":"Atom, mol ek stesiometri"}'::jsonb, '{"en":"Develop quantitative chemistry skills including the mole concept, formulae and calculations used in titrations and reacting quantities.","fr":"Développer des compétences en chimie quantitative, notamment le concept de mole, les formules et les calculs utilisés dans les titrages et les quantités réactionnelles.","mfe":"Devlop konpetans kimi kantitatif ki inklir konsep mol, formil ek kalkil servi dan titraz ek kantite reaksion."}'::jsonb),
('63a5615d-e47b-507e-894c-a9da0eb9cd7a', 'chemistry', 12, 3, '{"en":"Chemical bonding","fr":"Liaison chimique","mfe":"Lyezon simik"}'::jsonb, '{"en":"Study the types of chemical bonding, molecular shapes and intermolecular forces that determine the properties of substances.","fr":"Étudier les types de liaisons chimiques, les formes moléculaires et les forces intermoléculaires qui déterminent les propriétés des substances.","mfe":"Etidie diferan tip lyezon simik, form molekil ek fors entermolekiler ki determinn proprite sibstans."}'::jsonb),
('e6e1de19-bd2f-5bc3-a468-b3f5157c9bfb', 'chemistry', 12, 4, '{"en":"States of matter","fr":"États de la matière","mfe":"Leta matyer"}'::jsonb, '{"en":"Examine the gaseous, liquid and solid states, using the ideal gas equation and models of structure to explain physical properties.","fr":"Examiner les états gazeux, liquide et solide, en utilisant l''équation des gaz parfaits et des modèles de structure pour expliquer les propriétés physiques.","mfe":"Egzamin leta gaze, likid ek solid, servi lekwasion gaz ideal ek model striktir pou explik proprite fizik."}'::jsonb),
('af97b126-126b-5bf9-9df9-ae7ef6093d01', 'chemistry', 12, 5, '{"en":"Chemical energetics","fr":"Énergétique chimique","mfe":"Enerzetik simik"}'::jsonb, '{"en":"Investigate enthalpy changes in chemical reactions, applying Hess''s law and bond energies to calculate reaction enthalpies.","fr":"Étudier les variations d''enthalpie dans les réactions chimiques, en appliquant la loi de Hess et les énergies de liaison pour calculer les enthalpies de réaction.","mfe":"Envestig sanzman antalpi dan reaksion simik, aplik lalwa Hess ek energi lyezon pou kalkil antalpi reaksion."}'::jsonb),
('7dccdbfc-ffea-551e-9c3f-8cdfe8cb59a8', 'chemistry', 12, 6, '{"en":"Redox reactions and electrochemistry","fr":"Réactions redox et électrochimie","mfe":"Reaksion redoks ek elektrosimi"}'::jsonb, '{"en":"Understand oxidation and reduction processes, electrode potentials and electrochemical cells, with practical applications in Mauritius.","fr":"Comprendre les processus d''oxydation et de réduction, les potentiels d''électrode et les piles électrochimiques, avec des applications pratiques à Maurice.","mfe":"Konpran prosesis oksidasion ek redwiksion, potansiel elektrod ek pil elektrosimik, avek aplikasion pratik dan Moris."}'::jsonb),
('3029e64f-04d0-55f3-a70d-bff76aff3a23', 'chemistry', 12, 7, '{"en":"Reaction kinetics and chemical equilibria","fr":"Cinétique réactionnelle et équilibres chimiques","mfe":"Sinetik reaksion ek ekilib simik"}'::jsonb, '{"en":"Study the rates of chemical reactions and the concept of dynamic equilibrium, including equilibrium constants and Le Chatelier''s principle.","fr":"Étudier les vitesses des réactions chimiques et le concept d''équilibre dynamique, y compris les constantes d''équilibre et le principe de Le Chatelier.","mfe":"Etidie vites reaksion simik ek konsep ekilib dinamik, ki inklir konstant ekilib ek prinsip Le Chatelier."}'::jsonb),
('e801a422-c5cf-56ef-a27c-1c32836636fd', 'chemistry', 12, 8, '{"en":"Periodicity, group 2 and group 17","fr":"Périodicité, groupe 2 et groupe 17","mfe":"Periodisite, group 2 ek group 17"}'::jsonb, '{"en":"Explore periodic trends in physical and chemical properties, focusing on the reactivity of group 2 metals and group 17 halogens.","fr":"Explorer les tendances périodiques des propriétés physiques et chimiques, en se concentrant sur la réactivité des métaux du groupe 2 et des halogènes du groupe 17.","mfe":"Explor tandans periodik dan proprite fizik ek simik, konsantre lor reaktivite metal group 2 ek alozenn group 17."}'::jsonb),
('c2f98826-77ca-5299-854d-48047223efc2', 'chemistry', 13, 1, '{"en":"Lattice energy and Born-Haber cycles","fr":"Énergie réticulaire et cycles de Born-Haber","mfe":"Enerzi resosiye ek sik Born-Haber"}'::jsonb, '{"en":"Students explore energy changes in ionic compound formation using Born-Haber cycles, lattice energy, and enthalpy of solution and hydration.","fr":"Les élèves explorent les changements d''énergie lors de la formation des composés ioniques à l''aide des cycles de Born-Haber, de l''énergie réticulaire et des enthalpies de solution et d''hydratation.","mfe":"Bann elev explor sanzman lenerzi dan formasyon konpoze ionik atraver sik Born-Haber, enerzi resosiye, ek antalpi disolision ek idratasyon."}'::jsonb),
('b4c19f4f-1860-593d-9a63-c273ae9e029e', 'chemistry', 13, 2, '{"en":"Electrochemistry and electrode potentials","fr":"Électrochimie et potentiels d''électrode","mfe":"Elektrosimi ek potansyel elektrod"}'::jsonb, '{"en":"This unit covers standard electrode potentials, electrochemical cells, and their use in predicting redox reaction feasibility.","fr":"Cette unité couvre les potentiels d''électrode standard, les piles électrochimiques et leur utilisation pour prédire la faisabilité des réactions redox.","mfe":"Sa lini la kouver potansyel elektrod standard, pil elektrosimik, ek zot itilizasyon pou predir fezabilite reaksyon redoks."}'::jsonb),
('6eb17616-071c-5cf1-875a-68fb62e20e8d', 'chemistry', 13, 3, '{"en":"Further equilibria: acids, bases and buffers","fr":"Équilibres approfondis : acides, bases et tampons","mfe":"Ekilib avanse: asid, baz ek tanpon"}'::jsonb, '{"en":"Students extend equilibrium concepts to pH calculations, weak acids and bases, buffer solutions, and solubility product.","fr":"Les élèves approfondissent les concepts d''équilibre avec les calculs de pH, les acides et bases faibles, les solutions tampons et le produit de solubilité.","mfe":"Bann elev pouse konsep ekilib ar kalkil pH, asid ek baz feb, solisyon tanpon, ek prodwi solibilite."}'::jsonb),
('7d9b551d-abc6-5896-b979-5bd5e53be6c0', 'chemistry', 13, 4, '{"en":"Reaction kinetics and rate equations","fr":"Cinétique réactionnelle et équations de vitesse","mfe":"Sinetik reaksyon ek ekwasyon vites"}'::jsonb, '{"en":"This unit develops quantitative treatment of reaction rates, including orders of reaction, rate equations, and reaction mechanisms.","fr":"Cette unité développe un traitement quantitatif des vitesses de réaction, incluant les ordres de réaction, les équations de vitesse et les mécanismes réactionnels.","mfe":"Sa lini la devlop enn tretman kantitatif lor vites reaksyon, ki inklir lord reaksyon, ekwasyon vites, ek mekanism reaksyon."}'::jsonb),
('5f211bf4-cbd1-5fdd-ab7d-990ca88e7880', 'chemistry', 13, 5, '{"en":"Carbonyl compounds and carboxylic acids","fr":"Composés carbonylés et acides carboxyliques","mfe":"Konpoze karbonil ek asid karboksilik"}'::jsonb, '{"en":"Students study the structure, reactions and preparation of aldehydes, ketones, carboxylic acids and their derivatives.","fr":"Les élèves étudient la structure, les réactions et la préparation des aldéhydes, cétones, acides carboxyliques et leurs dérivés.","mfe":"Bann elev etidye striktir, reaksyon ek preparasyon aldeid, seton, asid karboksilik ek zot derive."}'::jsonb),
('a8c650b5-2d02-5b30-8c14-d766323fd3c7', 'chemistry', 13, 6, '{"en":"Nitrogen compounds and polymers","fr":"Composés azotés et polymères","mfe":"Konpoze nitrozenn ek polimer"}'::jsonb, '{"en":"This unit examines amines, amides, amino acids, and the chemistry of condensation and addition polymers.","fr":"Cette unité examine les amines, amides, acides aminés et la chimie des polymères de condensation et d''addition.","mfe":"Sa lini la examinn amin, amid, asid amine, ek simi polimer kondansasyon ek adisyon."}'::jsonb),
('bdc16af7-eab4-5d12-9f9a-d5aae44a830f', 'chemistry', 13, 7, '{"en":"Transition elements","fr":"Éléments de transition","mfe":"Element transisyon"}'::jsonb, '{"en":"Students explore the characteristic properties of transition elements, including variable oxidation states, complex ion formation and catalytic behaviour.","fr":"Les élèves explorent les propriétés caractéristiques des éléments de transition, incluant les états d''oxydation variables, la formation d''ions complexes et le comportement catalytique.","mfe":"Bann elev explor bann propriete karakteristik element transisyon, ki inklir eta oksidasyon variab, formasyon ion konplex ek konportman katalitik."}'::jsonb),
('58987613-8673-5bff-9ce4-d20c789d42e5', 'chemistry', 13, 8, '{"en":"Analytical techniques in chemistry","fr":"Techniques analytiques en chimie","mfe":"Teknik analitik dan simi"}'::jsonb, '{"en":"This unit introduces modern instrumental techniques used to identify and analyse chemical compounds, including chromatography and spectroscopy.","fr":"Cette unité introduit les techniques instrumentales modernes utilisées pour identifier et analyser les composés chimiques, y compris la chromatographie et la spectroscopie.","mfe":"Sa lini la introdir bann teknik enstrimantal modern ki servi pou idantifie ek analize konpoze simik, ki inklir kromatografi ek spektroskopi."}'::jsonb),
('d69ce5de-95e1-55e2-8a3e-4f5de747ced3', 'design-technology', 7, 1, '{"en":"Introduction to design and technology","fr":"Introduction à la technologie et au design","mfe":"Introdiksion ar design ek teknoloji"}'::jsonb, '{"en":"Students explore what design and technology means, why it matters in everyday life, and how it is studied in Mauritius, including careers linked to the subject.","fr":"Les élèves découvrent ce que signifie la technologie et le design, son importance dans la vie quotidienne, et comment elle est étudiée à Maurice, y compris les carrières liées à cette matière.","mfe":"Bann elev explor ki design ek teknoloji vedir, kifer li inportan dan lavi toulezour, ek kouma li anseigne dan Moris, avek bann karyer ki lie ar sa mater la."}'::jsonb),
('847c0f50-9968-5abd-8b98-2055d494cd61', 'design-technology', 7, 2, '{"en":"The design process","fr":"Le processus de conception","mfe":"Prosesis design"}'::jsonb, '{"en":"This unit introduces the stages of the design process, from identifying a problem to evaluating a finished solution, using simple everyday examples.","fr":"Cette unité présente les étapes du processus de conception, de l''identification d''un problème à l''évaluation d''une solution finale, à travers des exemples simples du quotidien.","mfe":"Sa linite la introduir bann letap dan prosesis design, depi idantifie enn problem ziska evalie enn solision final, ar bann lexanp senp dan lavi toulezour."}'::jsonb),
('b6e1c09b-f397-5c85-b52e-fd115b4b995a', 'design-technology', 7, 3, '{"en":"Materials and their properties","fr":"Les matériaux et leurs propriétés","mfe":"Materyo ek zot proprite"}'::jsonb, '{"en":"Students investigate common materials such as wood, metal, plastic and paper, learning about their properties and suitable uses in design projects.","fr":"Les élèves étudient des matériaux courants comme le bois, le métal, le plastique et le papier, en apprenant leurs propriétés et leurs usages appropriés dans des projets de conception.","mfe":"Bann elev examinn materyo komen kouma dibwa, metal, plastik ek papie, e aprann lor zot proprite ek kot bizin servi zot dan bann prozet design."}'::jsonb),
('dd6fb400-6637-5484-961f-87accf092365', 'design-technology', 7, 4, '{"en":"Tools, equipment and safety","fr":"Outils, équipement et sécurité","mfe":"Zouti, ekipman ek sekirite"}'::jsonb, '{"en":"This unit covers the safe and correct use of common hand tools and equipment used in design and technology projects.","fr":"Cette unité couvre l''utilisation sûre et correcte des outils manuels et de l''équipement couramment utilisés dans les projets de technologie et de design.","mfe":"Sa linite la kouver servi bann zouti amen ek ekipman komen dan bann prozet design ek teknoloji dan enn fason ki sekirize ek korek."}'::jsonb),
('a16e04f9-17a5-5898-8bbf-f246a901ffef', 'design-technology', 7, 5, '{"en":"Structures and mechanisms","fr":"Structures et mécanismes","mfe":"Striktir ek mekanism"}'::jsonb, '{"en":"Students explore how structures stay stable and how simple mechanisms transfer movement and force, applying this knowledge to build small models.","fr":"Les élèves découvrent comment les structures restent stables et comment des mécanismes simples transmettent le mouvement et la force, en appliquant ces connaissances pour construire de petits modèles.","mfe":"Bann elev explor kouma striktir reste stab ek kouma mekanism senp transfer mouvman ek fors, apre zot aplik sa konesans la pou konstrir ti model."}'::jsonb),
('6428d014-faec-5b9b-a516-8f79c8c4006a', 'design-technology', 7, 6, '{"en":"Graphic communication","fr":"Communication graphique","mfe":"Kominikasion grafik"}'::jsonb, '{"en":"This unit develops students'' ability to communicate design ideas clearly through sketches, labelled diagrams and simple technical drawings.","fr":"Cette unité développe la capacité des élèves à communiquer clairement leurs idées de conception à travers des croquis, des schémas annotés et des dessins techniques simples.","mfe":"Sa linite la devlop kapasite bann elev pou kominik zot lide design kler atraver bann kroki, diagram ki annan lezand, ek desin teknik senp."}'::jsonb),
('1f4a61f7-8565-5cd3-b49b-e2e34c2ecc5c', 'design-technology', 7, 7, '{"en":"Simple electrical systems","fr":"Systèmes électriques simples","mfe":"Sistem elektrik senp"}'::jsonb, '{"en":"Students learn the basics of electrical circuits and how simple components can be combined to create working products.","fr":"Les élèves apprennent les bases des circuits électriques et comment des composants simples peuvent être combinés pour créer des produits fonctionnels.","mfe":"Bann elev aprann baz sikwi elektrik ek kouma bann konpozan senp kapav konbine pou kree bann prodwi ki marse."}'::jsonb),
('dc48cb77-2407-5a17-87b3-f2862de6297c', 'design-technology', 7, 8, '{"en":"Introduction to textiles","fr":"Introduction aux textiles","mfe":"Introdiksion ar tekstil"}'::jsonb, '{"en":"This unit introduces basic textile materials, simple joining techniques and the role of textiles in Mauritian daily life and industry.","fr":"Cette unité présente les matériaux textiles de base, des techniques d''assemblage simples et le rôle des textiles dans la vie quotidienne et l''industrie mauricienne.","mfe":"Sa linite la introduir materyo tekstil debaz, teknik zwenn senp, ek rol tekstil dan lavi toulezour ek lindistri Moris."}'::jsonb),
('9ff9c7e7-4ce2-56e7-bbea-450a00fd414e', 'design-technology', 8, 1, '{"en":"The design process revisited","fr":"Le processus de conception revisité","mfe":"Reviziter proses konsepsyon"}'::jsonb, '{"en":"Students review and deepen their understanding of the design process, learning to analyse design briefs, conduct research and generate creative solutions to real-life problems in a Mauritian context.","fr":"Les élèves révisent et approfondissent leur compréhension du processus de conception, en apprenant à analyser des cahiers des charges, à faire des recherches et à générer des solutions créatives à des problèmes réels dans le contexte mauricien.","mfe":"Bann elev revize ek apronfondi zot konpreansyon lo proses konsepsyon, aprann analiz bann brief konsepsyon, fer resers ek dévlop bann solisyon kreatif pou problem reel dan kontex Moris."}'::jsonb),
('3de8ad36-6156-5c19-afb9-5b3adad14a0b', 'design-technology', 8, 2, '{"en":"Working with wood","fr":"Travailler le bois","mfe":"Travay avek dibwa"}'::jsonb, '{"en":"This unit introduces students to the properties of different woods and safe use of hand tools to shape, join and finish wooden products commonly made in Mauritius.","fr":"Cette unité présente aux élèves les propriétés de différents bois et l''utilisation sûre d''outils manuels pour façonner, assembler et finir des produits en bois couramment fabriqués à Maurice.","mfe":"Sa inite prezant bann elev bann propriete diferan bwa ek servi bann zouti manyel dan enn fason sekirize pou taye, azanse ek finalize bann prodwi an bwa ki komin fer Moris."}'::jsonb),
('a7ad2fb0-e7c5-5084-b0b2-797ab20181ad', 'design-technology', 8, 3, '{"en":"Metals and plastics in products","fr":"Métaux et plastiques dans les produits","mfe":"Metal ek plastik dan bann prodwi"}'::jsonb, '{"en":"Students explore the properties of metals and plastics, learning how these materials are processed and used to manufacture everyday products found in Mauritius.","fr":"Les élèves explorent les propriétés des métaux et des plastiques, en apprenant comment ces matériaux sont transformés et utilisés pour fabriquer des produits du quotidien trouvés à Maurice.","mfe":"Bann elev explor propriete metal ek plastik, aprann kouma sa bann material la trete ek servi pou fabrik bann prodwi toulezour ki trouve Moris."}'::jsonb),
('fca29b19-49e4-5a89-a760-66deb7b6b86d', 'design-technology', 8, 4, '{"en":"Structures around us","fr":"Les structures qui nous entourent","mfe":"Bann striktir otour nou"}'::jsonb, '{"en":"This unit examines how structures such as bridges, buildings and towers withstand forces, encouraging students to design and test simple structural models.","fr":"Cette unité examine comment les structures telles que les ponts, bâtiments et tours résistent aux forces, encourageant les élèves à concevoir et tester des modèles structurels simples.","mfe":"Sa inite examinn kouma bann striktir kouma pon, batiman ek tour reziste ar fors, ankouraz bann elev pou konsevwar ek teste bann modele striktirel senp."}'::jsonb),
('6e9ec8f4-c860-5302-adab-80474da112b2', 'design-technology', 8, 5, '{"en":"Mechanical systems and movement","fr":"Systèmes mécaniques et mouvement","mfe":"Sistem mekanik ek mouvman"}'::jsonb, '{"en":"Students learn about mechanisms such as levers, gears and cams that create and control movement in everyday devices and toys.","fr":"Les élèves apprennent les mécanismes tels que les leviers, engrenages et cames qui créent et contrôlent le mouvement dans les appareils et jouets quotidiens.","mfe":"Bann elev aprann bann mekanism kouma levie, angrenaz ek kam ki kree ek kontrol mouvman dan bann aparey ek zwe toulezour."}'::jsonb),
('8264a7de-7a42-59f6-b1f8-7c74d2eb43e3', 'design-technology', 8, 6, '{"en":"Introduction to electrical systems","fr":"Introduction aux systèmes électriques","mfe":"Entrodiksyon bann sistem elektrik"}'::jsonb, '{"en":"This unit introduces basic electrical circuits and components, allowing students to build and test simple circuits used in household devices.","fr":"Cette unité présente les circuits et composants électriques de base, permettant aux élèves de construire et tester des circuits simples utilisés dans les appareils domestiques.","mfe":"Sa inite prezant bann sirkwi ek konpozan elektrik debaz, permet bann elev construir ek teste bann sirkwi senp ki servi dan bann aparey dan lakaz."}'::jsonb),
('1106defd-c86e-5322-a05a-c6b05f90da40', 'design-technology', 8, 7, '{"en":"Graphic communication skills","fr":"Compétences en communication graphique","mfe":"Konpetans kominikasyon grafik"}'::jsonb, '{"en":"Students develop skills in freehand and technical drawing to communicate design ideas clearly, including simple use of computer-aided design tools.","fr":"Les élèves développent des compétences en dessin à main levée et technique pour communiquer clairement leurs idées de conception, y compris une utilisation simple des outils de CAO.","mfe":"Bann elev dévlop konpetans dan desine alamin ek desine teknik pou kominik bann lide konsepsyon kler, ki enkli enn servi senp bann zouti CAO."}'::jsonb),
('8c6e00c0-dfaa-5dab-97d0-a670dd982638', 'design-technology', 9, 1, '{"en":"The design process","fr":"Le processus de conception","mfe":"Prosesis konsepsyon"}'::jsonb, '{"en":"Students revisit and deepen their understanding of the design process, learning to identify problems, research solutions and evaluate outcomes systematically.","fr":"Les élèves revisitent et approfondissent leur compréhension du processus de conception, apprenant à identifier des problèmes, rechercher des solutions et évaluer les résultats de façon systématique.","mfe":"Bann elev revizit ek apronfondi zot konpreansyon lor prosesis konsepsyon, apran pou idantifie problem, rod solisyon ek evalie rezilta dan enn fason sistematik."}'::jsonb),
('ba97a5af-a6e2-5537-8323-314fd981e2e1', 'design-technology', 9, 2, '{"en":"Properties of materials","fr":"Propriétés des matériaux","mfe":"Proprite bann materyo"}'::jsonb, '{"en":"Students explore the physical and working properties of wood, metal and plastic, and how these properties influence material selection for products.","fr":"Les élèves explorent les propriétés physiques et de mise en œuvre du bois, du métal et du plastique, et comment ces propriétés influencent le choix des matériaux pour les produits.","mfe":"Bann elev explor proprite fizik ek travay dibwa, metal ek plastik, ek kouma sa bann proprite la enfliyans swa materyo pou prodwi."}'::jsonb),
('aa66c8e7-19ae-5bcb-98de-1108cbb3ea08', 'design-technology', 9, 3, '{"en":"Structures and forces","fr":"Structures et forces","mfe":"Striktir ek forse"}'::jsonb, '{"en":"Students investigate how structures resist forces and apply this understanding to design stable and strong constructions.","fr":"Les élèves étudient comment les structures résistent aux forces et appliquent cette compréhension pour concevoir des constructions stables et solides.","mfe":"Bann elev examinn kouma striktir rezist forse ek aplik sa konpreansyon pou konsevwar konstriksyon stab ek solid."}'::jsonb),
('3d9c4ed3-cb4a-5d46-b2b0-142733fb7c21', 'design-technology', 9, 4, '{"en":"Mechanisms and movement","fr":"Mécanismes et mouvement","mfe":"Mekanism ek mouvman"}'::jsonb, '{"en":"Students learn how mechanisms transform movement and force, exploring levers, gears, cams and linkages used in everyday devices.","fr":"Les élèves apprennent comment les mécanismes transforment le mouvement et la force, en explorant leviers, engrenages, cames et biellettes utilisés dans les appareils quotidiens.","mfe":"Bann elev aprann kouma mekanism transform mouvman ek forse, examine levie, angrenaz, kam ek lyezon itilize dan aparey ki servi toulezour."}'::jsonb),
('aa7e384f-ed43-5c1f-b9c9-483d937b10ff', 'design-technology', 9, 5, '{"en":"Electronics and control","fr":"Électronique et systèmes de contrôle","mfe":"Elektronik ek sistem kontrol"}'::jsonb, '{"en":"Students are introduced to basic electronic components and simple control systems used to automate everyday products.","fr":"Les élèves sont initiés aux composants électroniques de base et aux systèmes de contrôle simples utilisés pour automatiser les produits du quotidien.","mfe":"Bann elev fer konesans avek bann konpozan elektronik debaz ek sistem kontrol senp ki servi pou otomatiz prodwi toulezour."}'::jsonb),
('8d690d73-6449-54bc-9588-ba151a73ea74', 'design-technology', 9, 6, '{"en":"Graphic communication and drawing","fr":"Communication graphique et dessin","mfe":"Kominikasyon grafik ek desin"}'::jsonb, '{"en":"Students develop skills in freehand sketching, orthographic and pictorial drawing to communicate design ideas clearly.","fr":"Les élèves développent des compétences en croquis à main levée, dessin orthographique et en perspective pour communiquer clairement leurs idées de conception.","mfe":"Bann elev devlop konpetans dan croki lame lib, desin ortografik ek piktorial pou kominik lide konsepsyon dan enn fason kler."}'::jsonb),
('c871ece1-b5e9-5797-8070-58f3d2117b23', 'design-technology', 9, 7, '{"en":"Sustainable design and manufacture","fr":"Conception durable et fabrication","mfe":"Konsepsyon dirab ek fabrikasyon"}'::jsonb, '{"en":"Students consider environmental and social impacts of design decisions and learn manufacturing methods that reduce waste and resource use.","fr":"Les élèves examinent les impacts environnementaux et sociaux des décisions de conception et apprennent des méthodes de fabrication qui réduisent les déchets et l''utilisation des ressources.","mfe":"Bann elev examine lenfliyans lanvironnman ek sosyal bann desizyon konsepsyon ek aprann metod fabrikasyon ki diminie deshe ek itilizasyon resours."}'::jsonb),
('be0b2ac5-7068-5217-b319-e663de84f32e', 'design-technology', 10, 1, '{"en":"Understanding the design process","fr":"Comprendre le processus de conception","mfe":"Konpran pwosesis konsepsyon"}'::jsonb, '{"en":"Introduces the iterative design process used in O Level D&T, from identifying a problem to evaluating solutions.","fr":"Présente le processus itératif de conception utilisé en D&T niveau O, de l''identification d''un problème à l''évaluation des solutions.","mfe":"Prezant pwosesis konsepsyon iteratif itilize dan D&T Nivo O, depi identifye enn problem ziska evalye bann solisyon."}'::jsonb),
('96a8aa34-8aed-5d48-8c5e-91e5577e045a', 'design-technology', 10, 2, '{"en":"Working with timber and wood-based materials","fr":"Travailler le bois et les matériaux dérivés du bois","mfe":"Travay avek dibwa ek materyo ki sorti dan dibwa"}'::jsonb, '{"en":"Explores properties, sources, and uses of timber and manufactured boards in design projects.","fr":"Explore les propriétés, les sources et les usages du bois et des panneaux manufacturés dans les projets de conception.","mfe":"Explor bann proprite, sours ek itilizasyon dibwa ek pano fabrike dan bann prozet konsepsyon."}'::jsonb),
('3993c903-fbe6-5b0e-9c57-df19446c35b3', 'design-technology', 10, 3, '{"en":"Metals and polymers in design","fr":"Les métaux et les polymères en conception","mfe":"Metal ek polimer dan konsepsyon"}'::jsonb, '{"en":"Compares properties and applications of ferrous and non-ferrous metals and thermoplastics and thermosets.","fr":"Compare les propriétés et les applications des métaux ferreux et non ferreux ainsi que des thermoplastiques et thermodurcissables.","mfe":"Konpar bann proprite ek itilizasyon metal fero ek non-fero, osi bien ki termoplastik ek termodirsisan."}'::jsonb),
('ead3e287-caf2-50d9-b2de-07b13f831525', 'design-technology', 10, 4, '{"en":"Structures and mechanical systems","fr":"Structures et systèmes mécaniques","mfe":"Striktir ek sistenm mekanik"}'::jsonb, '{"en":"Covers structural forces, strengthening techniques, and basic mechanisms like levers, gears, and cams.","fr":"Couvre les forces structurelles, les techniques de renforcement et les mécanismes de base comme les leviers, les engrenages et les cames.","mfe":"Kouver bann fors striktirel, teknik pou ranforsi, ek mekanism debaz kouma levie, angrenaz ek kam."}'::jsonb),
('8ba344be-538d-5e26-92c2-b73d60e14e2d', 'design-technology', 10, 5, '{"en":"Electronic and control systems","fr":"Systèmes électroniques et de commande","mfe":"Sistenm elektronik ek kontrol"}'::jsonb, '{"en":"Introduces input-process-output systems, simple circuits, and components used in electronic products.","fr":"Présente les systèmes entrée-traitement-sortie, les circuits simples et les composants utilisés dans les produits électroniques.","mfe":"Prezant sistenm antre-tretman-sorti, sirkwi sinp ek konpozan itilize dan prodwi elektronik."}'::jsonb),
('ec58eb33-288e-54ab-ae1f-8487dd07c396', 'design-technology', 10, 6, '{"en":"Manufacturing processes and production","fr":"Procédés de fabrication et production","mfe":"Pwosesis fabrikasyon ek prodiksyon"}'::jsonb, '{"en":"Explains manufacturing methods, tolerances, quality control, and scales of production relevant to design.","fr":"Explique les méthodes de fabrication, les tolérances, le contrôle qualité et les échelles de production pertinentes pour la conception.","mfe":"Explik bann metod fabrikasyon, tolerans, kontrol kalite ek eshel prodiksyon relevan pou konsepsyon."}'::jsonb),
('05f106fd-254f-546e-ab8b-fbce3ed1ae83', 'design-technology', 10, 7, '{"en":"Sustainable design and material choice","fr":"Conception durable et choix des matériaux","mfe":"Konsepsyon dirab ek shwazi materyo"}'::jsonb, '{"en":"Examines environmental impact, the 6 Rs, and selecting materials responsibly for design projects.","fr":"Examine l''impact environnemental, les 6 R et le choix responsable des matériaux pour les projets de conception.","mfe":"Egzamin lenpak lor lanvironnman, 6 R ek fason pou shwazi materyo responsableman pou prozet konsepsyon."}'::jsonb),
('c45867ff-c159-54fe-9016-4a64375e9be2', 'design-technology', 10, 8, '{"en":"Analysing and evaluating products","fr":"Analyser et évaluer des produits","mfe":"Analize ek evalye bann prodwi"}'::jsonb, '{"en":"Develops skills in evaluating existing products and design outcomes against specifications.","fr":"Développe des compétences pour évaluer des produits existants et des résultats de conception par rapport aux spécifications.","mfe":"Devlop konpetans pou evalye prodwi ki existe ek rezilta konsepsyon par rapor ar spesifikasyon."}'::jsonb),
('0309a570-c815-5e62-b64b-772bf4e96694', 'design-technology', 11, 1, '{"en":"Design process and specifications","fr":"Processus de conception et cahiers des charges","mfe":"Prosesis konsepsyon ek kaye sarz"}'::jsonb, '{"en":"Students revisit and deepen their understanding of the design process, learning to write detailed design specifications and evaluate solutions against criteria for the O Level exam.","fr":"Les élèves révisent et approfondissent le processus de conception, apprenant à rédiger des cahiers des charges détaillés et à évaluer des solutions selon des critères pour l''examen O Level.","mfe":"Bann elev revize ek aprofondi konpreansyon zot lor prosesis konsepsyon, aprann ekrir kaye sarz detaye ek evalye solisyon dapre kriter pou lexamen O Level."}'::jsonb),
('6394628d-5205-51f9-9088-c3d61806857a', 'design-technology', 11, 2, '{"en":"Properties and selection of materials","fr":"Propriétés et sélection des matériaux","mfe":"Propriete ek swazi materyo"}'::jsonb, '{"en":"This unit examines the physical and mechanical properties of materials, including polymers, metals, woods and composites, and how these inform material selection for products.","fr":"Cette unité examine les propriétés physiques et mécaniques des matériaux, y compris les polymères, métaux, bois et composites, et leur influence sur la sélection des matériaux.","mfe":"Sa liniter la examinn propriete fizik ek mekanik materyo, ki inklir polimer, metal, dibwa ek konpozit, ek kouma sa gid swa materyo pou prodwi."}'::jsonb),
('40b19e12-4fca-552e-bc5d-8691ef176128', 'design-technology', 11, 3, '{"en":"Systems and control technology","fr":"Systèmes et technologie de contrôle","mfe":"Sistem ek teknolozi kontrol"}'::jsonb, '{"en":"Students learn about input, process and output systems, including sensors, control devices and simple programmable systems used in design solutions.","fr":"Les élèves apprennent les systèmes d''entrée, de traitement et de sortie, y compris les capteurs, les dispositifs de contrôle et les systèmes programmables simples.","mfe":"Bann elev aprann lor sistem lantre, prosesis ek sorti, ki inklir kapter, aparey kontrol ek sistem programab senp itilize dan solisyon konsepsyon."}'::jsonb),
('aa03cd8d-953d-55a6-9e4b-3ba5e6df5363', 'design-technology', 11, 4, '{"en":"Mechanisms and movement","fr":"Mécanismes et mouvement","mfe":"Mekanism ek mouvman"}'::jsonb, '{"en":"This unit covers mechanisms that transmit and transform motion, such as levers, linkages, gears, cams and pulleys, and their use in product design.","fr":"Cette unité couvre les mécanismes qui transmettent et transforment le mouvement, tels que leviers, liaisons, engrenages, cames et poulies.","mfe":"Sa liniter la kouver mekanism ki transmet ek transforme mouvman, kouma levye, lyezon, angrenaz, kam ek pouli, ek zot itilizasyon dan konsepsyon prodwi."}'::jsonb),
('d6fa839d-18a6-52d1-8c80-7f6f069655b2', 'design-technology', 11, 5, '{"en":"Electronics in product design","fr":"L''électronique dans la conception de produits","mfe":"Elektronik dan konsepsyon prodwi"}'::jsonb, '{"en":"Students explore basic electronic components, circuits and their integration into design solutions, building on earlier systems knowledge.","fr":"Les élèves explorent les composants électroniques de base, les circuits et leur intégration dans des solutions de conception.","mfe":"Bann elev explor bann konpozan elektronik debaz, sirkwi ek zot integrasyon dan solisyon konsepsyon."}'::jsonb),
('3a879ed5-7527-5c30-8ba0-a56b461c08dd', 'design-technology', 11, 6, '{"en":"Manufacturing processes and production","fr":"Procédés de fabrication et production","mfe":"Prosesis fabrikasyon ek prodiksyon"}'::jsonb, '{"en":"This unit examines industrial manufacturing processes, scales of production and quality control methods used to ensure consistent product quality.","fr":"Cette unité examine les procédés de fabrication industrielle, les échelles de production et les méthodes de contrôle qualité.","mfe":"Sa liniter la examinn prosesis fabrikasyon endistriyel, lesel prodiksyon ek metod kontrol kalite."}'::jsonb),
('95c6cfd9-05d6-5188-ae34-a014dbe41257', 'design-technology', 11, 7, '{"en":"Sustainability and impact of design","fr":"Durabilité et impact de la conception","mfe":"Dirabilite ek lenpak konsepsyon"}'::jsonb, '{"en":"Students examine environmental, social and economic impacts of design and manufacturing, including recycling, sustainability and ethical design practice.","fr":"Les élèves examinent les impacts environnementaux, sociaux et économiques de la conception et de la fabrication, y compris le recyclage et la durabilité.","mfe":"Bann elev examinn lenpak lanvironnman, sosyal ek ekonomik konsepsyon ek fabrikasyon, ki inklir resiklaz ek dirabilite."}'::jsonb),
('f5430072-5a9a-51ed-a86e-6754338da8c1', 'design-technology', 11, 8, '{"en":"Coursework skills and exam preparation","fr":"Compétences pour le projet et préparation à l''examen","mfe":"Konpetans travay ek prepar pou lexamen"}'::jsonb, '{"en":"This final unit consolidates coursework techniques and exam skills, guiding students to present design folders and practise examination-style questions for the O Level.","fr":"Cette unité finale consolide les techniques de projet et les compétences d''examen, guidant les élèves à présenter leurs dossiers et à s''entraîner aux questions d''examen.","mfe":"Sa dernie liniter konsolid teknik travay ek konpetans lexamen, gid bann elev prezant zot dosye konsepsyon ek pratik kestyon estil lexamen pou O Level."}'::jsonb),
('d82be610-72e8-5b75-8171-fe4a81046dee', 'design-technology', 12, 1, '{"en":"Foundations of design and technology","fr":"Fondements du design et de la technologie","mfe":"Baz dizayn ek teknolozi"}'::jsonb, '{"en":"This unit introduces the AS Level design and technology framework, exploring the role of design in society, the design process, and how technology shapes products and communities in Mauritius and globally.","fr":"Cette unité présente le cadre du design et de la technologie au niveau AS, en explorant le rôle du design dans la société, le processus de conception, et comment la technologie façonne les produits et les communautés à Maurice et dans le monde.","mfe":"Sa linite-la introdir lakad dizayn ek teknolozi nivo AS, examinn rol dizayn dan lasosyete, prosesis konsepsyon, ek kouma teknolozi fasonn produi ek kominote Moris ek dan lemond."}'::jsonb),
('72f47760-3480-59ed-82bb-e208d7decdbf', 'design-technology', 12, 2, '{"en":"User needs and ergonomics","fr":"Besoins des utilisateurs et ergonomie","mfe":"Bezwin itilizater ek ergonomi"}'::jsonb, '{"en":"Students explore how designers identify user needs, apply ergonomic and anthropometric data, and consider inclusive design to create products suited to diverse users.","fr":"Les élèves explorent comment les concepteurs identifient les besoins des utilisateurs, appliquent des données ergonomiques et anthropométriques, et considèrent la conception inclusive.","mfe":"Elev examinn kouma dizayner idantifie bezwin itilizater, aplik done ergonomik ek antropometrik, ek konsider dizayn enklizif pou kre produi ki adapte ar diferan itilizater."}'::jsonb),
('63bf0834-e00b-576e-b959-e018f3296f20', 'design-technology', 12, 3, '{"en":"Materials and their properties","fr":"Les matériaux et leurs propriétés","mfe":"Materyo ek zot proprete"}'::jsonb, '{"en":"This unit covers the classification, properties and selection of materials including woods, metals, polymers and composites, with emphasis on choosing suitable materials for design solutions.","fr":"Cette unité couvre la classification, les propriétés et la sélection des matériaux, y compris les bois, métaux, polymères et composites, en mettant l''accent sur le choix des matériaux appropriés.","mfe":"Sa linite-la kouver klasifikasyon, proprete ek seleksyon materyo, ki inklir dibwa, metal, polymer ek komposit, avek lanfaz lor swazir materyo apropriye pou solisyon dizayn."}'::jsonb),
('8b8c6d03-4e58-5ab2-a557-b0cd8ebfa0fb', 'design-technology', 12, 4, '{"en":"Manufacturing processes and techniques","fr":"Procédés et techniques de fabrication","mfe":"Prosesis ek teknik fabrikasyon"}'::jsonb, '{"en":"Students study a range of manufacturing processes for shaping, forming and joining materials, and examine how scale of production influences process choice.","fr":"Les élèves étudient divers procédés de fabrication pour façonner, former et assembler les matériaux, et examinent comment l''échelle de production influence le choix du procédé.","mfe":"Elev etidie diferan prosesis fabrikasyon pou fasonn, form ek zwenn materyo, ek examinn kouma lekel prodiksyon enfliyans swa prosesis."}'::jsonb),
('03338001-8ad6-5600-b763-327a28c98db3', 'design-technology', 12, 5, '{"en":"Systems and control in design","fr":"Systèmes et contrôle en conception","mfe":"Sistem ek kontrol dan dizayn"}'::jsonb, '{"en":"This unit introduces mechanical and electronic systems, including inputs, processes and outputs, and how control systems are used within designed products.","fr":"Cette unité présente les systèmes mécaniques et électroniques, incluant les entrées, processus et sorties, et comment les systèmes de contrôle sont utilisés dans les produits conçus.","mfe":"Sa linite-la introdir sistem mekanik ek elektronik, inklir intran, prosesis ek sortan, ek kouma sistem kontrol servi dan produi dizayne."}'::jsonb),
('877b9b3e-4350-5adb-b3c7-0f28975f91e4', 'design-technology', 12, 6, '{"en":"Design and market influences","fr":"Influences du design et du marché","mfe":"Lenfliyans dizayn ek marse"}'::jsonb, '{"en":"Students examine how historical, cultural, economic and marketing factors shape product design, including branding and consumer trends relevant to Mauritius.","fr":"Les élèves examinent comment les facteurs historiques, culturels, économiques et marketing façonnent le design des produits, y compris la marque et les tendances de consommation à Maurice.","mfe":"Elev examinn kouma faktor istorik, kiltirel, ekonomik ek marketing fasonn dizayn produi, ki inklir bran ek tandans konsomasyon relevan pou Moris."}'::jsonb),
('517003ea-d58a-5fc5-8afa-93b814cf1cfa', 'design-technology', 12, 7, '{"en":"Health, safety and industrial practice","fr":"Santé, sécurité et pratiques industrielles","mfe":"Lasante, sekirite ek pratik endistriyel"}'::jsonb, '{"en":"This unit covers health and safety practices in workshops and industry, along with quality control, quality assurance and commercial manufacturing considerations.","fr":"Cette unité couvre les pratiques de santé et de sécurité en atelier et dans l''industrie, ainsi que le contrôle qualité, l''assurance qualité et les considérations de fabrication commerciale.","mfe":"Sa linite-la kouver pratik lasante ek sekirite dan atelye ek dan endistri, ansanm avek kontrol kalite, aziransans kalite ek konsiderasyon fabrikasyon komersyal."}'::jsonb),
('45720c37-fc19-535a-a280-6658f971a8ae', 'design-technology', 13, 1, '{"en":"Advanced design strategies","fr":"Stratégies de conception avancées","mfe":"Stratezi konsepsion avanse"}'::jsonb, '{"en":"Students explore advanced iterative design methodologies, user-centred design and design thinking approaches used in professional practice, building on AS-level foundations.","fr":"Les élèves explorent des méthodologies de conception itératives avancées, la conception centrée sur l''utilisateur et les approches de design thinking utilisées dans la pratique professionnelle, en s''appuyant sur les acquis du niveau AS.","mfe":"Bann elev explor bann metod konsepsion iteratif avanse, konsepsion santre lor itilizater ek apros design thinking servi dan pratik profesionel, an baze lor sa ki finn aprann dan AS-level."}'::jsonb),
('36c5833d-491f-5412-9350-283d0368099c', 'design-technology', 13, 2, '{"en":"Industrial and commercial production","fr":"Production industrielle et commerciale","mfe":"Prodiksion endistriel ek komersial"}'::jsonb, '{"en":"This unit examines how products move from prototype to mass production, covering scales of production, automation and quality assurance in industrial contexts.","fr":"Cette unité examine comment les produits passent du prototype à la production de masse, en couvrant les échelles de production, l''automatisation et l''assurance qualité dans les contextes industriels.","mfe":"Sa linite-la examinn kouma prodwi pas depi prototip ziska prodiksion an mas, kouver eselel prodiksion, otomatizasion ek asirans kalite dan kontex endistriel."}'::jsonb),
('32e8fc82-8373-5204-95f0-e75c7fae2c27', 'design-technology', 13, 3, '{"en":"Systems and control in products","fr":"Systèmes et contrôle dans les produits","mfe":"Sistenm ek kontrol dan prodwi"}'::jsonb, '{"en":"Students study advanced systems thinking, mechanical and electronic control systems and how feedback loops are used to improve product performance.","fr":"Les élèves étudient la pensée systémique avancée, les systèmes de contrôle mécaniques et électroniques et l''utilisation des boucles de rétroaction pour améliorer la performance des produits.","mfe":"Bann elev etidie panse sistemik avanse, sistenm kontrol mekanik ek elektronik ek kouma bann boukle feedback servi pou ameliore performans prodwi."}'::jsonb),
('3589b9d6-49d3-578d-91e7-b5d00628e6f3', 'design-technology', 13, 4, '{"en":"Smart materials and technologies","fr":"Matériaux et technologies intelligentes","mfe":"Materio ek teknolozi intelizan"}'::jsonb, '{"en":"This unit explores emerging and smart materials, their properties and their potential applications in innovative product design.","fr":"Cette unité explore les matériaux émergents et intelligents, leurs propriétés et leurs applications potentielles dans la conception de produits innovants.","mfe":"Sa linite-la explor materio emerzan ek intelizan, zot proprite ek zot posib aplikasion dan konsepsion prodwi inovativ."}'::jsonb),
('252a7309-f29b-5266-82ba-d6b6d8300d2e', 'design-technology', 13, 5, '{"en":"Sustainability and environmental design","fr":"Durabilité et conception environnementale","mfe":"Dirabilite ek konsepsion anvironmantal"}'::jsonb, '{"en":"Students critically examine sustainable design principles, life cycle analysis and the environmental impact of manufacturing decisions.","fr":"Les élèves examinent de manière critique les principes de conception durable, l''analyse du cycle de vie et l''impact environnemental des décisions de fabrication.","mfe":"Bann elev examinn dan enn fason kritik prinsip konsepsion dirab, analiz sik lavi ek lenpak anvironmantal bann desizion fabrikasion."}'::jsonb),
('5d0320b6-d8e5-5204-8178-00fd343bf802', 'design-technology', 13, 6, '{"en":"Design communication and CAD/CAM","fr":"Communication de conception et CAO/FAO","mfe":"Kominikasion konsepsion ek CAD/CAM"}'::jsonb, '{"en":"This unit develops advanced skills in communicating design ideas using digital tools, including CAD modelling and CAM production methods.","fr":"Cette unité développe des compétences avancées en communication d''idées de conception à l''aide d''outils numériques, y compris la modélisation CAO et les méthodes de production FAO.","mfe":"Sa linite-la devlop bann konpetans avanse pou kominik lide konsepsion servi zouti dizital, ki inklir modelaz CAD ek metod prodiksion CAM."}'::jsonb),
('d5c9c2e1-b567-5e34-9609-7a545f97b7df', 'design-technology', 13, 7, '{"en":"Market and consumer influences","fr":"Influences du marché et des consommateurs","mfe":"Lenfliyans marse ek konsomater"}'::jsonb, '{"en":"Students analyse how market trends, branding and consumer culture shape design decisions and product success.","fr":"Les élèves analysent comment les tendances du marché, l''image de marque et la culture des consommateurs influencent les décisions de conception et le succès des produits.","mfe":"Bann elev analiz kouma tandans marse, brandin ek kiltir konsomater influans desizion konsepsion ek sikse prodwi."}'::jsonb),
('9e184c02-7fe4-5619-b041-2b29864403f4', 'design-technology', 13, 8, '{"en":"Major project development","fr":"Développement du projet majeur","mfe":"Devlopman gran projet"}'::jsonb, '{"en":"This unit guides students through planning, developing and documenting an independent major design project as preparation for coursework assessment.","fr":"Cette unité guide les élèves dans la planification, le développement et la documentation d''un projet de conception majeur indépendant en préparation de l''évaluation du travail de cours.","mfe":"Sa linite-la gid bann elev pou planifie, devlop ek dokimant enn gran projet konsepsion endepandan kouma preparasion pou levaliyasion travay kour."}'::jsonb),
('0c6723dd-ca27-57ab-a602-46386a9b1c4b', 'drama', 7, 1, '{"en":"Introduction to drama","fr":"Introduction au théâtre","mfe":"Introdiksion a lar dramatik"}'::jsonb, '{"en":"Students explore what drama is, its purpose, and basic classroom conventions for participating safely and respectfully in drama activities.","fr":"Les élèves explorent ce qu''est le théâtre, son but, et les conventions de base pour participer en toute sécurité et avec respect aux activités théâtrales.","mfe":"Bann elev explor ki eski drama ete, so bi, ek bann konvansion baz pou partisip an sekirite ek avek respe dan bann aktivite drama."}'::jsonb),
('ec8e76b9-dff2-5e0a-93ca-7eb4b2ffb0ad', 'drama', 7, 2, '{"en":"Using the voice","fr":"Utiliser la voix","mfe":"Servi lavwa"}'::jsonb, '{"en":"This unit introduces vocal skills such as projection, pace, pitch and tone, helping students communicate clearly and expressively.","fr":"Cette unité présente des compétences vocales telles que la projection, le rythme, la hauteur et le ton, aidant les élèves à communiquer clairement.","mfe":"Sa linite la introdir bann konpetans vokal kouma proteksion son, vites, oter ek ton, ki ed bann elev kominik kler ek expresif."}'::jsonb),
('2ffb777a-2c34-5e5d-a817-2d52f129f113', 'drama', 7, 3, '{"en":"Body and movement","fr":"Corps et mouvement","mfe":"Lekor ek mouvman"}'::jsonb, '{"en":"Students learn how posture, gesture and movement communicate character and feeling without words, building physical awareness for performance.","fr":"Les élèves apprennent comment la posture, le geste et le mouvement communiquent le caractère et les émotions sans mots.","mfe":"Bann elev aprann kouma postir, zes ek mouvman kominik karakter ek santiman san servi mo."}'::jsonb),
('3f85d2a5-9d5c-5622-bbe7-9d1de090c125', 'drama', 7, 4, '{"en":"Role play basics","fr":"Bases du jeu de rôle","mfe":"Baz zwe rol"}'::jsonb, '{"en":"This unit introduces students to taking on roles, exploring characters different from themselves, and building simple scenes.","fr":"Cette unité initie les élèves à endosser des rôles, à explorer des personnages différents d''eux-mêmes et à construire des scènes simples.","mfe":"Sa linite introdir bann elev pou pran rol, explor personaz diferan ar zot ek konstrir bann senn senp."}'::jsonb),
('13031f85-2e02-5a65-bb98-888bc72a2bdb', 'drama', 7, 5, '{"en":"Improvisation skills","fr":"Compétences d''improvisation","mfe":"Konpetans improvizasion"}'::jsonb, '{"en":"Students develop spontaneous performance skills by responding to prompts, building scenes together and thinking creatively under pressure.","fr":"Les élèves développent des compétences de performance spontanée en répondant à des consignes et en créant des scènes ensemble.","mfe":"Bann elev devlop konpetans perform spontane par reponn a bann prompt ek kree senn ansam."}'::jsonb),
('1e614c5e-482a-5dd6-bada-28b5acef6fcc', 'drama', 7, 6, '{"en":"Storytelling through drama","fr":"Raconter des histoires par le théâtre","mfe":"Rakont zistwar par drama"}'::jsonb, '{"en":"This unit explores how stories, including Mauritian folktales, can be brought to life through dramatic techniques and structure.","fr":"Cette unité explore comment les histoires, y compris les contes mauriciens, peuvent prendre vie grâce aux techniques théâtrales.","mfe":"Sa linite explor kouma bann zistwar, ki ensor bann conte morisien, kapav pran lavi atraver bann teknik dramatik."}'::jsonb),
('5cf4ae61-3564-5f20-981b-21b94ef468e5', 'drama', 7, 7, '{"en":"Elements of drama","fr":"Éléments du théâtre","mfe":"Bann element drama"}'::jsonb, '{"en":"Students are introduced to key dramatic elements such as tension, contrast and symbol, learning to apply them in simple performances.","fr":"Les élèves découvrent des éléments dramatiques clés tels que la tension, le contraste et le symbole, et apprennent à les appliquer.","mfe":"Bann elev aprann bann element dramatik kle kouma tansion, kontras ek senbol, ek aprann aplik zot dan bann perform senp."}'::jsonb),
('d96cf1c7-d502-5f71-8270-d35567640de0', 'drama', 7, 8, '{"en":"Sharing our performances","fr":"Partager nos performances","mfe":"Partaz nou bann perform"}'::jsonb, '{"en":"In this culminating unit, students devise and rehearse a short group performance, then present it and reflect on their learning journey.","fr":"Dans cette unité finale, les élèves créent et répètent une courte performance de groupe, puis la présentent et réfléchissent à leur apprentissage.","mfe":"Dan sa dernie linite, bann elev devlop ek repete enn ti perform an group, apre prezant li ek refleshi lor zot laprantisaz."}'::jsonb),
('d79bbafa-62dd-5640-97ef-de984ce2e57a', 'drama', 8, 1, '{"en":"Revisiting drama basics","fr":"Retour sur les bases du théâtre","mfe":"Repran bann baz teat"}'::jsonb, '{"en":"Students revise key drama vocabulary and warm-up techniques learnt in Grade 7 before building on them with more complex exercises.","fr":"Les élèves révisent le vocabulaire théâtral clé et les techniques d''échauffement apprises en 7e année avant de les approfondir avec des exercices plus complexes.","mfe":"Bann elev revize vokabiler teat inportan ek teknik esofman ki zot finn aprann Grade 7 avan zot devlop ar exersis pli konplike."}'::jsonb),
('23dc4d04-e29f-52eb-992e-17eedd7accd7', 'drama', 8, 2, '{"en":"Exploring characterisation","fr":"Explorer la caractérisation","mfe":"Explor karakterizasion"}'::jsonb, '{"en":"This unit develops students'' ability to create believable characters through physicality, voice and status.","fr":"Cette unité développe la capacité des élèves à créer des personnages crédibles à travers la corporalité, la voix et le statut.","mfe":"Sa linite-la devlop kapasite bann elev pou kree personaz kredib atraver lekor, lavwa ek statu."}'::jsonb),
('452ab14c-180d-5431-8258-f64b008aee00', 'drama', 8, 3, '{"en":"Improvisation techniques","fr":"Techniques d''improvisation","mfe":"Teknik improvizasion"}'::jsonb, '{"en":"Students practise spontaneous and structured improvisation to build confidence and creative thinking on stage.","fr":"Les élèves pratiquent l''improvisation spontanée et structurée pour développer la confiance et la pensée créative sur scène.","mfe":"Bann elev pratik improvizasion spontane ek striktire pou devlop konfians ek panse kreatif lor sen."}'::jsonb),
('ec1421f1-1f03-5bac-9669-a309c9b0f821', 'drama', 8, 4, '{"en":"Mauritian stories on stage","fr":"Histoires mauriciennes sur scène","mfe":"Zistwar morisien lor sen"}'::jsonb, '{"en":"Students explore local legends, folk tales and community stories, adapting them into short dramatic scenes.","fr":"Les élèves explorent des légendes locales, des contes populaires et des histoires communautaires, en les adaptant en courtes scènes dramatiques.","mfe":"Bann elev explor bann lezand lokal, kont popiler ek zistwar kominote, adapte zot an ti sen dramatik."}'::jsonb),
('ee1b93bd-293a-5654-b262-b180a54c840a', 'drama', 8, 5, '{"en":"Using space and movement","fr":"Utiliser l''espace et le mouvement","mfe":"Servi lespas ek mouvman"}'::jsonb, '{"en":"This unit focuses on stage geography, levels and movement to strengthen visual storytelling.","fr":"Cette unité se concentre sur la géographie de la scène, les niveaux et le mouvement pour renforcer la narration visuelle.","mfe":"Sa linite-la konsantre lor zeografi lasenn, nivo ek mouvman pou ranforsi rakonte istwar par lizie."}'::jsonb),
('bce441df-4848-5fac-b95b-c55087e74480', 'drama', 8, 6, '{"en":"Introduction to scripted drama","fr":"Introduction au théâtre scénarisé","mfe":"Introduksion ar teat ekri"}'::jsonb, '{"en":"Students learn to read, interpret and perform short scripted extracts, focusing on script conventions.","fr":"Les élèves apprennent à lire, interpréter et jouer de courts extraits scénarisés, en se concentrant sur les conventions de script.","mfe":"Bann elev aprann lir, interprete ek zwe ti extre ekri, konsantre lor konvansion skrip."}'::jsonb),
('748b465d-6773-55a4-b02f-9f42f3150d3f', 'drama', 8, 7, '{"en":"Drama for social awareness","fr":"Le théâtre pour la sensibilisation sociale","mfe":"Teat pou konsiantizasion sosial"}'::jsonb, '{"en":"Students use drama techniques such as forum theatre and tableaux to explore social issues relevant to their community.","fr":"Les élèves utilisent des techniques théâtrales telles que le théâtre-forum et les tableaux vivants pour explorer des questions sociales pertinentes pour leur communauté.","mfe":"Bann elev servi teknik teat kouma teat-forum ek tablivan pou explor bann problem sosial ki konsern zot kominote."}'::jsonb),
('a76e8fc0-9879-5ab5-86b0-170642f3a8f3', 'drama', 9, 1, '{"en":"Advanced improvisation techniques","fr":"Techniques d''improvisation avancées","mfe":"Teknik improvizasion avanse"}'::jsonb, '{"en":"Students build on earlier improvisation skills, learning to sustain longer scenes, respond to unexpected challenges, and work collaboratively to create believable dramatic moments.","fr":"Les élèves développent leurs compétences antérieures en improvisation, apprenant à maintenir des scènes plus longues, à réagir à des défis inattendus et à collaborer pour créer des moments dramatiques crédibles.","mfe":"Bann elev devlop zot bann konpetans improvizasion ki zot ti gagne avan, aprann pou maintenir bann sxenn pli long, reponn a bann defi initenn ek travay ansam pou kree bann moman dramatik kredib."}'::jsonb),
('cc5c7766-7d11-5546-84d3-2aff05017a20', 'drama', 9, 2, '{"en":"Characterisation and role development","fr":"Caractérisation et développement de rôle","mfe":"Karakterizasion ek devlopman rol"}'::jsonb, '{"en":"This unit explores how actors build believable characters using physicality, voice, backstory and motivation, moving from simple role play to deeper character study.","fr":"Cette unité explore comment les acteurs construisent des personnages crédibles en utilisant la physicalité, la voix, l''historique et la motivation, passant du simple jeu de rôle à une étude de personnage plus approfondie.","mfe":"Sa lini-la explor kouma bann akter konstrir bann personaz kredib par servi lekor, lavwa, listwar ek motivasion, pass depi enn senp role play ver enn letid personaz pli fon."}'::jsonb),
('6a60c42e-e800-5393-8fd4-a540d0d2b5d7', 'drama', 9, 3, '{"en":"Elements and structure of drama","fr":"Éléments et structure du théâtre","mfe":"Elema ek striktir teat"}'::jsonb, '{"en":"Learners examine the key elements of drama such as tension, contrast, symbol and climax, and how these combine to shape a piece of theatre.","fr":"Les élèves examinent les éléments clés du théâtre tels que la tension, le contraste, le symbole et le point culminant, et comment ceux-ci se combinent pour façonner une pièce de théâtre.","mfe":"Bann elev examinn bann elema kle teat kouma tansion, kontras, senbol ek klimaks, ek kouma sa bann la konbine pou form enn pyes teat."}'::jsonb),
('7bf708ec-949d-5a3e-95a9-5db819511fbd', 'drama', 9, 4, '{"en":"Devising theatre from stimulus","fr":"Créer du théâtre à partir d''un stimulus","mfe":"Kree teat apartir enn stimilis"}'::jsonb, '{"en":"Students learn the devising process, turning a picture, news story, object or theme into an original piece of theatre through collaborative creation.","fr":"Les élèves apprennent le processus de création théâtrale, transformant une image, un fait divers, un objet ou un thème en une pièce de théâtre originale grâce à une création collaborative.","mfe":"Bann elev aprann prosesis kreasion teat, transform enn zimaz, enn lartik nouvel, enn obze ouswa enn tem an enn pyes teat orizinal atraver kreasion kolektiv."}'::jsonb),
('32ef4bd4-f1fc-57d0-b289-b27710c8126e', 'drama', 9, 5, '{"en":"Exploring scripts and playwrights","fr":"Explorer des scripts et des dramaturges","mfe":"Explor bann skrip ek dramatiz"}'::jsonb, '{"en":"This unit introduces reading and interpreting scripts, understanding stage directions, and exploring the work of playwrights from Mauritius and beyond.","fr":"Cette unité initie à la lecture et à l''interprétation de scripts, à la compréhension des indications scéniques et à l''exploration du travail de dramaturges de Maurice et d''ailleurs.","mfe":"Sa lini-la introdir lir ek interprete skrip, konpran bann direksion lasenn ek explor travay bann dramatiz depi Moris ek lezot pei."}'::jsonb),
('2c18a2ac-9d6d-589b-80c8-276d994bb364', 'drama', 9, 6, '{"en":"Design and technical theatre basics","fr":"Bases de la conception et de la technique théâtrale","mfe":"Baz konsepsion ek teknik teat"}'::jsonb, '{"en":"Learners explore how set, costume, lighting and sound support storytelling, and try simple design tasks to enhance a performance.","fr":"Les élèves explorent comment le décor, le costume, l''éclairage et le son soutiennent la narration, et essaient des tâches de conception simples pour améliorer une représentation.","mfe":"Bann elev explor kouma dekor, kostim, lekleraz ek son sipport rakontaz enn zistwar, ek esey bann tas konsepsion senp pou amelior enn perfomans."}'::jsonb),
('32756415-a9c1-5d07-a9a7-066c5281800c', 'drama', 9, 7, '{"en":"Physical theatre and movement","fr":"Théâtre physique et mouvement","mfe":"Teat fizik ek mouvman"}'::jsonb, '{"en":"Students use their bodies expressively to tell stories without relying only on words, exploring mime, ensemble movement and physical storytelling.","fr":"Les élèves utilisent leur corps de manière expressive pour raconter des histoires sans dépendre uniquement des mots, explorant le mime, le mouvement d''ensemble et la narration physique.","mfe":"Bann elev servi zot lekor dan enn fason expresif pou rakont zistwar san depann zis lor bann mo, explor mim, mouvman an group ek rakontaz fizik."}'::jsonb),
('16abc28a-59cf-5d42-bf0b-c0dd31abd373', 'drama', 9, 8, '{"en":"Performance project and evaluation","fr":"Projet de performance et évaluation","mfe":"Projet perfomans ek evalyasion"}'::jsonb, '{"en":"In this culminating unit, students plan, rehearse and present a final performance piece, then reflect critically on their own and others'' work.","fr":"Dans cette unité finale, les élèves planifient, répètent et présentent une pièce de performance finale, puis réfléchissent de manière critique à leur propre travail et à celui des autres.","mfe":"Dan sa lini final-la, bann elev planifie, repete ek prezant enn dernie pyes perfomans, apre reflesi dan enn fason kritik lor zot prop travay ek lor travay lezot."}'::jsonb),
('b1236974-fb33-5500-822d-aa7859476c67', 'drama', 10, 1, '{"en":"Foundations of devising drama","fr":"Fondements de l''improvisation dramatique","mfe":"Baz pou kre teat"}'::jsonb, '{"en":"Students revisit key drama skills from earlier grades and begin exploring the devising process used in IGCSE Drama, learning how stimulus material can generate original performance ideas.","fr":"Les élèves révisent les compétences théâtrales essentielles des années précédentes et commencent à explorer le processus de création utilisé en théâtre IGCSE, en apprenant comment un stimulus peut générer des idées de performance originales.","mfe":"Bann elev pas an revi bann konpetans teat baz ki zot fin aprann avan, ek koumans explor prosesis pou kre enn pyes teat kouma dan IGCSE Drama, an aprann kouman enn stimulis kapav donn lide pou performans orizinal."}'::jsonb),
('7a9d5015-f3b3-5f2a-90c8-e85aa05df119', 'drama', 10, 2, '{"en":"Physical theatre and movement","fr":"Théâtre physique et mouvement","mfe":"Teat fizik ek mouvman"}'::jsonb, '{"en":"This unit develops students'' physical expression through movement-based exercises, exploring how the body communicates character, emotion and narrative on stage.","fr":"Cette unité développe l''expression physique des élèves à travers des exercices basés sur le mouvement, en explorant comment le corps communique le personnage, l''émotion et le récit sur scène.","mfe":"Sa linite-la devlop lexpresyon fizik bann elev atraver exersis baze lor mouvman, an explor kouman lekor kominik personaz, santiman ek istwar lor lasenn."}'::jsonb),
('ca44ccee-66c9-513f-a423-afb472728b09', 'drama', 10, 3, '{"en":"Exploring text through performance","fr":"Explorer un texte par la performance","mfe":"Explor enn tex atraver performans"}'::jsonb, '{"en":"Students study extracts from set and unseen play scripts, learning to interpret dialogue, subtext and stage directions to bring text to life.","fr":"Les élèves étudient des extraits de scripts de pièces prescrites et inconnues, apprenant à interpréter le dialogue, le sous-texte et les indications scéniques pour donner vie au texte.","mfe":"Bann elev etidye bann extre depi pyes teat fikse ek pa''nn fikse, an aprann interprete dyalog, sou-tex ek direksyon lasenn pou donn lavi ar tex."}'::jsonb),
('81004cea-91e2-57c0-86da-c0f1a98f7e53', 'drama', 10, 4, '{"en":"Characterisation and role-building","fr":"Caractérisation et construction de rôle","mfe":"Karakterizasyon ek konstriksyon rol"}'::jsonb, '{"en":"This unit focuses on techniques for creating believable characters, including physical, vocal and psychological approaches to role-building.","fr":"Cette unité se concentre sur les techniques de création de personnages crédibles, y compris les approches physiques, vocales et psychologiques de la construction de rôle.","mfe":"Sa linite-la konsantre lor teknik pou kre personaz kredib, ki inklir bann laprosh fizik, vokal ek psikolozik pou konstrir rol."}'::jsonb),
('23a3b451-8995-542b-90eb-679c88f28c9d', 'drama', 10, 5, '{"en":"Design elements in performance","fr":"Éléments de conception dans la performance","mfe":"Bann element design dan performans"}'::jsonb, '{"en":"Students explore how lighting, sound, costume and set design contribute to the overall meaning and atmosphere of a performance.","fr":"Les élèves explorent comment l''éclairage, le son, les costumes et la scénographie contribuent au sens global et à l''atmosphère d''une performance.","mfe":"Bann elev explor kouman lalimyer, son, kostim ek design lasenn kontribye dan sinifikasyon global ek atmosfer enn performans."}'::jsonb),
('fefa1e2f-9716-5ca8-9c69-f101d4cda269', 'drama', 10, 6, '{"en":"Improvisation and scripted work","fr":"Improvisation et travail scénarisé","mfe":"Improvizasyon ek travay skripte"}'::jsonb, '{"en":"This unit develops confidence in spontaneous performance while linking improvisational skills to structured, scripted drama work.","fr":"Cette unité développe la confiance dans la performance spontanée tout en reliant les compétences d''improvisation au travail théâtral scénarisé et structuré.","mfe":"Sa linite-la devlop konfyans dan performans spontane pandan ki li relye konpetans improvizasyon avek travay teat skripte ek striktire."}'::jsonb),
('ed7d86d9-21fa-5b2a-8cbb-9faa1d977300', 'drama', 10, 7, '{"en":"Preparing and evaluating performance","fr":"Préparer et évaluer une performance","mfe":"Prepar ek evalye enn performans"}'::jsonb, '{"en":"Students consolidate skills by rehearsing a polished performance piece and learning to critically evaluate their own and others'' theatrical work.","fr":"Les élèves consolident leurs compétences en répétant une performance soignée et en apprenant à évaluer de manière critique leur propre travail théâtral et celui des autres.","mfe":"Bann elev konsolid zot konpetans an repete enn pyes performans fini bien prepare ek an aprann evalye kritikman zot prop travay teat ek sa lezot osi."}'::jsonb),
('eb865277-8e2f-5f53-8611-12da41de74fe', 'drama', 11, 1, '{"en":"Foundations of drama practice","fr":"Fondements de la pratique théâtrale","mfe":"Baz lartistik teat"}'::jsonb, '{"en":"Students revise key drama skills from earlier grades and build ensemble trust needed for Cambridge IGCSE Drama coursework.","fr":"Les élèves révisent les compétences théâtrales clés des années précédentes et développent la confiance de groupe nécessaire pour le travail de coursework IGCSE Cambridge.","mfe":"Bann elev revize bann konpetans teat kle ki zwenn nan bann klas avan e devlop konfyans an group ki neseser pou travay coursework Cambridge IGCSE Drama."}'::jsonb),
('5d1b4cf7-1538-5d69-9e59-e0b4702ccda0', 'drama', 11, 2, '{"en":"Devising original drama","fr":"Créer une pièce originale","mfe":"Kree enn drama orizinal"}'::jsonb, '{"en":"Students learn the devising process, from stimulus to structured performance, developing original material collaboratively.","fr":"Les élèves apprennent le processus de création, du stimulus à la performance structurée, en développant du matériel original de manière collaborative.","mfe":"Bann elev aprann proseser kreasyon, depi enn stimulis ziska enn performans strikture, e devlop material orizinal ansam."}'::jsonb),
('2d63d55e-29fb-5297-8e28-0d8672ec400d', 'drama', 11, 3, '{"en":"Exploring performance texts","fr":"Explorer des textes de performance","mfe":"Explor bann text performans"}'::jsonb, '{"en":"Students study a set play text in depth, exploring character, context and dramatic meaning to prepare for practical exploration.","fr":"Les élèves étudient en profondeur un texte théâtral au programme, explorant les personnages, le contexte et le sens dramatique pour préparer l''exploration pratique.","mfe":"Bann elev etidye byin profon enn text pyes ki dan programme, explor personaz, kontex ek sinifikasyon dramatik pou prepar explorasyon praktik."}'::jsonb),
('2262726a-09a7-5fdb-a503-c238dd4088a6', 'drama', 11, 4, '{"en":"Characterisation and acting skills","fr":"Caractérisation et techniques de jeu","mfe":"Karakterizasyon ek teknik zwe"}'::jsonb, '{"en":"Students develop vocal and physical skills to create believable and detailed characters for performance.","fr":"Les élèves développent des compétences vocales et physiques pour créer des personnages crédibles et détaillés pour la scène.","mfe":"Bann elev devlop konpetans vokal ek fizik pou kree personaz kredib ek detaye pou performans."}'::jsonb),
('404ca93e-9024-5b3e-ab6d-14aa03f827e0', 'drama', 11, 5, '{"en":"Design and technical theatre","fr":"Conception et théâtre technique","mfe":"Konsepsyon ek teknik teat"}'::jsonb, '{"en":"Students explore how set, costume, lighting and sound design contribute to dramatic meaning in performance.","fr":"Les élèves explorent comment le décor, les costumes, l''éclairage et le son contribuent au sens dramatique de la performance.","mfe":"Bann elev explor kouma deko, kostim, limyer ek son kontribye dan sinifikasyon dramatik enn performans."}'::jsonb),
('ca118799-0d4e-59fa-ae0b-6f154a80156d', 'drama', 11, 6, '{"en":"Monologue and duologue performance","fr":"Performance de monologue et duologue","mfe":"Performans monolog ek dyalog"}'::jsonb, '{"en":"Students prepare and perform monologues and duologues, applying acting and interpretive skills for individual assessment.","fr":"Les élèves préparent et interprètent des monologues et duologues, en appliquant des compétences de jeu pour l''évaluation individuelle.","mfe":"Bann elev prepar ek performans monolog ek dyalog, aplik konpetans zwe pou levaluasyon endividyel."}'::jsonb),
('f5e79c5b-05eb-5960-a9e2-a1d1c0941cb3', 'drama', 11, 7, '{"en":"Live theatre evaluation","fr":"Évaluation du théâtre en direct","mfe":"Levaluasyon teat anrezistrer an direk"}'::jsonb, '{"en":"Students learn to critically evaluate live or recorded theatre performances, developing analytical writing skills for the exam.","fr":"Les élèves apprennent à évaluer de manière critique des performances théâtrales en direct ou enregistrées, développant des compétences d''analyse pour l''examen.","mfe":"Bann elev aprann evalyer bann performans teat an direk oubyen anrezistre dan enn fason kritik, e devlop konpetans analiz pou lekzame."}'::jsonb),
('14b93a08-5b33-570c-842c-cedcb9922067', 'drama', 11, 8, '{"en":"Exam preparation and mock practicals","fr":"Préparation à l''examen et pratiques simulées","mfe":"Prepar lekzame ek praktik similasyon"}'::jsonb, '{"en":"Students consolidate coursework and revise for the written paper through mock practical assessments and exam-style tasks.","fr":"Les élèves consolident leur travail de coursework et révisent pour l''épreuve écrite grâce à des évaluations pratiques simulées et des exercices type examen.","mfe":"Bann elev konsolid coursework ek revize pou papye ekri atraver bann levaluasyon praktik similasyon ek bann task style lekzame."}'::jsonb),
('bdbd679f-65f4-5177-ad64-1d227367f2fd', 'english-literature', 10, 1, '{"en":"Foundations of literary study","fr":"Fondements de l''étude littéraire","mfe":"Baz létid literer"}'::jsonb, '{"en":"An introduction to the key concepts and vocabulary needed to analyse literary texts, including plot, character, theme and figurative language.","fr":"Une introduction aux concepts clés et au vocabulaire nécessaires pour analyser des textes littéraires, notamment l''intrigue, les personnages, le thème et le langage figuré.","mfe":"Enn lentrodiksion lor bann konsep kle ek vokabiler ki bizin pou analiz text literer, kouma intrig, personaz, tem ek langaz figiratif."}'::jsonb),
('d01eee3e-43b8-5a1d-b5bc-c57b431852de', 'english-literature', 10, 2, '{"en":"Reading and appreciating poetry","fr":"Lire et apprécier la poésie","mfe":"Lir ek apresie poezi"}'::jsonb, '{"en":"Students explore set poems, developing skills to interpret imagery, sound and structure while comparing different poets'' approaches to shared themes.","fr":"Les élèves explorent des poèmes au programme, développant des compétences pour interpréter l''imagerie, le son et la structure tout en comparant les approches de différents poètes sur des thèmes communs.","mfe":"Bann etidian explor bann poem lor program, devlop konpetans pou interpret imaz, son ek striktir pandan ki zot konpar diferan lapros poet lor mem tem."}'::jsonb),
('7623a545-50a5-590a-8a8f-69236c051d4e', 'english-literature', 10, 3, '{"en":"Studying Lord of the Flies","fr":"Étudier Sa Majesté des Mouches","mfe":"Etidye Lord of the Flies"}'::jsonb, '{"en":"A close study of William Golding''s novel, focusing on character development, symbolism and the central conflict between civilization and savagery.","fr":"Une étude approfondie du roman de William Golding, axée sur le développement des personnages, le symbolisme et le conflit central entre civilisation et sauvagerie.","mfe":"Enn letid apronfondi roman William Golding, ki fokis lor devlopman personaz, senbolism ek konfli santral ant sivilizasion ek sovaziz."}'::jsonb),
('123af01a-654e-5fcd-adb9-c550bf9a129a', 'english-literature', 10, 4, '{"en":"Studying Julius Caesar","fr":"Étudier Jules César","mfe":"Etidye Julius Caesar"}'::jsonb, '{"en":"Students study Shakespeare''s tragedy, examining its historical context, characters, themes of power and betrayal, and dramatic techniques.","fr":"Les élèves étudient la tragédie de Shakespeare, en examinant son contexte historique, ses personnages, les thèmes du pouvoir et de la trahison, et les techniques dramatiques.","mfe":"Bann etidian etidye trazedi Shakespeare, examine so kontex istorik, personaz, tem pouvwar ek trayizon, ek teknik dramatik."}'::jsonb),
('0afa2ef7-ea85-53cb-af30-317853520851', 'english-literature', 10, 5, '{"en":"Developing unseen poetry skills","fr":"Développer les compétences en poésie inconnue","mfe":"Devlop konpetans poezi ki pa vwar avan"}'::jsonb, '{"en":"Focused practice in reading and responding to unfamiliar poems under timed conditions, building confidence for the examination.","fr":"Une pratique ciblée de lecture et de réponse à des poèmes inconnus dans des conditions chronométrées, renforçant la confiance pour l''examen.","mfe":"Pratik fokalize pou lir ek reponn poem ki pa konnen dan kondision ki gard letan, pou ranforsi konfians pou lexamen."}'::jsonb),
('86fd56f3-c8c7-54b0-a720-acfe7842cc5e', 'english-literature', 10, 6, '{"en":"Developing unseen prose skills","fr":"Développer les compétences en prose inconnue","mfe":"Devlop konpetans proz ki pa konnen"}'::jsonb, '{"en":"Students build skills in analysing unfamiliar prose extracts, focusing on narrative viewpoint, language and stylistic features.","fr":"Les élèves développent des compétences pour analyser des extraits de prose inconnus, en se concentrant sur le point de vue narratif, le langage et les procédés stylistiques.","mfe":"Bann etidian devlop konpetans pou analiz extrait proz ki pa konnen, fokis lor pwin-de-vi naratif, langaz ek teknik stilistik."}'::jsonb),
('ff75fb11-29bc-5e76-9ca7-2a1e710e449a', 'english-literature', 10, 7, '{"en":"Essay writing and exam preparation","fr":"Rédaction d''essais et préparation à l''examen","mfe":"Ekritir dissertation ek preparasion pou lexamen"}'::jsonb, '{"en":"A final unit consolidating essay-writing skills and exam techniques across poetry, prose and drama in preparation for the SC examination.","fr":"Une dernière unité consolidant les compétences de rédaction d''essais et les techniques d''examen en poésie, prose et théâtre en préparation de l''examen SC.","mfe":"Enn dernier linite ki konsolid konpetans ekritir dissertation ek teknik lexamen dan poezi, proz ek teat pou prepar lexamen SC."}'::jsonb),
('9a51711d-ff94-50ee-a829-3adad83d1531', 'english-literature', 11, 1, '{"en":"Refining poetry analysis skills","fr":"Affiner les compétences d''analyse poétique","mfe":"Rafinn konpetans analiz lapoezi"}'::jsonb, '{"en":"Students deepen their ability to analyse the set poetry anthology, focusing on imagery, sound and structure to build strong exam responses.","fr":"Les élèves approfondissent leur capacité à analyser l''anthologie de poésie au programme, en se concentrant sur les images, les sonorités et la structure pour construire des réponses solides à l''examen.","mfe":"Bann elev apronfondi zot kapasite pou analiz lantolozi lapoezi ki dan program, ar fokis lor imazri, son ek striktir pou konstir bann repons solid pou lexamen."}'::jsonb),
('a453072b-3970-5ddc-8956-8d6405977867', 'english-literature', 11, 2, '{"en":"Deepening study of the set novel","fr":"Approfondir l''étude du roman au programme","mfe":"Apronfondi letid lo roman ki dan program"}'::jsonb, '{"en":"Students explore character development, narrative technique and themes in the set novel to prepare detailed critical responses.","fr":"Les élèves explorent le développement des personnages, la technique narrative et les thèmes du roman au programme pour préparer des réponses critiques détaillées.","mfe":"Bann elev explor devlopman personaz, teknik naratif ek tem dan roman ki dan program pou prepar bann repons kritik detaye."}'::jsonb),
('449ad7f8-caca-5d66-b1e4-e1d7176d7922', 'english-literature', 11, 3, '{"en":"Exploring the set play in depth","fr":"Explorer en profondeur la pièce au programme","mfe":"Explor an profonder lapies ki dan program"}'::jsonb, '{"en":"Students examine dramatic techniques, characterisation and staging choices in the set play to strengthen essay writing.","fr":"Les élèves examinent les techniques dramatiques, la caractérisation et les choix de mise en scène de la pièce au programme pour renforcer leur rédaction.","mfe":"Bann elev examine teknik dramatik, karakteryzasyon ek swa mizansenn dan lapies ki dan program pou ranforsi zot redaksyon."}'::jsonb),
('17cbd78e-5ac2-5cca-bb5c-01bd98cb3e26', 'english-literature', 11, 4, '{"en":"Comparing characters and relationships","fr":"Comparer personnages et relations","mfe":"Konpar personaz ek relasyon"}'::jsonb, '{"en":"Students compare characters and relationships across set texts to develop analytical and comparative writing skills.","fr":"Les élèves comparent des personnages et des relations entre les textes au programme pour développer des compétences d''écriture analytique et comparative.","mfe":"Bann elev konpar personaz ek relasyon ant bann text ki dan program pou devlop konpetans lekritir analitik ek konparativ."}'::jsonb),
('69254106-2f64-5050-974a-ab24ccd25be5', 'english-literature', 11, 5, '{"en":"Tackling unseen poetry and prose","fr":"Aborder poésie et prose inconnues","mfe":"Abord lapoezi ek proz ki pa konpli"}'::jsonb, '{"en":"Students practise close reading strategies for unseen extracts to build confidence for the unseen examination paper.","fr":"Les élèves s''exercent aux stratégies de lecture attentive pour des extraits inconnus afin de renforcer leur confiance pour l''épreuve de textes inconnus.","mfe":"Bann elev pratik bann estrateji lekti atantiv pou extre ki pa konpli pou ranforsi zot konfyans pou lepev tex ki pa konpli."}'::jsonb),
('c691a559-31c7-5e6c-8118-73ae93a4b741', 'english-literature', 11, 6, '{"en":"Mastering essay writing techniques","fr":"Maîtriser les techniques de rédaction d''essais","mfe":"Metriz teknik redaksyon lesse"}'::jsonb, '{"en":"Students refine essay planning, argument structure and use of evidence to write higher-scoring literature essays.","fr":"Les élèves affinent la planification des essais, la structure de l''argumentation et l''utilisation des preuves pour rédiger des essais littéraires mieux notés.","mfe":"Bann elev rafinn planifikasyon lesse, striktir largiman ek servi levidans pou ekrir bann lesse literer ki gagn pli bon not."}'::jsonb),
('83bc435b-e1a0-5870-afb0-f1ad6cdaa6d1', 'english-literature', 11, 7, '{"en":"Preparing for the literature examination","fr":"Se préparer à l''examen de littérature","mfe":"Prepar pou lexamen literati"}'::jsonb, '{"en":"Students consolidate learning through timed practice, past paper analysis and targeted revision of all set texts.","fr":"Les élèves consolident leurs apprentissages par des exercices chronométrés, l''analyse d''anciens sujets et une révision ciblée de tous les textes au programme.","mfe":"Bann elev konsolid zot lantiseman atraver pratik ar tan limite, analiz ansien lepev ek revizyon sible tou text ki dan program."}'::jsonb),
