('913529fc-2590-54ca-82b6-290399f59c78', 'mathematics', 12, 8, '{"en":"Integration","fr":"L''intégration","mfe":"Integrasyon"}'::jsonb, '{"en":"Learn integration as the reverse of differentiation and apply it to find areas and solve problems.","fr":"Apprendre l''intégration comme opération inverse de la dérivation et l''appliquer pour calculer des aires et résoudre des problèmes.","mfe":"Aprann integrasyon kouma lopozan diferansiasyon ek aplik li pou trouv sirfas ek rezourd problem."}'::jsonb),
('ac588a67-ff50-5cd8-b28f-f4d248d57ea7', 'mathematics', 13, 1, '{"en":"Algebra and functions","fr":"Algèbre et fonctions","mfe":"Aljèb ek fonksion"}'::jsonb, '{"en":"Extend algebraic techniques to modulus functions, algebraic fractions and partial fractions, building the toolkit needed for Pure Mathematics 3.","fr":"Étendre les techniques algébriques aux fonctions modulaires, aux fractions algébriques et aux fractions partielles, développant les outils nécessaires pour Pure Mathematics 3.","mfe":"Etann bann teknik aljebrik ver fonksion modil, fraksion aljebrik ek fraksion parsyel, pou konstrir zouti neseser pou Pure Mathematics 3."}'::jsonb),
('04e368b1-fbd3-5e1e-8972-60d23f70611c', 'mathematics', 13, 2, '{"en":"Logarithmic and exponential functions","fr":"Fonctions logarithmiques et exponentielles","mfe":"Fonksion logaritmik ek eksponansyel"}'::jsonb, '{"en":"Deepen understanding of exponential and logarithmic functions and use them to model and solve real-world growth and decay problems.","fr":"Approfondir la compréhension des fonctions exponentielles et logarithmiques et les utiliser pour modéliser des problèmes de croissance et de décroissance.","mfe":"Apronfondi konpreansyon fonksion eksponansyel ek logaritmik ek servi zot pou modelize problem kwasans ek diminision."}'::jsonb),
('bdbc5cdc-997d-5887-884e-6b79a20a584a', 'mathematics', 13, 3, '{"en":"Trigonometry beyond the basics","fr":"Trigonométrie avancée","mfe":"Trigonometri avanse"}'::jsonb, '{"en":"Explore further trigonometric identities, compound and multiple angle formulae, and their use in solving complex equations.","fr":"Explorer des identités trigonométriques avancées, les formules d''angles composés et multiples, et leur usage dans la résolution d''équations complexes.","mfe":"Explor bann idantite trigonometrik avanse, formil pou lang kompoze ek miltip, ek zot servi pou rezoud ekwasion konplex."}'::jsonb),
('a925955b-472f-588e-9ed6-0166c873bb5e', 'mathematics', 13, 4, '{"en":"Advanced differentiation","fr":"Dérivation avancée","mfe":"Diferansiasion avanse"}'::jsonb, '{"en":"Extend differentiation techniques to implicit, parametric and further chain-rule applications, applying them to rates of change problems.","fr":"Étendre les techniques de dérivation aux fonctions implicites, paramétriques et aux applications de la règle de chaîne, appliquées aux taux de variation.","mfe":"Etann teknik diferansiasion ver fonksion implisit, parametrik ek plis servis reg sène, aplike ar problem to sanzman."}'::jsonb),
('7cfc11d2-d379-5397-9f4d-d328a460d2cd', 'mathematics', 13, 5, '{"en":"Techniques and applications of integration","fr":"Techniques et applications de l''intégration","mfe":"Teknik ek aplikasion integrasion"}'::jsonb, '{"en":"Master further integration techniques including substitution and by parts, and apply integration to areas, volumes and differential equations.","fr":"Maîtriser des techniques d''intégration avancées, notamment la substitution et l''intégration par parties, et les appliquer aux aires, volumes et équations différentielles.","mfe":"Metrize plis teknik integrasion, kompran sibstitision ek par parti, ek aplik integrasion pou lear, volim ek ekwasion diferansyel."}'::jsonb),
('a4d4184f-9cc0-57d9-b42f-fb1d48733972', 'mathematics', 13, 6, '{"en":"Numerical methods and differential equations","fr":"Méthodes numériques et équations différentielles","mfe":"Metod nimerik ek ekwasion diferansyel"}'::jsonb, '{"en":"Use numerical techniques to locate roots and solve first order differential equations arising from real situations.","fr":"Utiliser des techniques numériques pour localiser des racines et résoudre des équations différentielles du premier ordre issues de situations réelles.","mfe":"Servi teknik nimerik pou lokalize rasin ek rezoud ekwasion diferansyel premie order ki sorti dan sitiasion reel."}'::jsonb),
('ff00495c-2945-5a2c-839e-25d22eded8d2', 'mathematics', 13, 7, '{"en":"Vectors in three dimensions","fr":"Vecteurs en trois dimensions","mfe":"Vekter dan trwa dimansion"}'::jsonb, '{"en":"Extend vector methods to three dimensions, including lines, planes and their intersections, applying vector techniques to geometric problems.","fr":"Étendre les méthodes vectorielles à trois dimensions, y compris les droites, plans et leurs intersections, en appliquant les techniques vectorielles à des problèmes géométriques.","mfe":"Etann metod vektoryel ver trwa dimansion, kompran lign, plan ek zot intersaksion, aplik teknik vektoryel pou problem zeometrik."}'::jsonb),
('8ffa92bd-1b97-58a8-928b-f596fdadd82a', 'mathematics', 13, 8, '{"en":"Probability distributions and hypothesis testing","fr":"Distributions de probabilité et tests d''hypothèses","mfe":"Distribision probabilite ek test ipotez"}'::jsonb, '{"en":"Study the Poisson distribution, sampling and hypothesis testing to draw statistically sound conclusions from data.","fr":"Étudier la distribution de Poisson, l''échantillonnage et les tests d''hypothèses pour tirer des conclusions statistiquement fondées à partir de données.","mfe":"Etidie distribision Poisson, esantiyonaz ek test ipotez pou tir konklizion statistikman solid depi done."}'::jsonb),
('a653a240-5d7c-5b3d-bde6-f3303b80429c', 'physical-education', 7, 1, '{"en":"Introduction to physical education","fr":"Introduction à l''éducation physique","mfe":"Introdiksion a ledikasion fizik"}'::jsonb, '{"en":"Students learn the purpose of physical education, basic safety rules, and how to warm up and cool down properly before physical activity.","fr":"Les élèves découvrent l''objectif de l''éducation physique, les règles de sécurité de base, et apprennent à s''échauffer et à récupérer correctement avant et après l''activité physique.","mfe":"Bann elev aprann bi ledikasion fizik, bann regleman sekirite debaz, ek kouma pou fer echofman ek retour o kalm avan ek apre lekzersis fizik."}'::jsonb),
('73d0ea01-c9df-58fa-b9a1-ba56198ca62e', 'physical-education', 7, 2, '{"en":"Fitness components and testing","fr":"Composantes et tests de la condition physique","mfe":"Bann eleman ek test kondision fizik"}'::jsonb, '{"en":"This unit introduces the main components of physical fitness and simple tests students can use to measure their own fitness levels.","fr":"Cette unité présente les principales composantes de la condition physique et des tests simples pour mesurer son propre niveau de forme.","mfe":"Sa linite la introdir bann prensipal eleman kondision fizik ek bann test senp pou mezir prop nivo fitnes."}'::jsonb),
('634c1cfb-4adf-566a-ae3e-d6f5ce3a3598', 'physical-education', 7, 3, '{"en":"Athletics fundamentals","fr":"Fondamentaux de l''athlétisme","mfe":"Bann fondaman letletis"}'::jsonb, '{"en":"Students develop basic running, jumping and throwing techniques used across different athletics events.","fr":"Les élèves développent les techniques de base de course, saut et lancer utilisées dans différentes épreuves d''athlétisme.","mfe":"Bann elev devlop bann teknik debaz kouri, sote ek lanse ki servi dan diferan lepev letletis."}'::jsonb),
('a3a50a1f-fb61-5308-b78a-b1e9b6bd3ef3', 'physical-education', 7, 4, '{"en":"Team games: football and handball","fr":"Jeux collectifs : football et handball","mfe":"Zwe lekip: foutbol ek handball"}'::jsonb, '{"en":"Students learn basic skills, rules and teamwork strategies in football and handball.","fr":"Les élèves apprennent les compétences de base, les règles et les stratégies d''équipe au football et au handball.","mfe":"Bann elev aprann bann konpetans debaz, regleman ek stratezi lekip dan foutbol ek handball."}'::jsonb),
('1343c0ff-b176-513f-9f33-e243b4727b65', 'physical-education', 7, 5, '{"en":"Gymnastics and body movement","fr":"Gymnastique et mouvement corporel","mfe":"Zimnastik ek mouvman lekor"}'::jsonb, '{"en":"This unit builds body control, balance and coordination through simple gymnastic movements and sequences.","fr":"Cette unité développe le contrôle corporel, l''équilibre et la coordination à travers des mouvements et enchaînements gymniques simples.","mfe":"Sa linite la devlop kontrol lekor, lekilib ek kordinasion atraver bann mouvman ek sekans zimnastik senp."}'::jsonb),
('0462b0d5-e77b-5ef7-bdd9-3ec5cddbdb96', 'physical-education', 7, 6, '{"en":"Racket sports basics","fr":"Bases des sports de raquette","mfe":"Baz bann sport raket"}'::jsonb, '{"en":"Students are introduced to badminton and table tennis, focusing on grip, basic strokes and simple rules.","fr":"Les élèves découvrent le badminton et le tennis de table, en se concentrant sur la prise, les coups de base et les règles simples.","mfe":"Bann elev dekouver badminton ek tennis de table, konsantre lor lasenn, bann kout debaz ek regleman senp."}'::jsonb),
('66d20d42-09bd-5e69-b274-69e28e0b4157', 'physical-education', 7, 7, '{"en":"Traditional and cultural games","fr":"Jeux traditionnels et culturels","mfe":"Bann zwe tradisionel ek kiltirel"}'::jsonb, '{"en":"Students explore traditional Mauritian games and outdoor activities that promote physical activity and cultural appreciation.","fr":"Les élèves explorent des jeux traditionnels mauriciens et des activités de plein air qui favorisent l''activité physique et l''appréciation culturelle.","mfe":"Bann elev explor bann zwe tradisionel morisien ek aktivite deor ki promouvwar lativite fizik ek lapresiasion kiltirel."}'::jsonb),
('cecf1649-4272-58bd-92b2-9110089e3fd5', 'physical-education', 8, 1, '{"en":"Fitness components and testing","fr":"Composantes de la condition physique et tests","mfe":"Bann eleman fitnes ek test"}'::jsonb, '{"en":"Students explore the main components of physical fitness and learn simple methods to test and track their own fitness levels.","fr":"Les élèves explorent les principales composantes de la condition physique et apprennent des méthodes simples pour tester et suivre leur propre niveau de forme.","mfe":"Bann elev explor bann prensipal eleman fitnes fizik ek aprann bann metod sinp pou teste ek swiv zot prop nivo fitnes."}'::jsonb),
('ccc79075-b422-5bcf-b031-6ae4f39417c7', 'physical-education', 8, 2, '{"en":"Athletics skills development","fr":"Développement des compétences en athlétisme","mfe":"Devlopman ladres atletism"}'::jsonb, '{"en":"Students develop running, jumping and throwing techniques used in track and field athletics.","fr":"Les élèves développent des techniques de course, de saut et de lancer utilisées en athlétisme.","mfe":"Bann elev devlop teknik kouri, sote ek lanse itilize dan atletism."}'::jsonb),
('ecf3407e-a315-565b-847d-3866daac48b9', 'physical-education', 8, 3, '{"en":"Football skills and small games","fr":"Compétences en football et petits jeux","mfe":"Ladres foutbol ek pti zwe"}'::jsonb, '{"en":"Students build ball control, passing and teamwork skills through football drills and modified games.","fr":"Les élèves développent le contrôle du ballon, les passes et le travail d''équipe grâce à des exercices et jeux modifiés de football.","mfe":"Bann elev devlop kontrol balon, pas ek travay lekip atraver egzersis ek zwe modifye foutbol."}'::jsonb),
('e0a86885-50e3-5f7f-aac7-d68194d99c1f', 'physical-education', 8, 4, '{"en":"Volleyball fundamentals","fr":"Fondamentaux du volley-ball","mfe":"Bann fondaman volebol"}'::jsonb, '{"en":"Students learn the basic techniques and rules of volleyball while practising in pairs and small teams.","fr":"Les élèves apprennent les techniques de base et les règles du volley-ball tout en s''exerçant en binômes et en petites équipes.","mfe":"Bann elev aprann bann teknik debaz ek regleman volebol pandan zot pratike an per ek an pti lekip."}'::jsonb),
('486fdd7a-8307-5d3e-ae13-2d46a4d816da', 'physical-education', 8, 5, '{"en":"Gymnastics and body movement","fr":"Gymnastique et mouvement corporel","mfe":"Zimnastik ek mouvman lekor"}'::jsonb, '{"en":"Students explore balance, flexibility and control through basic gymnastic movements and sequences.","fr":"Les élèves explorent l''équilibre, la souplesse et le contrôle à travers des mouvements et enchaînements gymniques de base.","mfe":"Bann elev explor balans, fleksibilite ek kontrol atraver bann mouvman ek sekans zimnastik debaz."}'::jsonb),
('bf356651-7d06-5799-81a8-f0568d645bd6', 'physical-education', 8, 6, '{"en":"Health, nutrition and hygiene","fr":"Santé, nutrition et hygiène","mfe":"Lasante, nitrisyon ek ligyenn"}'::jsonb, '{"en":"Students learn about healthy eating, hygiene practices and lifestyle choices that support an active life.","fr":"Les élèves apprennent une alimentation saine, des pratiques d''hygiène et des choix de mode de vie favorisant une vie active.","mfe":"Bann elev aprann manzer sante, pratik ligyenn ek swa lastil lavi ki soutenir enn lavi aktif."}'::jsonb),
('55bb9f92-1881-5029-bc77-3b4312f78462', 'physical-education', 8, 7, '{"en":"Traditional games and Mauritian culture","fr":"Jeux traditionnels et culture mauricienne","mfe":"Zwe tradisyonel ek kiltir morisien"}'::jsonb, '{"en":"Students explore traditional Mauritian games and movement activities that reflect the island''s cultural diversity.","fr":"Les élèves découvrent des jeux traditionnels mauriciens et des activités de mouvement reflétant la diversité culturelle de l''île.","mfe":"Bann elev explor zwe tradisyonel morisien ek aktivite mouvman ki reflet diversite kiltirel lil."}'::jsonb),
('6a9173a6-8f99-546c-9f17-cbe9a4aaa129', 'physical-education', 9, 1, '{"en":"Health-related fitness","fr":"Condition physique liée à la santé","mfe":"Bonn fizik pou lasante"}'::jsonb, '{"en":"Students explore the components of health-related fitness and learn how regular physical activity contributes to a healthy lifestyle.","fr":"Les élèves explorent les composantes de la condition physique liée à la santé et apprennent comment l''activité physique régulière contribue à un mode de vie sain.","mfe":"Bann elev explor bann eleman bonn fizik ki lié ar lasante ek aprann kouma lexersis fizik regilie kontribie dan enn lavi ansante."}'::jsonb),
('a6e83175-ebd0-5593-b43b-e54dcbaa1421', 'physical-education', 9, 2, '{"en":"Athletics skills and events","fr":"Compétences et épreuves d''athlétisme","mfe":"Konpetans ek lepev atletism"}'::jsonb, '{"en":"Students develop technique in track and field events, focusing on running, jumping and throwing skills used in school competitions.","fr":"Les élèves développent leur technique dans les épreuves d''athlétisme, en se concentrant sur la course, le saut et le lancer utilisés dans les compétitions scolaires.","mfe":"Bann elev devlop teknik dan lepev atletism, konsantre lor kouri, sote ek lanse ki servi dan konpetision lekol."}'::jsonb),
('059724ca-978f-5cda-a6c8-30827c356878', 'physical-education', 9, 3, '{"en":"Invasion games: football and handball","fr":"Jeux d''invasion : football et handball","mfe":"Zwe lekip: football ek handball"}'::jsonb, '{"en":"Students build tactical understanding and skills for invasion games, applying attacking and defending strategies in small-sided games.","fr":"Les élèves développent leur compréhension tactique et leurs compétences pour les jeux d''invasion, en appliquant des stratégies d''attaque et de défense.","mfe":"Bann elev devlop konpreansion taktik ek konpetans pou zwe lekip, applik strateji atak ek defans dan pti zwe."}'::jsonb),
('808237e7-053b-537f-87ae-c10bd3d3e332', 'physical-education', 9, 4, '{"en":"Net and court games","fr":"Jeux de filet et de terrain","mfe":"Zwe file ek teren"}'::jsonb, '{"en":"Students refine skills in badminton and volleyball, learning rules, scoring and simple tactics for competitive play.","fr":"Les élèves affinent leurs compétences en badminton et en volley-ball, en apprenant les règles, le comptage des points et des tactiques simples.","mfe":"Bann elev amelior konpetans dan badminton ek volleyball, aprann bann regleman, kont pwin ek taktik senp."}'::jsonb),
('41839b1d-9a14-50f3-b70b-53b527ff6b50', 'physical-education', 9, 5, '{"en":"Gymnastics and body movement","fr":"Gymnastique et mouvement corporel","mfe":"Zimnastik ek mouvman lekor"}'::jsonb, '{"en":"Students explore balance, flexibility and coordination through gymnastics sequences performed individually and in groups.","fr":"Les élèves explorent l''équilibre, la souplesse et la coordination à travers des séquences de gymnastique individuelles et en groupe.","mfe":"Bann elev explor balans, souples ek kordinasion atraver sekans zimnastik individiel ek an group."}'::jsonb),
('510bbcfd-7b29-553c-b4f7-5b4756fcce34', 'physical-education', 9, 6, '{"en":"Growth, development and safety","fr":"Croissance, développement et sécurité","mfe":"Krwasans, devlopman ek sekirite"}'::jsonb, '{"en":"Students learn about physical changes during adolescence and how to stay safe while participating in sport and exercise.","fr":"Les élèves apprennent les changements physiques de l''adolescence et comment rester en sécurité lors du sport et de l''exercice.","mfe":"Bann elev aprann lor bann sanzman fizik pandan ladolesans ek kouma reste an sekirite pandan sport ek lexersis."}'::jsonb),
('4f3f7c04-b97e-5886-8425-775c8dc8e438', 'physical-education', 9, 7, '{"en":"Leisure, recreation and lifelong activity","fr":"Loisirs, récréation et activité physique à vie","mfe":"Lwazir, rekreasion ek aktivite pou lavi"}'::jsonb, '{"en":"Students explore leisure activities available in Mauritius and consider how to remain physically active throughout life.","fr":"Les élèves explorent les activités de loisirs disponibles à Maurice et réfléchissent à comment rester actifs toute leur vie.","mfe":"Bann elev explor bann aktivite lwazir disponib Moris ek reflesi lor kouma reste aktif pandan tou lavi."}'::jsonb),
('4336f454-4290-552d-8b81-b16480431701', 'physical-education', 10, 1, '{"en":"The skeletal system","fr":"Le système squelettique","mfe":"Sistem lezo"}'::jsonb, '{"en":"Students explore the structure and functions of the skeleton, types of bones and joints, and how these relate to movement in sport.","fr":"Les élèves explorent la structure et les fonctions du squelette, les types d''os et d''articulations, et leur lien avec le mouvement sportif.","mfe":"Elev examine striktir ek fonksion lezo, diferan tip lezo ek zwenti, ek kouma sa relye ar mouvman dan sport."}'::jsonb),
('912129e4-daa2-5489-9124-eb19db120d0f', 'physical-education', 10, 2, '{"en":"The muscular system","fr":"Le système musculaire","mfe":"Sistem miskilo"}'::jsonb, '{"en":"Students study major muscles, muscle contraction types and how muscles work together to produce sporting movement.","fr":"Les élèves étudient les principaux muscles, les types de contraction musculaire et leur coopération pour produire le mouvement sportif.","mfe":"Elev etidie prensipal miskilo, tip kontraksion miskilo ek kouma zot travay ansam pou fer mouvman dan sport."}'::jsonb),
('294213ff-715f-526a-95df-016e613c5d1e', 'physical-education', 10, 3, '{"en":"Cardiovascular and respiratory systems","fr":"Systèmes cardiovasculaire et respiratoire","mfe":"Sistem kardiovaskiler ek respiratwar"}'::jsonb, '{"en":"This unit covers the structure and function of the heart, blood vessels and lungs, and how they respond to exercise.","fr":"Cette unité couvre la structure et la fonction du cœur, des vaisseaux sanguins et des poumons, et leur réponse à l''exercice.","mfe":"Sa liniter la kouver striktir ek fonksion leker, vesso sangen ek poumon, ek kouma zot reponn a lexersis."}'::jsonb),
('2b85d621-f699-5c58-8c6c-5eba72b136e5', 'physical-education', 10, 4, '{"en":"Movement analysis","fr":"Analyse du mouvement","mfe":"Analiz mouvman"}'::jsonb, '{"en":"Students learn to analyse sporting movements using lever systems, planes and axes of movement.","fr":"Les élèves apprennent à analyser les mouvements sportifs à l''aide des systèmes de leviers, des plans et des axes de mouvement.","mfe":"Elev aprann analiz mouvman sportif atraver sistem levie, plan ek aks mouvman."}'::jsonb),
('4f5291ec-c996-50bc-994c-507ebf8e3e86', 'physical-education', 10, 5, '{"en":"Components of physical fitness","fr":"Composantes de la condition physique","mfe":"Konpozan kondisyon fizik"}'::jsonb, '{"en":"This unit introduces health-related and skill-related components of fitness and methods to measure them.","fr":"Cette unité introduit les composantes de la condition physique liées à la santé et aux compétences, ainsi que leurs méthodes de mesure.","mfe":"Sa liniter la introdir konpozan kondisyon fizik lie ar lasante ek konpetans, ek metod pou mezir zot."}'::jsonb),
('6b2ad179-a144-599b-b4ab-d0b758cd0105', 'physical-education', 10, 6, '{"en":"Training methods and principles","fr":"Méthodes et principes d''entraînement","mfe":"Metod ek prensip lantrennman"}'::jsonb, '{"en":"Students examine different training methods and the principles of training used to improve performance safely.","fr":"Les élèves examinent différentes méthodes d''entraînement et les principes utilisés pour améliorer la performance en toute sécurité.","mfe":"Elev examine diferan metod lantrennman ek prensip lantrennman servi pou ameliyor perfomans an sekirite."}'::jsonb),
('a807a4d9-39cf-5850-acae-878c1862c05b', 'physical-education', 10, 7, '{"en":"Diet, nutrition and performance","fr":"Alimentation, nutrition et performance","mfe":"Rezim, nitrision ek perfomans"}'::jsonb, '{"en":"This unit looks at the role of nutrients, hydration and diet planning in supporting sporting performance and recovery.","fr":"Cette unité examine le rôle des nutriments, de l''hydratation et de la planification alimentaire dans la performance et la récupération sportives.","mfe":"Sa liniter la gete rol nitriman, ideratasion ek planifikasion rezim pou soutenir perfomans sportif ek rekiperasion."}'::jsonb),
('f1d3bfe8-06fc-5d42-9b73-88620dd3f2a5', 'physical-education', 10, 8, '{"en":"Participation and sport in society","fr":"Participation et le sport dans la société","mfe":"Partisipasion ek sport dan lasosiete"}'::jsonb, '{"en":"Students explore reasons for participation, factors affecting access to sport, and the influence of media and technology on sport.","fr":"Les élèves explorent les raisons de la participation, les facteurs affectant l''accès au sport, et l''influence des médias et de la technologie sur le sport.","mfe":"Elev explor rezon partisipasion, fakter ki afekte lakse a sport, ek lenfliyans media ek teknolozi lor sport."}'::jsonb),
('3928e3c7-f2a0-5836-8fb6-1167624dcb47', 'physical-education', 11, 1, '{"en":"Applied anatomy and physiology","fr":"Anatomie et physiologie appliquées","mfe":"Anatomi ek fizyoloji aplike"}'::jsonb, '{"en":"Explore how the skeletal, muscular, cardiovascular and respiratory systems work together to enable movement and exercise performance.","fr":"Découvrir comment les systèmes squelettique, musculaire, cardiovasculaire et respiratoire fonctionnent ensemble pour permettre le mouvement et la performance sportive.","mfe":"Explor kouma sistem skwelet, miskilar, kardyovaskiler ek respiratwar travay ansam pou permet mouvman ek performans sportif."}'::jsonb),
('9b454aff-babb-58f1-977d-a4b835cb1fe8', 'physical-education', 11, 2, '{"en":"Movement analysis","fr":"Analyse du mouvement","mfe":"Lanaliz mouvman"}'::jsonb, '{"en":"Apply concepts of levers, planes and axes to analyse sporting techniques and improve performance.","fr":"Appliquer les concepts de leviers, de plans et d''axes pour analyser les techniques sportives et améliorer la performance.","mfe":"Aplik konsep levye, plan ek aks pou analiz teknik sportif ek ameliyor performans."}'::jsonb),
('5077c12f-16f6-507b-b63c-64edf32fbb67', 'physical-education', 11, 3, '{"en":"Principles and methods of training","fr":"Principes et méthodes d''entraînement","mfe":"Prensip ek metod lantrennman"}'::jsonb, '{"en":"Learn how training principles and different training methods are used to improve components of fitness.","fr":"Apprendre comment les principes d''entraînement et différentes méthodes sont utilisés pour améliorer les composantes de la condition physique.","mfe":"Aprann kouma prensip lantrennman ek diferan metod lantrennman servi pou ameliyor bann konpozan fitnes."}'::jsonb),
('4a63a2eb-0e67-57f9-acdc-056e280834cf', 'physical-education', 11, 4, '{"en":"Health, fitness and wellbeing","fr":"Santé, forme et bien-être","mfe":"Lasante, fitnes ek byennet"}'::jsonb, '{"en":"Understand the relationship between diet, health, injury prevention and long-term physical wellbeing.","fr":"Comprendre la relation entre l''alimentation, la santé, la prévention des blessures et le bien-être physique à long terme.","mfe":"Konpran relasyon ant nourritir, lasante, prevansyon blesir ek byennet fizik lontan."}'::jsonb),
('dd3d68d7-9f3c-542e-a492-f805a62c6e3f', 'physical-education', 11, 5, '{"en":"Skill acquisition and learning","fr":"Acquisition des compétences et apprentissage","mfe":"Akizisyon konpetans ek laprantisaz"}'::jsonb, '{"en":"Examine how skills are classified, learned and refined through practice, guidance and feedback.","fr":"Examiner comment les habiletés sont classées, apprises et perfectionnées grâce à la pratique, aux conseils et au feedback.","mfe":"Examinn kouma konpetans klasifye, aprann ek amelyore atraver pratik, gidans ek feedback."}'::jsonb),
('417554ae-d014-59d4-bd2e-9f1c2122fee5', 'physical-education', 11, 6, '{"en":"Sports psychology and performance","fr":"Psychologie du sport et performance","mfe":"Sikoloji sportif ek performans"}'::jsonb, '{"en":"Investigate psychological factors such as motivation, arousal and personality that influence sporting performance.","fr":"Étudier les facteurs psychologiques tels que la motivation, l''excitation et la personnalité qui influencent la performance sportive.","mfe":"Etidye bann fakter sikolozik kouma motivasyon, arousal ek personalite ki enfliyans performans sportif."}'::jsonb),
('5b814144-df28-5756-a1f9-915900f5e28f', 'physical-education', 11, 7, '{"en":"Socio-cultural influences on sport","fr":"Influences socioculturelles sur le sport","mfe":"Lenfliyans sosyokiltirel lor sport"}'::jsonb, '{"en":"Consider social, cultural and economic factors that affect participation and provision of sport in Mauritius and beyond.","fr":"Considérer les facteurs sociaux, culturels et économiques qui affectent la participation et l''offre sportive à Maurice et ailleurs.","mfe":"Konsider fakter sosyal, kiltirel ek ekonomik ki afekte partisipasyon ek lofer sport dan Moris ek aylaris."}'::jsonb),
('1e2d3aaa-0629-56e7-9791-cc6f3dbaa63e', 'physical-education', 11, 8, '{"en":"Using data to evaluate performance","fr":"Utiliser les données pour évaluer la performance","mfe":"Servi done pou evalye performans"}'::jsonb, '{"en":"Develop skills to collect, interpret and use performance data to improve training and competitive outcomes.","fr":"Développer des compétences pour collecter, interpréter et utiliser des données de performance afin d''améliorer l''entraînement et les résultats compétitifs.","mfe":"Devlop konpetans pou kolekte, entèprete ek servi done performans pou ameliyor lantrennman ek rezilta konpetitif."}'::jsonb),
('7122d9dd-6c73-5dc7-8f39-396f7a3e3f67', 'physical-education', 12, 1, '{"en":"Skeletal and muscular systems","fr":"Systèmes squelettique et musculaire","mfe":"Sistem lezo ek miskil"}'::jsonb, '{"en":"Study the structure and function of the skeletal and muscular systems and how they enable movement during physical activity.","fr":"Étudier la structure et la fonction des systèmes squelettique et musculaire et leur rôle dans le mouvement lors de l''activité physique.","mfe":"Etidie striktir ek fonksion sistem lezo ek miskil ek kouma zot permet mouvman pandan lekzersis fizik."}'::jsonb),
('2a3b1f5a-eaf6-52ed-b5c1-673cfb5b7e4c', 'physical-education', 12, 2, '{"en":"Cardiorespiratory system and exercise","fr":"Système cardiorespiratoire et exercice","mfe":"Sistem kardio-respiratwar ek lekzersis"}'::jsonb, '{"en":"Examine how the heart, blood vessels and lungs respond and adapt to exercise demands.","fr":"Examiner comment le cœur, les vaisseaux sanguins et les poumons réagissent et s''adaptent à l''effort physique.","mfe":"Egzamine kouma leker, vezo sang ek poumon reazir ek adapte ar bezwin lekzersis."}'::jsonb),
('4a171323-e948-5a46-b5c7-44e51ae5ca1c', 'physical-education', 12, 3, '{"en":"Energy systems and nutrition","fr":"Systèmes énergétiques et nutrition","mfe":"Sistem lenerzi ek nitrision"}'::jsonb, '{"en":"Explore how the body produces energy for exercise and the role of nutrition in supporting performance.","fr":"Explorer comment le corps produit de l''énergie pour l''exercice et le rôle de la nutrition dans la performance.","mfe":"Explor kouma lekor prodir lenerzi pou lekzersis ek rol nitrision dan performans."}'::jsonb),
('52c3705c-d63d-516f-b666-ae71e0df5481', 'physical-education', 12, 4, '{"en":"Skill acquisition and learning","fr":"Acquisition des habiletés et apprentissage","mfe":"Aprantisaz konpetans"}'::jsonb, '{"en":"Understand how skills are classified, learned and refined through practice and feedback.","fr":"Comprendre comment les habiletés sont classées, apprises et perfectionnées grâce à la pratique et au retour d''information.","mfe":"Konpran kouma konpetans klasifie, aprann ek amelior par pratik ek fidbak."}'::jsonb),
('4ce478c0-646e-5493-8c2b-c9ad650533b2', 'physical-education', 12, 5, '{"en":"Information processing and memory","fr":"Traitement de l''information et mémoire","mfe":"Trètman linformasion ek memwar"}'::jsonb, '{"en":"Analyse how performers receive, process and respond to information during sporting performance.","fr":"Analyser comment les sportifs reçoivent, traitent et répondent à l''information durant la performance sportive.","mfe":"Analiz kouma sportif resevwar, trete ek reponn a linformasion pandan performans sportif."}'::jsonb),
('50fdedca-17a0-5b7e-a234-a09557294d5a', 'physical-education', 12, 6, '{"en":"Sport psychology foundations","fr":"Fondements de la psychologie du sport","mfe":"Bann baz sikolozi spor"}'::jsonb, '{"en":"Investigate personality, motivation and arousal and their influence on sporting performance.","fr":"Étudier la personnalité, la motivation et l''excitation et leur influence sur la performance sportive.","mfe":"Investig personalite, motivasion ek arouzman ek zot lenfliyans lor performans sportif."}'::jsonb),
('a4859793-eca2-50c2-8015-adae6881a5df', 'physical-education', 12, 7, '{"en":"Participation and provision in Mauritius","fr":"Participation et offre sportive à Maurice","mfe":"Partisipasion ek lofer sportif Moris"}'::jsonb, '{"en":"Explore factors influencing participation in physical activity and the provision of sport in Mauritian society.","fr":"Explorer les facteurs influençant la participation à l''activité physique et l''offre sportive dans la société mauricienne.","mfe":"Explor bann fakter ki lenfliyans partisipasion dan lekzersis fizik ek lofer spor dan sosiete morisien."}'::jsonb),
('f879f411-22c1-5f44-ae17-b204a57bcc09', 'physical-education', 13, 1, '{"en":"Energy systems and fatigue","fr":"Systèmes énergétiques et fatigue","mfe":"Sistem enerzetik ek fatig"}'::jsonb, '{"en":"Advanced study of ATP resynthesis, the three energy systems, and causes and management of fatigue in elite performance.","fr":"Étude avancée de la resynthèse de l''ATP, des trois systèmes énergétiques, et des causes et gestion de la fatigue chez les athlètes de haut niveau.","mfe":"Etid avanse lor resintez ATP, trwa sistem enerzetik, ek kozz ek zestion fatig kot bann atlet elit."}'::jsonb),
('09918774-3868-547b-b13c-fea788bb67f4', 'physical-education', 13, 2, '{"en":"Biomechanical principles of movement","fr":"Principes biomécaniques du mouvement","mfe":"Prinsip biomekanik mouvman"}'::jsonb, '{"en":"In-depth analysis of angular motion, projectile motion, and fluid mechanics applied to sporting techniques.","fr":"Analyse approfondie du mouvement angulaire, du mouvement de projectile et de la mécanique des fluides appliquée aux techniques sportives.","mfe":"Analiz an profonder mouvman angiler, mouvman proziktil, ek mekanik fliyid aplike ar teknik sportif."}'::jsonb),
('a3705d64-07c6-5469-8c6a-ebd68ac7dd47', 'physical-education', 13, 3, '{"en":"Advanced skill acquisition","fr":"Acquisition avancée des habiletés","mfe":"Akizisyon avanse konpetans"}'::jsonb, '{"en":"Exploration of memory models, transfer of learning, and advanced theories explaining skilled performance.","fr":"Exploration des modèles de mémoire, du transfert d''apprentissage et des théories avancées expliquant la performance habile.","mfe":"Eksploration bann modenn memwar, transfer laprantisaz, ek teori avanse ki explik parformans abil."}'::jsonb),
('592d2dc9-e660-5e54-82ef-c4cc730dbc7e', 'physical-education', 13, 4, '{"en":"Psychological factors affecting performance","fr":"Facteurs psychologiques influençant la performance","mfe":"Fakter psikolozik ki afekte parformans"}'::jsonb, '{"en":"Study of aggression, motivation, self-confidence and group dynamics influencing elite sporting performance.","fr":"Étude de l''agressivité, de la motivation, de la confiance en soi et de la dynamique de groupe influençant la performance sportive d''élite.","mfe":"Etid agresivite, motivasyon, konfyans an swa ek dinamik lekip ki influans parformans sportif elit."}'::jsonb),
('99461a62-b39e-5a5a-8635-1e58b6304c06', 'physical-education', 13, 5, '{"en":"Sport, technology and ethics","fr":"Sport, technologie et éthique","mfe":"Sport, teknolozi ek letik"}'::jsonb, '{"en":"Examination of technological advances, ethical issues and drugs in sport at elite and international levels.","fr":"Examen des avancées technologiques, des questions éthiques et du dopage dans le sport aux niveaux élite et international.","mfe":"Egzaminasyon avansman teknolozik, kestion letik ek dopaz dan sport nivo elit ek internasional."}'::jsonb),
('7fa4f871-90fd-5387-968d-309c35b666c5', 'physical-education', 13, 6, '{"en":"Optimising training and performance","fr":"Optimisation de l''entraînement et de la performance","mfe":"Optimizasyon lantrenman ek parformans"}'::jsonb, '{"en":"Application of periodisation, training thresholds and altitude training to design elite training programmes.","fr":"Application de la périodisation, des seuils d''entraînement et de l''entraînement en altitude pour concevoir des programmes d''entraînement d''élite.","mfe":"Aplikasyon periodizasyon, sey lantrenman ek lantrenman an altitid pou desine program lantrenman elit."}'::jsonb),
('f8c1ce40-6114-5061-8f57-622783b15c5d', 'physical-education', 13, 7, '{"en":"Preparing for advanced assessment","fr":"Préparation à l''évaluation avancée","mfe":"Prepar pou levaliasyon avanse"}'::jsonb, '{"en":"Consolidation of A2 theory and practical skills to prepare for HSC examinations and performance assessment.","fr":"Consolidation de la théorie A2 et des compétences pratiques pour préparer les examens du HSC et l''évaluation de performance.","mfe":"Konsolidasyon teori A2 ek konpetans pratik pou prepar lekzame HSC ek levaliasyon parformans."}'::jsonb),
('c670ae65-9d7d-5c4d-8cc3-7c850ca6d15a', 'physics', 7, 1, '{"en":"Measurement and scientific method","fr":"Mesure et démarche scientifique","mfe":"Mezir ek metod syantifik"}'::jsonb, '{"en":"Students learn how scientists observe, measure and record data using correct units and simple apparatus, building the foundation for all physics investigations.","fr":"Les élèves apprennent comment les scientifiques observent, mesurent et enregistrent des données en utilisant des unités correctes et des appareils simples, posant les bases de toute investigation en physique.","mfe":"Bann elev aprann kouma bann syantis observe, mezire ek anrezistre done avek bann linite korek ek bann laparey sinp, sa form baz pou tou bann investigasyon fizik."}'::jsonb),
('da30908a-6ba8-5f05-8762-1d6d5b18a65e', 'physics', 7, 2, '{"en":"States of matter","fr":"Les états de la matière","mfe":"Bann eta matyer"}'::jsonb, '{"en":"This unit explores solids, liquids and gases through the particle model, explaining everyday changes of state observed in Mauritius.","fr":"Cette unité explore les solides, les liquides et les gaz à travers le modèle particulaire, expliquant les changements d''état observés au quotidien à Maurice.","mfe":"Sa lini-la explor bann solid, likid ek gaz atraver model partikil, ek explik bann sanzman leta ki nou observe dan lavi tou-le-zour Moris."}'::jsonb),
('c38e8448-e82a-5d45-adcd-d6f3a57c8477', 'physics', 7, 3, '{"en":"Forces and their effects","fr":"Les forces et leurs effets","mfe":"Bann fors ek zot lefe"}'::jsonb, '{"en":"Students investigate different types of forces, how they change motion and shape, and learn to measure force using a newton meter.","fr":"Les élèves étudient différents types de forces, comment elles modifient le mouvement et la forme, et apprennent à mesurer une force avec un dynamomètre.","mfe":"Bann elev examine diferan tip fors, kouma zot sanz mouvman ek form, ek aprann mezir fors avek enn nyoutonmet."}'::jsonb),
('c01fc0d2-7d5e-590a-8660-f88a8b842e32', 'physics', 7, 4, '{"en":"Energy around us","fr":"L''énergie autour de nous","mfe":"Lenerzi otour nou"}'::jsonb, '{"en":"This unit introduces different forms of energy, energy sources used in Mauritius, and the idea that energy can change from one form to another.","fr":"Cette unité présente les différentes formes d''énergie, les sources d''énergie utilisées à Maurice, et l''idée que l''énergie peut se transformer d''une forme à une autre.","mfe":"Sa lini-la introdir diferan form lenerzi, bann sours lenerzi ki servi Moris, ek lide ki lenerzi kapav sanz form."}'::jsonb),
('3899d35d-68da-5844-96b4-60a9db4b69b0', 'physics', 7, 5, '{"en":"Light and shadows","fr":"La lumière et les ombres","mfe":"Lalimyer ek lonbraz"}'::jsonb, '{"en":"Students explore how light travels, how shadows are formed, and how light interacts with mirrors and different materials.","fr":"Les élèves explorent comment la lumière se propage, comment les ombres se forment et comment la lumière interagit avec les miroirs et différents matériaux.","mfe":"Bann elev explor kouma lalimyer voyaze, kouma lonbraz forme, ek kouma lalimyer aze avek bann miwar ek diferan materyo."}'::jsonb),
('02685ec7-02fb-59b1-bb37-4e551727445f', 'physics', 7, 6, '{"en":"Sound and hearing","fr":"Le son et l''audition","mfe":"Son ek lekout"}'::jsonb, '{"en":"This unit covers how sound is produced, how it travels, and how our ears detect sound, with attention to noise and hearing safety.","fr":"Cette unité traite de la production du son, de sa propagation et de la manière dont nos oreilles le détectent, en insistant sur le bruit et la sécurité auditive.","mfe":"Sa lini-la kouver kouma son prodwir, kouma li voyaze, ek kouma nou zorey detekte son, avek latansyon lor bri ek sekirite lekout."}'::jsonb),
('745bbb5d-6236-5902-92c0-f90b1e8c7609', 'physics', 7, 7, '{"en":"Magnetism and static electricity","fr":"Magnétisme et électricité statique","mfe":"Manyetis ek elektrisite statik"}'::jsonb, '{"en":"Students investigate magnetic materials and forces, and are introduced to static electricity and its everyday effects.","fr":"Les élèves étudient les matériaux et forces magnétiques, et découvrent l''électricité statique et ses effets quotidiens.","mfe":"Bann elev examine bann materyo ek fors manyetik, ek zot introdir avek elektrisite statik ek so bann lefe dan lavi tou-le-zour."}'::jsonb),
('9dd51330-5b80-581d-a74d-08d881ee59d6', 'physics', 8, 1, '{"en":"Measurement and scientific method","fr":"Mesure et méthode scientifique","mfe":"Mezir ek metod syantifik"}'::jsonb, '{"en":"Students revise measurement skills and learn how scientists plan and carry out fair investigations.","fr":"Les élèves révisent les compétences de mesure et apprennent comment les scientifiques planifient et réalisent des expériences équitables.","mfe":"Bann elev revize kompetans mezir ek aprann kouma bann syantis planifie ek fer bann lanket ekitab."}'::jsonb),
('db327f51-9587-54c9-9db0-2d30282b2ca7', 'physics', 8, 2, '{"en":"Matter and its states","fr":"La matière et ses états","mfe":"Matyer ek so bann leta"}'::jsonb, '{"en":"This unit explores the particle model of matter and explains changes of state observed in daily life.","fr":"Cette unité explore le modèle particulaire de la matière et explique les changements d''état observés au quotidien.","mfe":"Sa linite-la explor modelparticil matyer ek explik chanzman leta ki nou observ dan lavi toulezour."}'::jsonb),
('b48f282d-fd63-59fd-8184-5badae69bb9d', 'physics', 8, 3, '{"en":"Forces and their effects","fr":"Les forces et leurs effets","mfe":"Bann fors ek zot lefe"}'::jsonb, '{"en":"Students investigate different types of forces and how they change the motion and shape of objects.","fr":"Les élèves étudient différents types de forces et comment elles modifient le mouvement et la forme des objets.","mfe":"Bann elev etidie diferan tip fors ek kouma zot sanz mouvman ek form bann lobze."}'::jsonb),
('2dc41c40-9be4-5373-a89c-728864c6fa5d', 'physics', 8, 4, '{"en":"Energy and its transformations","fr":"L''énergie et ses transformations","mfe":"Lenerzi ek so bann transformasyon"}'::jsonb, '{"en":"This unit introduces forms of energy, how energy changes from one form to another, and the idea of energy conservation.","fr":"Cette unité présente les formes d''énergie, la transformation de l''énergie et le principe de conservation de l''énergie.","mfe":"Sa linite-la introdir bann form lenerzi, kouma lenerzi sanz form ek prinsip konservasion lenerzi."}'::jsonb),
('99760a82-da1e-5f04-b0f0-7af42264c6c7', 'physics', 8, 5, '{"en":"Heat and temperature","fr":"La chaleur et la température","mfe":"Chalar ek tanperatir"}'::jsonb, '{"en":"Students learn the difference between heat and temperature and explore how heat is transferred between objects.","fr":"Les élèves apprennent la différence entre chaleur et température et explorent les modes de transfert de chaleur.","mfe":"Bann elev aprann diferans ant chalar ek tanperatir ek explor kouma chalar transfer ant bann lobze."}'::jsonb),
('de028320-f325-5aa3-88c0-3f19c6767bdc', 'physics', 8, 6, '{"en":"Light and sound waves","fr":"Ondes lumineuses et sonores","mfe":"Bann onn limyer ek son"}'::jsonb, '{"en":"This unit examines the basic properties of light and sound and how they travel and interact with materials.","fr":"Cette unité examine les propriétés de base de la lumière et du son et leur propagation à travers les matériaux.","mfe":"Sa linite-la examine bann propriete debaz limyer ek son ek kouma zot propaz atraver bann materio."}'::jsonb),
('56ce044d-f565-5a3d-960e-7caf75904352', 'physics', 8, 7, '{"en":"Electricity and magnetism basics","fr":"Bases de l''électricité et du magnétisme","mfe":"Baz elektrisite ek mayetis"}'::jsonb, '{"en":"Students build on earlier knowledge of circuits and explore the relationship between electricity and magnetism.","fr":"Les élèves approfondissent leurs connaissances sur les circuits et explorent la relation entre électricité et magnétisme.","mfe":"Bann elev devlop zot konesans lor sirkwi ek explor relasyon ant elektrisite ek mayetis."}'::jsonb),
('bf82f0df-3dc0-5610-a4c8-064818e96593', 'physics', 9, 1, '{"en":"Measurement and scientific inquiry","fr":"Mesure et démarche scientifique","mfe":"Mezir ek demars syantifik"}'::jsonb, '{"en":"Students revise and extend their understanding of physical quantities, SI units and measuring instruments, and learn how scientists collect and present reliable data.","fr":"Les élèves révisent et approfondissent leur compréhension des grandeurs physiques, des unités SI et des instruments de mesure, et apprennent comment les scientifiques collectent et présentent des données fiables.","mfe":"Bann elev revize ek dekouver pli lwen kantite fizik, inite SI ek lezenstriman mezir, ek aprann kouma syantis kolekte ek prezant done fiab."}'::jsonb),
('ffef2290-1d49-5242-817f-f1aa5bf6c10d', 'physics', 9, 2, '{"en":"Forces and motion","fr":"Forces et mouvement","mfe":"Fors ek mouvman"}'::jsonb, '{"en":"This unit introduces the effects of forces on motion, including speed, velocity, acceleration and Newton''s laws, using everyday Mauritian examples.","fr":"Cette unité présente les effets des forces sur le mouvement, incluant la vitesse, la vélocité, l''accélération et les lois de Newton, à travers des exemples mauriciens du quotidien.","mfe":"Sa linite-la introdir lefe fors lor mouvman, ki inklir vites, veloste, akselerasyon ek lalwa Newton, avek lexanp ki bann Morisyen konn dan lavi toulezour."}'::jsonb),
('ba890b8a-77cf-5b2b-8a74-b1595d4ad029', 'physics', 9, 3, '{"en":"Energy","fr":"L''énergie","mfe":"Lenerzi"}'::jsonb, '{"en":"Students explore the different forms of energy, how energy is transformed and conserved, and consider energy resources relevant to Mauritius.","fr":"Les élèves explorent les différentes formes d''énergie, comment elle est transformée et conservée, et étudient les ressources énergétiques pertinentes pour Maurice.","mfe":"Bann elev explor diferan form lenerzi, kouma lenerzi transforme ek konserve, ek examine resours lenerzi ki pertinan pou Moris."}'::jsonb),
('94b1b310-cb80-5dd0-9ef5-979ec46b19b7', 'physics', 9, 4, '{"en":"Pressure","fr":"La pression","mfe":"Presion"}'::jsonb, '{"en":"This unit covers pressure in solids, liquids and the atmosphere, and explains everyday applications such as hydraulics and barometers.","fr":"Cette unité couvre la pression dans les solides, les liquides et l''atmosphère, et explique des applications quotidiennes comme l''hydraulique et les baromètres.","mfe":"Sa linite-la kouver presion dan solid, likid ek latmosfer, ek explik bann aplikasion toulezour kouma idrolik ek barometer."}'::jsonb),
('a752c875-6b81-5c7e-89b1-0ad952ffc821', 'physics', 9, 5, '{"en":"Matter and the particle model","fr":"La matière et le modèle particulaire","mfe":"Matyer ek model partikil"}'::jsonb, '{"en":"Students study the particle model of matter to explain states of matter, changes of state, diffusion and density.","fr":"Les élèves étudient le modèle particulaire de la matière pour expliquer les états de la matière, les changements d''état, la diffusion et la densité.","mfe":"Bann elev etidye model partikil matyer pou explik eta matyer, sanzman eta, difizion ek densite."}'::jsonb),
('8ee920e3-2ff6-53b5-8a4b-af9bbec3f701', 'physics', 9, 6, '{"en":"Light and waves","fr":"La lumière et les ondes","mfe":"Limyer ek lezond"}'::jsonb, '{"en":"This unit introduces the behaviour of light through reflection and refraction, basic wave properties, and the electromagnetic spectrum.","fr":"Cette unité présente le comportement de la lumière à travers la réflexion et la réfraction, les propriétés de base des ondes, et le spectre électromagnétique.","mfe":"Sa linite-la introdir konportman limyer atraver reflexion ek refraksion, proprite baz lezond, ek spektr elektromagnetik."}'::jsonb),
('2ba74ba1-d33f-57da-9a91-4cf0c5dd32f3', 'physics', 9, 7, '{"en":"Electricity","fr":"L''électricité","mfe":"Lelektrisite"}'::jsonb, '{"en":"Students explore static and current electricity, building simple circuits and understanding the relationships between voltage, current and resistance.","fr":"Les élèves explorent l''électricité statique et le courant électrique, construisent des circuits simples et comprennent les relations entre tension, courant et résistance.","mfe":"Bann elev explor lelektrisite statik ek kouran, konstrir sirkwi sinp ek konpran relasion ant tansion, kouran ek rezistans."}'::jsonb),
('e96f917a-a98c-5578-b20c-d02716085f3e', 'physics', 9, 8, '{"en":"Magnetism","fr":"Le magnétisme","mfe":"Mayetism"}'::jsonb, '{"en":"This unit covers the properties of magnets, magnetic fields, and the basic principles of electromagnetism.","fr":"Cette unité couvre les propriétés des aimants, les champs magnétiques, et les principes de base de l''électromagnétisme.","mfe":"Sa linite-la kouver proprite leman, sanp mayetik, ek prinsip baz elektromayetism."}'::jsonb),
('14b76a5b-e3ca-5cc4-be92-9e801d9bf1ca', 'physics', 10, 1, '{"en":"Physical quantities and measurement","fr":"Grandeurs physiques et mesures","mfe":"Kantite fizik ek mezir"}'::jsonb, '{"en":"Introduces SI units, measurement instruments and techniques used to record length, time and other quantities accurately, forming the foundation for O Level physics.","fr":"Présente les unités SI, les instruments de mesure et les techniques permettant d''enregistrer avec précision la longueur, le temps et d''autres grandeurs, base de la physique du niveau O.","mfe":"Prezant bann inite SI, bann lenstriman ek teknik mezir pou anrezistre longer, letan ek lezot kantite avek presizyon, ki form baz fizik O Level."}'::jsonb),
('fb090afb-b690-5f2c-8f3e-e95ae2aa7292', 'physics', 10, 2, '{"en":"Kinematics of motion","fr":"Cinématique du mouvement","mfe":"Sinematik mouvman"}'::jsonb, '{"en":"Covers the description of motion including speed, velocity, acceleration and the use of graphs and equations to analyse movement.","fr":"Couvre la description du mouvement, y compris la vitesse, la vélocité, l''accélération et l''utilisation de graphiques et d''équations pour analyser le déplacement.","mfe":"Kouver deskripsyon mouvman ki inklir vites, velosite, akselerasyon ek servi grafik ek ekwasyon pou analiz mouvman."}'::jsonb),
('1f8196b3-85d6-59fa-9c9a-4ddb8cda58ca', 'physics', 10, 3, '{"en":"Dynamics and forces","fr":"Dynamique et forces","mfe":"Dinamik ek forse"}'::jsonb, '{"en":"Explores Newton''s laws of motion, the effects of forces on objects, friction and momentum in everyday and Mauritian contexts.","fr":"Explore les lois du mouvement de Newton, les effets des forces sur les objets, le frottement et la quantité de mouvement dans des contextes quotidiens et mauriciens.","mfe":"Explor lalwa mouvman Newton, lefe bann forse lor bann lobze, friksyon ek momantom dan kontex de tou le zour ek Moris."}'::jsonb),
('bf737047-8dd6-5b47-a423-0dc74e352932', 'physics', 10, 4, '{"en":"Mass, weight and density","fr":"Masse, poids et densité","mfe":"Mas, pwa ek densite"}'::jsonb, '{"en":"Clarifies the difference between mass and weight and teaches how to determine and apply density in practical situations.","fr":"Clarifie la différence entre masse et poids et enseigne comment déterminer et appliquer la densité dans des situations pratiques.","mfe":"Klarifye diferans ant mas ek pwa e montre kouma pou determinn ek aplik densite dan situasyon pratik."}'::jsonb),
('33a5d9f9-398a-5fb3-883e-0a416b43ba4d', 'physics', 10, 5, '{"en":"Turning effects and equilibrium","fr":"Effets de rotation et équilibre","mfe":"Lefe rotasyon ek balans"}'::jsonb, '{"en":"Examines moments, centre of gravity and the conditions needed for objects to remain balanced and stable.","fr":"Examine les moments, le centre de gravité et les conditions nécessaires pour que les objets restent équilibrés et stables.","mfe":"Examinn moman, sant gravite ek kondisyon neseser pou bann lobze reste balanse ek stab."}'::jsonb),
('466bf053-dbc3-5b15-816c-ee6c58ba74dd', 'physics', 10, 6, '{"en":"Energy, work and power","fr":"Énergie, travail et puissance","mfe":"Lenerzi, travay ek pwisans"}'::jsonb, '{"en":"Develops understanding of work done, energy transformations, conservation of energy, power and efficiency in mechanical systems.","fr":"Développe la compréhension du travail effectué, des transformations d''énergie, de la conservation de l''énergie, de la puissance et de l''efficacité dans les systèmes mécaniques.","mfe":"Devlop konpreansyon travay fer, transformasyon lenerzi, konservasyon lenerzi, pwisans ek efikasite dan bann sistem mekanik."}'::jsonb),
('4f68324e-825e-512b-a880-45bc8c0440fb', 'physics', 10, 7, '{"en":"Pressure in fluids and solids","fr":"Pression dans les fluides et solides","mfe":"Presyon dan fluid ek solid"}'::jsonb, '{"en":"Explains how pressure arises in solids and liquids, atmospheric pressure and its applications including hydraulic systems.","fr":"Explique comment la pression se produit dans les solides et les liquides, la pression atmosphérique et ses applications, y compris les systèmes hydrauliques.","mfe":"Explik kouma presyon aparet dan solid ek likid, presyon atmosferik ek so bann aplikasyon ki inklir sistem idrolik."}'::jsonb),
('3032ca09-41d3-5621-a6c4-c419ea31ba31', 'physics', 10, 8, '{"en":"Thermal physics fundamentals","fr":"Fondements de la physique thermique","mfe":"Bann fondaman fizik termik"}'::jsonb, '{"en":"Introduces the kinetic model of matter, thermal expansion, specific heat capacity, latent heat and temperature measurement.","fr":"Présente le modèle cinétique de la matière, la dilatation thermique, la chaleur spécifique, la chaleur latente et la mesure de la température.","mfe":"Prezant modelsinetik matyer, dilatasyon termik, kapasite termik spesifik, saler latant ek mezir temperatir."}'::jsonb),
('291e2ac9-919c-5fbc-a294-ff7f366e5302', 'physics', 11, 1, '{"en":"Thermal physics","fr":"Physique thermique","mfe":"Fizik term"}'::jsonb, '{"en":"Explore the kinetic model of matter and how heat affects materials, including expansion, specific heat capacity, latent heat and methods of heat transfer relevant to daily life in Mauritius.","fr":"Explorer le modèle cinétique de la matière et l''effet de la chaleur sur les matériaux, y compris la dilatation, la capacité thermique massique, la chaleur latente et les modes de transfert de chaleur utiles au quotidien à Maurice.","mfe":"Explor model sinetik lamater ek kouma lasaler afekte bann materyo, ki inklir dilatasion, kapasite term spesifik, saler latan ek fason transfer saler dan lavi toulezour Moris."}'::jsonb),
('b2835ed4-e8a2-5f51-bfd0-2b1ed0ce0e1f', 'physics', 11, 2, '{"en":"Waves and their properties","fr":"Les ondes et leurs propriétés","mfe":"Bann lond ek zot proprete"}'::jsonb, '{"en":"Study the general properties of waves, the difference between transverse and longitudinal waves, and the behaviour of waves at boundaries such as reflection, refraction and diffraction.","fr":"Étudier les propriétés générales des ondes, la différence entre ondes transversales et longitudinales, et leur comportement aux frontières comme la réflexion, la réfraction et la diffraction.","mfe":"Etidie bann proprete zeneral lond, diferans ant lond transversal ek longitidinal, ek konporteman lond kan zot zwenn bann fronte kouma refleksion, refraksion ek difraksion."}'::jsonb),
('a5606d26-f2dc-5dc0-a52f-d972d807fe1e', 'physics', 11, 3, '{"en":"Light","fr":"La lumière","mfe":"Lalimier"}'::jsonb, '{"en":"Investigate how light behaves when it reflects and refracts, including total internal reflection and image formation by lenses, with applications such as optical fibres and cameras.","fr":"Étudier le comportement de la lumière lors de la réflexion et de la réfraction, y compris la réflexion totale interne et la formation d''images par les lentilles, avec des applications comme la fibre optique et les appareils photo.","mfe":"Investig kouma lalimier konporte kan li refletir ek refrakte, ki inklir refleksion total intern ek formasion imaz par bann lantiy, avek aplikasion kouma fib optik ek kamera."}'::jsonb),
('aab83227-7ccc-5330-b7fa-fff07c5f47d0', 'physics', 11, 4, '{"en":"Sound","fr":"Le son","mfe":"Son"}'::jsonb, '{"en":"Examine the nature of sound as a wave, how its speed is measured, and how properties like pitch and loudness relate to frequency and amplitude, with everyday and cultural examples.","fr":"Examiner la nature du son en tant qu''onde, la mesure de sa vitesse, et le lien entre hauteur, intensité, fréquence et amplitude, avec des exemples quotidiens et culturels.","mfe":"Examine natir son kouma enn lond, kouma mezir so vites, ek kouma proprete kouma pitch ek fors lason relie ar frekans ek amplitid, avek bann lexanp toulezour ek kiltirel."}'::jsonb),
('35e0db75-152e-532f-98a9-4b49ea8e8317', 'physics', 11, 5, '{"en":"Electricity fundamentals","fr":"Fondements de l''électricité","mfe":"Baz lelektrisite"}'::jsonb, '{"en":"Build understanding of electric charge, current, potential difference and resistance, and apply these concepts to analyse simple series and parallel circuits.","fr":"Développer la compréhension de la charge électrique, du courant, de la tension et de la résistance, et appliquer ces notions à l''analyse de circuits simples en série et en parallèle.","mfe":"Devlop konpreansion lasarz elektrik, kouran, diferans potansiel ek rezistans, ek aplik sa bann konsep pou analiz bann sirkwi sinp an serie ek an paralel."}'::jsonb),
('5302ade7-f84f-5a7c-b206-265cd9b4115c', 'physics', 11, 6, '{"en":"Electrical energy and safety","fr":"Énergie électrique et sécurité","mfe":"Lenerzi elektrik ek sekirite"}'::jsonb, '{"en":"Understand how electrical energy is calculated and used safely in homes, and get an introduction to basic electronic components used in devices.","fr":"Comprendre comment l''énergie électrique est calculée et utilisée en toute sécurité à la maison, et découvrir les composants électroniques de base utilisés dans les appareils.","mfe":"Konpran kouma lenerzi elektrik kalkile ek servi an sekirite dan lakaz, ek gagn enn introdiksion bann konpozan elektronik debaz servi dan bann aparey."}'::jsonb),
('a67b04ce-4755-5956-aed8-34524a7e0f3f', 'physics', 11, 7, '{"en":"Magnetism and electromagnetism","fr":"Magnétisme et électromagnétisme","mfe":"Manyetism ek elektromanyetism"}'::jsonb, '{"en":"Explore magnetic fields, how electric currents create magnetism, and how electromagnetic induction underlies devices such as generators and transformers.","fr":"Explorer les champs magnétiques, la manière dont les courants électriques créent du magnétisme, et le principe de l''induction électromagnétique dans les générateurs et transformateurs.","mfe":"Explor bann sam manyetik, kouma kouran elektrik kree manyetism, ek kouma indiksion elektromanyetik form baz bann zeneratir ek transformater."}'::jsonb),
('35574bd7-15f7-57f7-82ba-15675a9ec463', 'physics', 11, 8, '{"en":"Atomic and nuclear physics","fr":"Physique atomique et nucléaire","mfe":"Fizik atomik ek nikleer"}'::jsonb, '{"en":"Discover the structure of the atom, the nature of radioactivity, and the uses and hazards of nuclear radiation in medicine, industry and energy production.","fr":"Découvrir la structure de l''atome, la nature de la radioactivité, ainsi que les usages et dangers des rayonnements nucléaires en médecine, dans l''industrie et la production d''énergie.","mfe":"Dekouver striktir latom, natir radioaktivite, ek servis ek danze radiasion nikleer dan medsinn, indistri ek prodiksion lenerzi."}'::jsonb),
('fb6e5945-ff17-5e76-9c8e-ae6e6109fa64', 'physics', 12, 1, '{"en":"Physical quantities and measurement","fr":"Grandeurs physiques et mesures","mfe":"Kantite fizik ek mezir"}'::jsonb, '{"en":"Introduces SI units, measurement techniques, uncertainties, and the distinction between scalar and vector quantities used throughout AS Physics.","fr":"Introduit les unites du SI, les techniques de mesure, les incertitudes et la distinction entre grandeurs scalaires et vectorielles utilisees tout au long du programme AS de physique.","mfe":"Introdir bann linite SI, bann teknik mezir, ensertitid, ek diferans ant kantite skalaire ek vekteris ki servi partou dan program AS Physics."}'::jsonb),
('ea69461d-2d3e-57fc-9fa1-1bfb38b469c2', 'physics', 12, 2, '{"en":"Kinematics of motion","fr":"Cinematique du mouvement","mfe":"Sinematik mouvman"}'::jsonb, '{"en":"Explores how objects move in a straight line and in projectile paths, using equations and graphs to describe motion.","fr":"Explore comment les objets se deplacent en ligne droite et selon une trajectoire de projectile, en utilisant equations et graphiques pour decrire le mouvement.","mfe":"Explor kouma bann lobze deplase dan enn lign drwat ek dan enn trazektwar prozektil, servi ekwasyon ek grafik pou dekrir mouvman."}'::jsonb),
('1375cc88-5a58-5a3a-b4d0-c51896c022fa', 'physics', 12, 3, '{"en":"Dynamics and forces","fr":"Dynamique et forces","mfe":"Dinamik ek fors"}'::jsonb, '{"en":"Covers Newton''s laws of motion, momentum conservation and collisions, building the foundation for understanding forces.","fr":"Couvre les lois du mouvement de Newton, la conservation de la quantite de mouvement et les collisions, base essentielle pour comprendre les forces.","mfe":"Kouver bann lwa mouvman Newton, konservasyon moman ek kolizyon, ki form baz pou konpran fors."}'::jsonb),
('31399989-0b75-5a57-9712-2d11212b95d6', 'physics', 12, 4, '{"en":"Forces, density and pressure","fr":"Forces, densite et pression","mfe":"Fors, densite ek presyon"}'::jsonb, '{"en":"Examines equilibrium of forces, turning effects, and how density and pressure behave in fluids.","fr":"Examine l''equilibre des forces, les effets de rotation, et comment la densite et la pression se comportent dans les fluides.","mfe":"Examinn ekilib fors, bann lefe rotasyon, ek kouma densite ek presyon aji dan bann likid ek gaz."}'::jsonb),
('5335a94e-2c83-5895-8f37-2f525e03e917', 'physics', 12, 5, '{"en":"Work, energy and power","fr":"Travail, energie et puissance","mfe":"Travay, lenerzi ek pwisans"}'::jsonb, '{"en":"Develops the concepts of work, kinetic and potential energy, energy conservation, and power in mechanical systems.","fr":"Developpe les concepts de travail, d''energie cinetique et potentielle, de conservation de l''energie et de puissance dans les systemes mecaniques.","mfe":"Devlop bann konsep travay, lenerzi sinetik ek potansyel, konservasyon lenerzi, ek pwisans dan bann sistem mekanik."}'::jsonb),
('38b299de-27c6-5f91-bb1a-d2d1337593f2', 'physics', 12, 6, '{"en":"Deformation of solids","fr":"Deformation des solides","mfe":"Defomasyon solid"}'::jsonb, '{"en":"Investigates how materials stretch and deform under load, including Hooke''s law, stress, strain and the Young modulus.","fr":"Etudie comment les materiaux s''etirent et se deforment sous charge, incluant la loi de Hooke, la contrainte, la deformation et le module de Young.","mfe":"Etidye kouma bann materyo alonze ek defome anba enn sarz, ki inkli lwa Hooke, stress, strain ek modil Young."}'::jsonb),
('64de02ae-b45d-514c-9bd3-d906e53b87d5', 'physics', 12, 7, '{"en":"Waves and superposition","fr":"Ondes et superposition","mfe":"Bann ond ek siperpozisyon"}'::jsonb, '{"en":"Covers wave properties, types of waves, and phenomena arising from the superposition of waves such as interference and stationary waves.","fr":"Couvre les proprietes des ondes, les types d''ondes, et les phenomenes resultant de la superposition des ondes comme l''interference et les ondes stationnaires.","mfe":"Kouver proprite ond, tip ond, ek fenomenn ki sorti kan ond siperpoze kouma lenterferans ek ond stasyoner."}'::jsonb),
('3b4d6b57-fb7f-51db-b186-0dbcf9af31c0', 'physics', 12, 8, '{"en":"Electricity and DC circuits","fr":"Electricite et circuits en courant continu","mfe":"Elektrisite ek sirkwi kouran kontini"}'::jsonb, '{"en":"Introduces electric current, potential difference, resistance and the analysis of direct current circuits using Kirchhoff''s laws.","fr":"Introduit le courant electrique, la difference de potentiel, la resistance et l''analyse des circuits a courant continu a l''aide des lois de Kirchhoff.","mfe":"Introdir kouran elektrik, diferans potansyel, rezistans ek analiz sirkwi kouran kontini servi lwa Kirchhoff."}'::jsonb),
('ba7383af-be54-55fb-a7da-f6aa32bfb0a5', 'physics', 13, 1, '{"en":"Circular motion and gravitational fields","fr":"Mouvement circulaire et champs gravitationnels","mfe":"Mouvman sirkiler ek shan gravitasyonel"}'::jsonb, '{"en":"Explore motion in circles and the forces that keep planets and satellites in orbit, extending gravitation to fields and potential.","fr":"Explorer le mouvement circulaire et les forces maintenant les planètes et satellites en orbite, en étendant la gravitation aux champs et au potentiel.","mfe":"Explor mouvman sirkiler ek bann fors ki gard bann planet ek satelit an orbit, agrandi gravitasyon ver shan ek potansyel."}'::jsonb),
('05ca6583-1237-546e-975b-1be7f530e545', 'physics', 13, 2, '{"en":"Oscillations","fr":"Oscillations","mfe":"Osilasyon"}'::jsonb, '{"en":"Study simple harmonic motion, energy exchange in oscillators, and the effects of damping and resonance in real systems.","fr":"Étudier le mouvement harmonique simple, l''échange d''énergie dans les oscillateurs, ainsi que les effets de l''amortissement et de la résonance.","mfe":"Etidye mouvman armonik senp, lesanz lenerzi dan bann osilater, ek bann lefe amortisman ek rezonans dan sistem reel."}'::jsonb),
('537fe069-e3ff-5c4e-8c45-40c5440ad3a4', 'physics', 13, 3, '{"en":"Thermal physics and ideal gases","fr":"Physique thermique et gaz parfaits","mfe":"Fizik termik ek gaz parfe"}'::jsonb, '{"en":"Understand temperature, internal energy, and the behaviour of ideal gases using kinetic theory and the first law of thermodynamics.","fr":"Comprendre la température, l''énergie interne et le comportement des gaz parfaits à l''aide de la théorie cinétique et du premier principe de la thermodynamique.","mfe":"Konpran temperatir, lenerzi intern ek konportman gaz parfe atraver teori sinetik ek premie lwa termodinamik."}'::jsonb),
('74d34b84-6a31-5c6f-a700-e5e6dcf228b3', 'physics', 13, 4, '{"en":"Electric fields and capacitance","fr":"Champs électriques et capacité","mfe":"Shan elektrik ek kapasite"}'::jsonb, '{"en":"Investigate electric fields around charges, potential, and how capacitors store and release electrical energy.","fr":"Étudier les champs électriques autour des charges, le potentiel, et comment les condensateurs stockent et libèrent l''énergie électrique.","mfe":"Investig shan elektrik otour sarz, potansyel, ek kouma kapasiter stok ek lib lenerzi elektrik."}'::jsonb),
('8edf56cc-b45e-5a2e-9f6e-3c19425a619a', 'physics', 13, 5, '{"en":"Magnetic fields and electromagnetic induction","fr":"Champs magnétiques et induction électromagnétique","mfe":"Shan manyetik ek induksyon elektromanyetik"}'::jsonb, '{"en":"Explore magnetic forces on currents and charges, and how changing fields generate electromotive force.","fr":"Explorer les forces magnétiques sur les courants et charges, et comment les champs variables génèrent une force électromotrice.","mfe":"Explor bann fors manyetik lor kouran ek sarz, ek kouma shan sanzman genere fors elektromotris."}'::jsonb),
('7f6d3a7c-d58f-5530-a0bb-1063acb819fe', 'physics', 13, 6, '{"en":"Alternating currents and quantum physics","fr":"Courants alternatifs et physique quantique","mfe":"Kouran alternatif ek fizik kantik"}'::jsonb, '{"en":"Analyse alternating current circuits and discover the quantum nature of light and matter.","fr":"Analyser les circuits à courant alternatif et découvrir la nature quantique de la lumière et de la matière.","mfe":"Analiz sirkwi kouran alternatif ek dekouver natir kantik lalimyer ek matyer."}'::jsonb),
('bcd90840-07b3-5c27-912c-64cf24a1205f', 'physics', 13, 7, '{"en":"Nuclear physics and astrophysics","fr":"Physique nucléaire et astrophysique","mfe":"Fizik nikleer ek astrofizik"}'::jsonb, '{"en":"Examine the structure of the nucleus, radioactive decay, and apply physics to stars and the wider universe.","fr":"Examiner la structure du noyau, la désintégration radioactive, et appliquer la physique aux étoiles et à l''univers.","mfe":"Egzamin striktir nwayo, dezintegrasyon radioaktif, ek aplik fizik lor zetwal ek liniver."}'::jsonb),
('4434ee7c-55b2-5aba-aa18-98f9d35f6027', 'sexuality-education', 7, 1, '{"en":"Growing and changing","fr":"Grandir et changer","mfe":"Grandi ek sanze"}'::jsonb, '{"en":"An introduction to puberty and the physical and emotional changes that happen as young people grow.","fr":"Une introduction à la puberté et aux changements physiques et émotionnels qui surviennent en grandissant.","mfe":"Enn lintrodiksion lor pibert ek bann sanzman fizik ek emosionel ki arive kan enn zenn grandi."}'::jsonb),
('37bbfab1-175d-5c0c-8cdc-d95d13a75ac0', 'sexuality-education', 7, 2, '{"en":"Understanding my body","fr":"Comprendre mon corps","mfe":"Konpran mo lekor"}'::jsonb, '{"en":"Learning correct names and functions of body parts, including the reproductive system, and building positive body image.","fr":"Apprendre les noms et fonctions corrects des parties du corps, y compris le système reproducteur, et développer une image corporelle positive.","mfe":"Aprann bon nom ek fonksion bann parti lekor, inklir sistem reproduktif, ek devlop enn bon limaz lor lekor."}'::jsonb),
('7c2b0dfb-2cba-57a4-a205-11afc6f9dd79', 'sexuality-education', 7, 3, '{"en":"Emotions and friendships","fr":"Émotions et amitiés","mfe":"Emosion ek lamitie"}'::jsonb, '{"en":"Exploring emotions, building healthy friendships and understanding family relationships during early adolescence.","fr":"Explorer les émotions, développer des amitiés saines et comprendre les relations familiales au début de l''adolescence.","mfe":"Explor emosion, devlop bon lamitie ek konpran relasion familial pandan koumansman ladolesans."}'::jsonb),
('4b561025-b8b7-5cce-ad0f-9bce3a1534dd', 'sexuality-education', 7, 4, '{"en":"Respect and consent","fr":"Respect et consentement","mfe":"Respe ek konsantman"}'::jsonb, '{"en":"Understanding personal boundaries, respect for others and the meaning of consent in everyday situations.","fr":"Comprendre les limites personnelles, le respect d''autrui et la signification du consentement dans la vie quotidienne.","mfe":"Konpran limit personel, respe pou lezot ek sinifikasion konsantman dan lavi toulezour."}'::jsonb),
('473c6198-3dee-5896-9f48-61c1ca07fa72', 'sexuality-education', 7, 5, '{"en":"Staying safe from harm","fr":"Se protéger contre les dangers","mfe":"Res anseksirite kont danze"}'::jsonb, '{"en":"Learning to recognise unsafe situations, understand safe and unsafe touch, and know how to seek help.","fr":"Apprendre à reconnaître les situations dangereuses, comprendre les contacts sûrs et non sûrs, et savoir comment demander de l''aide.","mfe":"Aprann rekonet sitiasion danzere, konpran tousman sekiritaire ek non sekiritaire, ek kone kouma demann led."}'::jsonb),
('cc1f0f31-2905-56c3-9760-14c249633f93', 'sexuality-education', 7, 6, '{"en":"Staying safe online","fr":"Rester en sécurité en ligne","mfe":"Res anseksirite lor internet"}'::jsonb, '{"en":"Building awareness of online risks, protecting personal information and responding to cyberbullying.","fr":"Développer la sensibilisation aux risques en ligne, protéger les informations personnelles et réagir à la cyberintimidation.","mfe":"Devlop konesans lor risk lor internet, protez linformasion personel ek reazir kont cyberintimidation."}'::jsonb),
('6060917a-b312-5d24-81b6-605fcb9a4dfa', 'sexuality-education', 7, 7, '{"en":"Health and well-being choices","fr":"Choix pour la santé et le bien-être","mfe":"Swa pou lasante ek byennet"}'::jsonb, '{"en":"Understanding how nutrition, sleep and responsible decision-making support health during adolescence.","fr":"Comprendre comment la nutrition, le sommeil et une prise de décision responsable soutiennent la santé à l''adolescence.","mfe":"Konpran kouma nitrision, dormi ek pran desizion responsab soutenir lasante pandan ladolesans."}'::jsonb),
('197f88a9-3fb8-5a01-ab23-ee1bb62a22b9', 'sexuality-education', 8, 1, '{"en":"Understanding puberty and body changes","fr":"Comprendre la puberté et les changements du corps","mfe":"Konpran pibète ek chanzman lekor"}'::jsonb, '{"en":"Students explore the physical and emotional changes that occur during puberty and learn to manage these changes with confidence and good hygiene practices.","fr":"Les élèves explorent les changements physiques et émotionnels survenant pendant la puberté et apprennent à les gérer avec confiance et une bonne hygiène.","mfe":"Bann elev pou explor bann chanzman fizik ek emosionel ki arive pandan pibète ek aprann gere sa avek konfians ek bon ladan pou ligyenn."}'::jsonb),
('5bad3978-b481-5810-be14-83dca36ddc71', 'sexuality-education', 8, 2, '{"en":"Building healthy relationships","fr":"Construire des relations saines","mfe":"Konstrir bann relasion an bon sante"}'::jsonb, '{"en":"Students learn about different types of relationships, effective communication and how to handle peer pressure while respecting others.","fr":"Les élèves apprennent les différents types de relations, une communication efficace et comment gérer la pression des pairs tout en respectant les autres.","mfe":"Bann elev aprann diferan tip relasion, komenikasion efikas ek kouma zere presion kamarad tou an respekte lezot."}'::jsonb),
('469e80de-267d-5507-ba97-edde48a8fdd8', 'sexuality-education', 8, 3, '{"en":"Consent and personal boundaries","fr":"Le consentement et les limites personnelles","mfe":"Konsantman ek limit personel"}'::jsonb, '{"en":"Students learn what consent means, how to set and respect personal boundaries, and how to respond assertively in uncomfortable situations.","fr":"Les élèves apprennent ce que signifie le consentement, comment fixer et respecter des limites personnelles, et comment réagir avec assurance dans des situations inconfortables.","mfe":"Bann elev aprann ki sa vedir konsantman, kouma etabli ek respekte limit personel, ek kouma reazir avek fermte dan sitiasion malalez."}'::jsonb),
('c568671a-f571-550f-83a2-f58f036cdfc8', 'sexuality-education', 8, 4, '{"en":"Respect, equality and diversity","fr":"Respect, égalité et diversité","mfe":"Respe, legalite ek diversite"}'::jsonb, '{"en":"Students examine gender stereotypes, discrimination and the value of diversity, building respect for all people in Mauritius''s multicultural society.","fr":"Les élèves examinent les stéréotypes de genre, la discrimination et la valeur de la diversité, renforçant le respect envers tous dans la société multiculturelle mauricienne.","mfe":"Bann elev examine bann stereotip zann, diskriminasion ek valer diversite, pou ranforsi respe anver tou dimoun dan sosiete miltikilturel Moris."}'::jsonb),
('33e01dfb-acdd-56b6-8471-1ad57f0e69e5', 'sexuality-education', 8, 5, '{"en":"Health and safety awareness","fr":"Sensibilisation à la santé et à la sécurité","mfe":"Sansibilizasion lasante ek sekirite"}'::jsonb, '{"en":"Students learn basic facts about reproductive health, risks of substance use, and how to recognise and respond to situations of abuse.","fr":"Les élèves apprennent des notions de base sur la santé reproductive, les risques liés à la consommation de substances, et comment reconnaître et réagir face à des situations d''abus.","mfe":"Bann elev aprann bann konesans debaz lor lasante repwodiktif, risk konsomasion sibstans, ek kouma rekonet ek reazir fas a sitiasion abi."}'::jsonb),
('37be609a-e21e-5eed-8e2e-95bd3c06f8ed', 'sexuality-education', 8, 6, '{"en":"Staying safe online","fr":"Rester en sécurité en ligne","mfe":"Res an sekirite anlinn"}'::jsonb, '{"en":"Students explore digital privacy, online risks and safe social media practices to protect themselves and others in the online world.","fr":"Les élèves explorent la confidentialité numérique, les risques en ligne et les bonnes pratiques sur les réseaux sociaux pour se protéger et protéger les autres.","mfe":"Bann elev explor konfidansialite dizital, risk anlinn ek bon pratik lor rezo sosial pou protez zot ek lezot dan lemond anlinn."}'::jsonb),
('7cfd277d-dbdf-572f-8350-cdacebf9406a', 'sexuality-education', 8, 7, '{"en":"Family, values and decision-making","fr":"Famille, valeurs et prise de décision","mfe":"Fami, valer ek pran desizion"}'::jsonb, '{"en":"Students reflect on family roles, personal values and decision-making skills to make responsible choices and set positive life goals.","fr":"Les élèves réfléchissent aux rôles familiaux, aux valeurs personnelles et aux compétences de prise de décision pour faire des choix responsables et se fixer des objectifs positifs.","mfe":"Bann elev reflesi lor rol fami, valer personel ek konpetans pran desizion pou fer bon swa ek fixe bann lobzektif pozitiv dan lavi."}'::jsonb),
('e7f0facb-c6c4-50ec-8ef6-3cafbee26669', 'sexuality-education', 9, 1, '{"en":"Growth and development revisited","fr":"Croissance et développement revisités","mfe":"Kwasans ek devlopman revizite"}'::jsonb, '{"en":"A review and deepening of puberty changes, body image, and self-esteem as students move into adolescence.","fr":"Une révision et un approfondissement des changements de la puberté, de l''image corporelle et de l''estime de soi à l''adolescence.","mfe":"Enn revizyon ek apronfondisman lor sanzman pandan lapibersete, limaz lekor ek lestim swa pandan ladolesans."}'::jsonb),
('d306b374-bdf7-5bc3-9113-22f047b22f6f', 'sexuality-education', 9, 2, '{"en":"Understanding relationships","fr":"Comprendre les relations","mfe":"Konpran relasyon"}'::jsonb, '{"en":"Exploring different types of relationships, healthy versus unhealthy dynamics, and communication skills.","fr":"Exploration des différents types de relations, des dynamiques saines et malsaines, et des compétences en communication.","mfe":"Explor diferan tip relasyon, dinamik ki sen ek ki pa sen, ek konpetans kominikasyon."}'::jsonb),
('a86ba1a6-dcfe-5451-9b63-23276411a4b3', 'sexuality-education', 9, 3, '{"en":"Consent and personal boundaries","fr":"Consentement et limites personnelles","mfe":"Konsantman ek limit personel"}'::jsonb, '{"en":"Understanding consent, bodily autonomy, and how to set and respect personal boundaries.","fr":"Comprendre le consentement, l''autonomie corporelle et comment établir et respecter les limites personnelles.","mfe":"Konpran konsantman, otonomi lekor ek kouman etabli ek respekte limit personel."}'::jsonb),
('86256785-43aa-59fd-b245-82c2cf7e6ed0', 'sexuality-education', 9, 4, '{"en":"Gender roles and respect","fr":"Rôles de genre et respect","mfe":"Rol zann ek respe"}'::jsonb, '{"en":"Examining gender stereotypes, equality, and respectful behaviour between all genders in Mauritian society.","fr":"Examiner les stéréotypes de genre, l''égalité et le comportement respectueux entre tous les genres dans la société mauricienne.","mfe":"Egzamin stereotip zann, egalite ek konportman respektye ant tou zann dan sosyete morisyen."}'::jsonb),
('23ce7159-8192-58b2-a751-703aef65a981', 'sexuality-education', 9, 5, '{"en":"Health, hygiene and safety","fr":"Santé, hygiène et sécurité","mfe":"Lasante, ijyenn ek sekirite"}'::jsonb, '{"en":"Practical guidance on personal hygiene, reproductive health basics, and staying safe from risks.","fr":"Conseils pratiques sur l''hygiène personnelle, les bases de la santé reproductive et la protection contre les risques.","mfe":"Gid pratik lor ijyenn personel, baz lasante repwodiktiv ek res an sekirite kont risk."}'::jsonb),
('6701c021-ac8d-578d-91f8-88aceae0a4e6', 'sexuality-education', 9, 6, '{"en":"Staying safe online","fr":"Rester en sécurité en ligne","mfe":"Res an sekirite lor internet"}'::jsonb, '{"en":"Building skills to navigate social media, recognise online risks, and protect personal information.","fr":"Développer des compétences pour naviguer sur les réseaux sociaux, reconnaître les risques en ligne et protéger les informations personnelles.","mfe":"Devlop konpetans pou navige lor rezo sosyal, rekonet risk anlinn ek protez linformasyon personel."}'::jsonb),
('b77b34d8-cc8a-5fde-a99c-50f055fb1936', 'sexuality-education', 9, 7, '{"en":"Making informed and responsible choices","fr":"Faire des choix informés et responsables","mfe":"Fer swa enform ek responsab"}'::jsonb, '{"en":"Applying knowledge of relationships, consent and safety to make responsible decisions as a young person.","fr":"Appliquer les connaissances sur les relations, le consentement et la sécurité pour faire des choix responsables en tant que jeune.","mfe":"Aplik konesans lor relasyon, konsantman ek sekirite pou fer desizyon responsab kouma enn zenn."}'::jsonb),
('628bc3d9-1cea-5462-9745-585d3ab77570', 'sexuality-education', 10, 1, '{"en":"Puberty and body image","fr":"Puberté et image corporelle","mfe":"Piberte ek limaz likor"}'::jsonb, '{"en":"Students revisit the physical and emotional changes of puberty and explore how to build a positive body image and healthy self-care habits.","fr":"Les élèves revoient les changements physiques et émotionnels de la puberté et explorent comment développer une image corporelle positive et de bonnes habitudes d''hygiène.","mfe":"Bann elev revwar sanzman fizik ek emosyonel pandan piberte ek dekouver kouma pou devlop enn bon limaz likor ek bon labitid liygyenn."}'::jsonb),
('479eab7c-4313-565a-9227-a5daccb6aa14', 'sexuality-education', 10, 2, '{"en":"Healthy relationships and family values","fr":"Relations saines et valeurs familiales","mfe":"Relasyon ki bon ek valer fami"}'::jsonb, '{"en":"This unit examines different types of relationships, effective communication, and the role of family values in building respectful connections.","fr":"Cette unité examine différents types de relations, la communication efficace et le rôle des valeurs familiales dans la construction de liens respectueux.","mfe":"Sa linite-la examinn diferan tip relasyon, kominikasyon efikas, ek rol valer fami pou konstrir bann relasyon respekte."}'::jsonb),
('d082293a-6651-52a7-a98e-14efd78e7ddc', 'sexuality-education', 10, 3, '{"en":"Consent, respect and boundaries","fr":"Consentement, respect et limites","mfe":"Konsantman, respe ek limit personel"}'::jsonb, '{"en":"Students learn about consent, personal boundaries, and how to recognise and respond to disrespectful or abusive behaviour.","fr":"Les élèves apprennent le consentement, les limites personnelles, et comment reconnaître et réagir face à des comportements irrespectueux ou abusifs.","mfe":"Bann elev aprann konsantman, limit personel, ek kouma pou rekonet ek reazir devan bann konportman ki manke respe ouswa abizif."}'::jsonb),
('218f5d2c-14da-5901-8ddc-210699dca5dc', 'sexuality-education', 10, 4, '{"en":"Gender roles and equality","fr":"Rôles de genre et égalité","mfe":"Rol zanfan garson-fi ek egalite"}'::jsonb, '{"en":"This unit explores gender stereotypes, discrimination, and the importance of promoting equality in Mauritian society.","fr":"Cette unité explore les stéréotypes de genre, la discrimination et l''importance de promouvoir l''égalité dans la société mauricienne.","mfe":"Sa linite-la explor bann stereotip zanfan garson-fi, diskriminasyon, ek linportans promouvwar egalite dan sosyete Morisien."}'::jsonb),
('c30a4cbc-adb1-5932-8f27-d2c61c91bb54', 'sexuality-education', 10, 5, '{"en":"Reproductive health and human reproduction","fr":"Santé reproductive et reproduction humaine","mfe":"Lasante reprodiksyon ek reprodiksyon imen"}'::jsonb, '{"en":"Students study the reproductive systems, menstrual health, and the biological process of human reproduction, correcting common myths.","fr":"Les élèves étudient les systèmes reproducteurs, la santé menstruelle et le processus biologique de la reproduction humaine, en corrigeant les idées fausses courantes.","mfe":"Bann elev etidye sistem reprodiksyon, lasante mansiyel, ek prosesis biolozik reprodiksyon imen, koriz bann fos lide komen."}'::jsonb),
('53b0eb94-b063-5894-9727-6b057b54abeb', 'sexuality-education', 10, 6, '{"en":"Contraception and responsible choices","fr":"Contraception et choix responsables","mfe":"Kontrasepsyon ek swa responsab"}'::jsonb, '{"en":"This unit introduces contraception methods, decision-making skills, and the importance of delaying sexual activity responsibly.","fr":"Cette unité présente les méthodes de contraception, les compétences de prise de décision et l''importance de retarder l''activité sexuelle de manière responsable.","mfe":"Sa linite-la introdir bann metod kontrasepsyon, konpetans pran desizyon, ek linportans pou retard aktivite sexyel dan enn fason responsab."}'::jsonb),
('bf0a954e-aa0e-5cec-a04b-33b9796c6642', 'sexuality-education', 10, 7, '{"en":"STIs, HIV and AIDS awareness","fr":"Sensibilisation aux IST, au VIH et au SIDA","mfe":"Sansibilizasyon lor MST, VIH ek SIDA"}'::jsonb, '{"en":"Students learn about sexually transmitted infections, HIV/AIDS transmission, prevention, and available testing and support services.","fr":"Les élèves apprennent les infections sexuellement transmissibles, la transmission du VIH/SIDA, la prévention et les services de dépistage et de soutien disponibles.","mfe":"Bann elev aprann lor bann infeksyon transmet par sex, transmisyon VIH/SIDA, prevansyon, ek servis test ek soutyen ki disponib."}'::jsonb),
('e61d4418-2205-53ad-8901-9dbe808937ab', 'sexuality-education', 10, 8, '{"en":"Online safety and digital citizenship","fr":"Sécurité en ligne et citoyenneté numérique","mfe":"Sekirite anlign ek sitwayennte dizital"}'::jsonb, '{"en":"This unit addresses online risks, grooming, sexting, cyberbullying, and how to seek help and report unsafe situations online.","fr":"Cette unité traite des risques en ligne, du grooming, du sexting, de la cyberintimidation, et comment demander de l''aide et signaler des situations dangereuses en ligne.","mfe":"Sa linite-la adres bann risk anlign, groming, sexting, cyberintimidasyon, ek kouma pou demann led ek rapor bann sitiasyon danzere anlign."}'::jsonb),
('d14dd493-196c-589f-8a3f-90298d7835f7', 'sexuality-education', 11, 1, '{"en":"Growth, identity and self-esteem","fr":"Croissance, identité et estime de soi","mfe":"Kwasans, ledantite ek lestim pou soi"}'::jsonb, '{"en":"Explore physical and emotional changes in late adolescence, and how identity, values and self-esteem develop during this stage of life.","fr":"Explorer les changements physiques et émotionnels de la fin de l''adolescence, ainsi que le développement de l''identité, des valeurs et de l''estime de soi.","mfe":"Explor bann sanzman fizik ek emosyonel dan lafin adolesans, ek kouma ledantite, valer ek lestim pou soi devlope dan sa etap lavi la."}'::jsonb),
('cd5a3d4b-da0e-57f5-94da-d49bcab02506', 'sexuality-education', 11, 2, '{"en":"Healthy relationships and communication","fr":"Relations saines et communication","mfe":"Relasyon an bonn sante ek kominikasyon"}'::jsonb, '{"en":"Examine the qualities of healthy relationships and develop communication skills to build respect, trust and support in personal and family relationships.","fr":"Examiner les qualités des relations saines et développer des compétences en communication pour instaurer le respect, la confiance et le soutien.","mfe":"Egzamin bann kalite relasyon an bonn sante ek devlop konpetans kominikasyon pou ranforsi respe, konfyans ek sipor."}'::jsonb),
('c46f020f-4126-5357-82b1-3abeaca88978', 'sexuality-education', 11, 3, '{"en":"Consent, rights and respect","fr":"Consentement, droits et respect","mfe":"Konsantman, drwa ek respe"}'::jsonb, '{"en":"Understand the meaning of consent, personal rights and mutual respect, and learn how to respond appropriately when boundaries are crossed.","fr":"Comprendre la signification du consentement, des droits personnels et du respect mutuel, et apprendre à réagir face aux limites franchies.","mfe":"Konpran sinifikasyon konsantman, drwa personel ek respe mityel, ek aprann kouma reponn kan bann limit finn depase."}'::jsonb),
('132ec016-2976-5625-a8d8-326c9b05a9d8', 'sexuality-education', 11, 4, '{"en":"Gender, equality and social norms","fr":"Genre, égalité et normes sociales","mfe":"Zanr, egalite ek norm sosyal"}'::jsonb, '{"en":"Analyse gender roles, stereotypes and gender-based violence, and explore ways to promote equality and respect in Mauritian society.","fr":"Analyser les rôles de genre, les stéréotypes et la violence basée sur le genre, et explorer des moyens de promouvoir l''égalité.","mfe":"Analiz rol zanr, stereotip ek vyolans baze lor zanr, ek explor bann fason pou promouvwar egalite dan sosyete Moris."}'::jsonb),
('97bb5f0e-b8f0-5436-914c-15301c9f7c98', 'sexuality-education', 11, 5, '{"en":"Sexual health and safety","fr":"Santé et sécurité sexuelles","mfe":"Lasante ek sekirite seksyel"}'::jsonb, '{"en":"Learn about reproductive health, sexually transmitted infections, HIV prevention, and how to access confidential health services.","fr":"Apprendre la santé reproductive, les infections sexuellement transmissibles, la prévention du VIH et l''accès aux services de santé confidentiels.","mfe":"Aprann lor lasante reproduktif, enfeksyon transmet par sex, prevansyon VIH ek kouma gagn aksed a servis lasante konfidansyel."}'::jsonb),
('bd4ac618-0d99-5ad0-a882-c2ad562f8527', 'sexuality-education', 11, 6, '{"en":"Pregnancy, contraception and family planning","fr":"Grossesse, contraception et planification familiale","mfe":"Gwoses, kontrasepsyon ek planifikasyon familyal"}'::jsonb, '{"en":"Understand contraception methods, the realities of teenage pregnancy, and the importance of planning for future family life.","fr":"Comprendre les méthodes de contraception, les réalités de la grossesse chez les adolescentes et l''importance de la planification familiale.","mfe":"Konpran metod kontrasepsyon, realite gwoses adolesant ek lenportans planifikasyon pou lavenir familyal."}'::jsonb),
('704b5e05-7c06-51df-b007-e463396a5086', 'sexuality-education', 11, 7, '{"en":"Online safety and digital relationships","fr":"Sécurité en ligne et relations numériques","mfe":"Sekirite anlinn ek relasyon dizital"}'::jsonb, '{"en":"Explore the risks of online relationships, digital reputation, sexting and grooming, and learn strategies to stay safe online.","fr":"Explorer les risques des relations en ligne, la réputation numérique, le sexting et le grooming, et apprendre à rester en sécurité en ligne.","mfe":"Explor risk relasyon anlinn, reputasyon dizital, sexting ek grooming, ek aprann strateji pou reste an sekirite anlinn."}'::jsonb),
('d191ba7c-6522-5fbb-a8fc-c2dbf46ce34c', 'sexuality-education', 11, 8, '{"en":"Preparing for adulthood","fr":"Se préparer à l''âge adulte","mfe":"Prepar pou vinn adilt"}'::jsonb, '{"en":"Reflect on personal values, decision-making skills and available support services to make informed choices about relationships, health and the future.","fr":"Réfléchir sur les valeurs personnelles, les compétences de décision et les services disponibles pour faire des choix éclairés.","mfe":"Reflekt lor valer personel, konpetans pran desizyon ek servis disponib pou fer swa eklere lor relasyon, lasante ek lavenir."}'::jsonb),
('06b20498-8745-5f88-9e2c-f5fcb99b8ee8', 'social-modern-studies', 7, 1, '{"en":"Understanding ourselves and society","fr":"Se comprendre soi-même et la société","mfe":"Konpran nou-mem ek lasosiete"}'::jsonb, '{"en":"Students explore personal identity, family life and how individuals learn values and roles within Mauritian society.","fr":"Les élèves explorent l''identité personnelle, la vie familiale et la manière dont les individus apprennent des valeurs et des rôles au sein de la société mauricienne.","mfe":"Bann elev explor zot lidentite personel, lavi familial ek kouma bann individi aprann valer ek rol dan lasosiete morisien."}'::jsonb),
('e3bfb5c5-2889-5d86-bf37-ebfd22dca13f', 'social-modern-studies', 7, 2, '{"en":"Mauritius: land and people","fr":"Maurice : le pays et son peuple","mfe":"Moris: pei ek so lepep"}'::jsonb, '{"en":"An introduction to the physical geography of Mauritius and the diverse population that shapes the island''s identity.","fr":"Une introduction à la géographie physique de Maurice et à la population diverse qui façonne l''identité de l''île.","mfe":"Enn lintrodiksion lor zeografi fizik Moris ek popilasion divers ki fer lidentite lil-la."}'::jsonb),
('d63675ca-0255-5a44-9fec-80dd656708e4', 'social-modern-studies', 7, 3, '{"en":"Our island''s history","fr":"L''histoire de notre île","mfe":"Listwar nou lil"}'::jsonb, '{"en":"Students trace the early history of Mauritius, from colonization to the arrival of enslaved and indentured people.","fr":"Les élèves retracent l''histoire ancienne de Maurice, de la colonisation à l''arrivée des esclaves et des travailleurs engagés.","mfe":"Bann elev swiv listwar ansien Moris, depi kolonizasion ziska larive bann esklav ek travayer angaze."}'::jsonb),
('ac3c407a-4c1f-5306-9480-6693f22318fd', 'social-modern-studies', 7, 4, '{"en":"Citizens and government","fr":"Citoyens et gouvernement","mfe":"Sitwayen ek gouvernman"}'::jsonb, '{"en":"This unit introduces citizenship, local government and the rights and responsibilities of Mauritian citizens.","fr":"Cette unité présente la citoyenneté, le gouvernement local ainsi que les droits et responsabilités des citoyens mauriciens.","mfe":"Sa linite-la introdir sitwayente, gouvernman lokal ek bann drwa ek responsabilite sitwayen morisien."}'::jsonb),
('13f253b1-5645-52fc-9b9a-89142400c24f', 'social-modern-studies', 7, 5, '{"en":"Economic life in Mauritius","fr":"La vie économique à Maurice","mfe":"Lavi ekonomik Moris"}'::jsonb, '{"en":"Students examine how people meet their needs through work, resources and trade in the Mauritian economy.","fr":"Les élèves examinent comment les gens satisfont leurs besoins grâce au travail, aux ressources et au commerce dans l''économie mauricienne.","mfe":"Bann elev examinn kouma dimoun satisfer zot bezwin atraver travay, resours ek komers dan lekonomi morisien."}'::jsonb),
('dedfc969-f818-5e68-9e86-26b062cadaac', 'social-modern-studies', 7, 6, '{"en":"Environment and sustainability","fr":"Environnement et durabilité","mfe":"Lanvironnman ek dirabilite"}'::jsonb, '{"en":"This unit looks at the natural environment of Mauritius, environmental challenges and the importance of sustainable living.","fr":"Cette unité examine l''environnement naturel de Maurice, les défis environnementaux et l''importance d''un mode de vie durable.","mfe":"Sa linite-la get lanvironnman natirel Moris, bann defi lanvironnman ek limportans enn lavi dirab."}'::jsonb),
('b1d3c4bc-e909-5346-9d1f-79d1e98567d4', 'social-modern-studies', 7, 7, '{"en":"Culture, religion and national unity","fr":"Culture, religion et unité nationale","mfe":"Kiltir, relizion ek linite nasional"}'::jsonb, '{"en":"Students discover the religions, festivals and symbols that make up Mauritius''s rich cultural heritage and shared identity.","fr":"Les élèves découvrent les religions, les fêtes et les symboles qui composent le riche patrimoine culturel et l''identité commune de Maurice.","mfe":"Bann elev dekouver bann relizion, fet ek senbol ki form parti larises kiltirel ek lidentite kominote Moris."}'::jsonb),
('a1e84c26-7126-5a88-add2-71db0de4059c', 'social-modern-studies', 8, 1, '{"en":"Mauritius under colonial rule","fr":"Maurice sous la domination coloniale","mfe":"Moris anba dominasyon kolonyal"}'::jsonb, '{"en":"Students explore the Dutch, French and British periods of Mauritian history and how each power shaped the island''s society and economy.","fr":"Les élèves explorent les périodes néerlandaise, française et britannique de l''histoire mauricienne et la manière dont chaque puissance a façonné la société et l''économie de l''île.","mfe":"Bann elev explor bann period Olande, Franse ek Britanik dan listwar Moris ek kouman sak pwisans finn fason lasosyete ek lekonomi lil la."}'::jsonb),
('942c423f-d84f-5581-95d3-6dc26ad8f8c6', 'social-modern-studies', 8, 2, '{"en":"Slavery and indentured labour","fr":"Esclavage et travail sous contrat","mfe":"Lesklavaz ek travay angaze"}'::jsonb, '{"en":"This unit examines the system of slavery and the later system of indentured labour that shaped Mauritius''s diverse population.","fr":"Cette unité examine le système de l''esclavage et le système ultérieur du travail sous contrat qui ont façonné la population diversifiée de Maurice.","mfe":"Sa linite la examine sistem lesklavaz ek sistem travay angaze apre ki finn fason popilasyon divers Moris."}'::jsonb),
('73188bb0-4022-5abb-9d87-b90e0713edda', 'social-modern-studies', 8, 3, '{"en":"Population and settlement in Mauritius","fr":"Population et peuplement à Maurice","mfe":"Popilasyon ek etablisman dan Moris"}'::jsonb, '{"en":"Students study population distribution, growth and settlement patterns across the island, linking geography to daily life.","fr":"Les élèves étudient la répartition, la croissance et les modes de peuplement de la population à travers l''île, en reliant la géographie à la vie quotidienne.","mfe":"Bann elev etidye distribisyon, kwasans ek modele etablisman popilasyon partou dan lil la, ek relye zeografi ar lavi toulezour."}'::jsonb),
('4d41c1bd-dcd2-5f34-bd03-faccd97ee2af', 'social-modern-studies', 8, 4, '{"en":"Government and citizenship in Mauritius","fr":"Gouvernement et citoyenneté à Maurice","mfe":"Gouvernman ek sitwayennte dan Moris"}'::jsonb, '{"en":"This unit introduces students to the structures of government, the electoral process and the rights and responsibilities of citizens.","fr":"Cette unité initie les élèves aux structures du gouvernement, au processus électoral et aux droits et responsabilités des citoyens.","mfe":"Sa linite la introdwi bann elev bann striktir gouvernman, prosesis elektoral ek bann drwa ek responsabilite sitwayen."}'::jsonb),
('ccd0a0cd-6f48-5c5b-a825-62ed485894a8', 'social-modern-studies', 8, 5, '{"en":"Economic activities and development","fr":"Activités économiques et développement","mfe":"Aktivite ekonomik ek devlopman"}'::jsonb, '{"en":"Students investigate the sectors of the Mauritian economy and how the country has diversified since independence.","fr":"Les élèves étudient les secteurs de l''économie mauricienne et la manière dont le pays s''est diversifié depuis l''indépendance.","mfe":"Bann elev examine bann sekter lekonomi Morisyen ek kouman pei finn diversifye depi lindepandans."}'::jsonb),
('4c2ee47e-c99a-5323-b412-fe38ac80b6d2', 'social-modern-studies', 8, 6, '{"en":"Environment and sustainable development","fr":"Environnement et développement durable","mfe":"Lanvironnman ek devlopman dirab"}'::jsonb, '{"en":"This unit looks at Mauritius''s natural environment, environmental challenges, and efforts towards sustainability.","fr":"Cette unité examine l''environnement naturel de Maurice, les défis environnementaux et les efforts vers la durabilité.","mfe":"Sa linite la gete lanvironnman natirel Moris, defi lanvironnman ek zefor pou enn devlopman dirab."}'::jsonb),
('5890da3f-ada2-53fe-9269-fd0fbc17ebf5', 'social-modern-studies', 8, 7, '{"en":"Media, communication and society","fr":"Médias, communication et société","mfe":"Lame, kominikasyon ek lasosyete"}'::jsonb, '{"en":"Students examine how media shapes opinions and behaviour, and learn to evaluate information critically in a digital age.","fr":"Les élèves examinent comment les médias façonnent les opinions et les comportements, et apprennent à évaluer l''information de manière critique à l''ère numérique.","mfe":"Bann elev examine kouman lame fason lopinyon ek konportman, ek aprann evalye linformasyon dan enn fason kritik dan laz dizital."}'::jsonb),
('715b31db-cfa0-516e-b8d6-5c1dabcfae2e', 'social-modern-studies', 8, 8, '{"en":"Social issues and living together","fr":"Problèmes sociaux et vivre ensemble","mfe":"Problem sosyal ek viv ansam"}'::jsonb, '{"en":"This unit explores contemporary social issues in Mauritius and the importance of tolerance and social cohesion in a multicultural nation.","fr":"Cette unité explore les problèmes sociaux contemporains à Maurice et l''importance de la tolérance et de la cohésion sociale dans une nation multiculturelle.","mfe":"Sa linite la explor bann problem sosyal kontanporen dan Moris ek linportans toleranse ek kohezyon sosyal dan enn nasyon miltikiltirel."}'::jsonb),
('3b01ed96-da2a-5733-897c-e27496186cdd', 'social-modern-studies', 9, 1, '{"en":"Understanding society and social institutions","fr":"Comprendre la société et les institutions sociales","mfe":"Konpran lasosiete ek lezenstitisyon sosyal"}'::jsonb, '{"en":"Students explore what society is, how it is organised, and the role of key institutions such as family, school and religion in shaping individuals.","fr":"Les élèves explorent ce qu''est la société, son organisation, et le rôle des institutions clés comme la famille, l''école et la religion dans la formation des individus.","mfe":"Bann elev explor ki ete lasosiete, kouma li organize, ek rol bann lenstitisyon kle kouma fami, lekol ek larelizyon dan formasyon bann individi."}'::jsonb),
('9902dfcc-00e1-5b02-9291-f2f8db12ff80', 'social-modern-studies', 9, 2, '{"en":"Mauritius: a plural and diverse nation","fr":"Maurice: une nation plurielle et diverse","mfe":"Moris: enn nasyon plirielist ek divers"}'::jsonb, '{"en":"This unit examines the ethnic, cultural and linguistic diversity of Mauritius and how communities have built national unity.","fr":"Cette unité examine la diversité ethnique, culturelle et linguistique de Maurice et comment les communautés ont construit l''unité nationale.","mfe":"Sa linite-la examinn diversite etnik, kiltirel ek lingwistik Moris ek kouma bann kominote finn konstrir linite nasyonal."}'::jsonb),
('223e376a-55cb-5777-ab8c-da1d54680cf1', 'social-modern-studies', 9, 3, '{"en":"Citizenship, rights and responsibilities","fr":"Citoyenneté, droits et responsabilités","mfe":"Sitwayennte, drwa ek responsabilite"}'::jsonb, '{"en":"Students learn about citizenship, human rights, and their responsibilities as members of a democratic society.","fr":"Les élèves apprennent la citoyenneté, les droits humains et leurs responsabilités en tant que membres d''une société démocratique.","mfe":"Bann elev aprann lor sitwayennte, drwa imen ek zot responsabilite kouma manb enn lasosiete demokratik."}'::jsonb),
('7a6098cb-de1f-5258-b7bf-5509dbc1a42f', 'social-modern-studies', 9, 4, '{"en":"Governance and democracy in Mauritius","fr":"Gouvernance et démocratie à Maurice","mfe":"Gouvernans ek demokrasi Moris"}'::jsonb, '{"en":"This unit introduces the political system of Mauritius, the electoral process and the functioning of democratic institutions.","fr":"Cette unité présente le système politique de Maurice, le processus électoral et le fonctionnement des institutions démocratiques.","mfe":"Sa linite-la introdir sistem politik Moris, prosesis elektoral ek fonksionnman lezenstitisyon demokratik."}'::jsonb),
('b6287da2-f7e2-5b9b-836a-2dbb9efe4500', 'social-modern-studies', 9, 5, '{"en":"Population and migration","fr":"Population et migration","mfe":"Popilasyon ek migrasyon"}'::jsonb, '{"en":"Students study population characteristics, growth patterns and migration trends in Mauritius and their social effects.","fr":"Les élèves étudient les caractéristiques de la population, les schémas de croissance et les tendances migratoires à Maurice et leurs effets sociaux.","mfe":"Bann elev etidye karakteristik popilasyon, model kwasans ek tandans migrasyon Moris ek zot lefe sosyal."}'::jsonb),
('d0911a56-9df6-52e9-8247-d1a2f6fb3d13', 'social-modern-studies', 9, 6, '{"en":"Economic development and world of work","fr":"Développement économique et monde du travail","mfe":"Devlopman ekonomik ek lemond travay"}'::jsonb, '{"en":"This unit looks at economic sectors, employment, and Mauritius''s development from an agricultural to a diversified economy.","fr":"Cette unité examine les secteurs économiques, l''emploi et le développement de Maurice, d''une économie agricole à une économie diversifiée.","mfe":"Sa linite-la gete bann sekter ekonomik, lanplwa ek devlopman Moris, depi enn lekonomi agrikol ver enn lekonomi diversifye."}'::jsonb),
('af782263-a670-59b2-85ed-033126911f44', 'social-modern-studies', 9, 7, '{"en":"Global issues and sustainable development","fr":"Enjeux mondiaux et développement durable","mfe":"Problem mondyal ek devlopman dirab"}'::jsonb, '{"en":"Students examine global challenges such as climate change and inequality, and Mauritius''s role in sustainable development.","fr":"Les élèves examinent les défis mondiaux tels que le changement climatique et les inégalités, ainsi que le rôle de Maurice dans le développement durable.","mfe":"Bann elev examinn defi mondyal kouma sanzman klimatik ek inegalite, ek rol Moris dan devlopman dirab."}'::jsonb),
('d4fa7928-7c2f-59a8-9adb-981296605d9f', 'social-modern-studies', 9, 8, '{"en":"Media, technology and society","fr":"Médias, technologie et société","mfe":"Medya, teknolozi ek lasosiete"}'::jsonb, '{"en":"This unit explores the influence of media and digital technology on Mauritian society and responsible citizenship online.","fr":"Cette unité explore l''influence des médias et de la technologie numérique sur la société mauricienne et la citoyenneté responsable en ligne.","mfe":"Sa linite-la explor lenfliyans medya ek teknolozi dizital lor lasosiete Morisien ek sitwayennte responsab online."}'::jsonb),
('5d25253b-3756-5481-a2fc-d4a856e25f7e', 'social-modern-studies', 10, 1, '{"en":"Foundations of social studies","fr":"Fondements des études sociales","mfe":"Fondasion letid sosyal"}'::jsonb, '{"en":"An introduction to key concepts, methods and vocabulary used in social sciences, preparing students to study society in a structured way.","fr":"Une introduction aux concepts, méthodes et vocabulaire clés utilisés en sciences sociales, préparant les élèves à étudier la société de manière structurée.","mfe":"Enn lentrodiksion konsep, metod ek vokabiler kle itilize dan syans sosyal, pou prepar bann elev etidye lasosiete dan enn fason striktire."}'::jsonb),
('a87946d8-f712-5276-b0e8-0a60bb7bad22', 'social-modern-studies', 10, 2, '{"en":"Mauritian society and culture","fr":"Société et culture mauricienne","mfe":"Lasosiete ek kiltir morisien"}'::jsonb, '{"en":"An exploration of the ethnic, religious and linguistic diversity that shapes Mauritian identity and everyday life.","fr":"Une exploration de la diversité ethnique, religieuse et linguistique qui façonne l''identité mauricienne et la vie quotidienne.","mfe":"Enn leksplorasion divers etnik, relizye ek lingwistik ki fer lidentite morisien ek lavi toulezour."}'::jsonb),
('6a7e6bf5-b6c0-5a6c-b284-3e2d833a7fda', 'social-modern-studies', 10, 3, '{"en":"Family and socialisation","fr":"Famille et socialisation","mfe":"Fami ek sosyalizasion"}'::jsonb, '{"en":"A study of the family as a social institution and how it shapes individuals through the process of socialisation.","fr":"Une étude de la famille en tant qu''institution sociale et de la façon dont elle façonne les individus à travers la socialisation.","mfe":"Enn letid fami kouma enn lenstitision sosyal ek kouma li fer bann individi atraver sosyalizasion."}'::jsonb),
('2db526ec-bf67-5eee-bdc2-9a63d6468a0d', 'social-modern-studies', 10, 4, '{"en":"Social stratification and inequality","fr":"Stratification sociale et inégalités","mfe":"Stratifikasion sosyal ek inegalite"}'::jsonb, '{"en":"An examination of how societies are divided by class, gender and wealth, with focus on inequality in Mauritius.","fr":"Un examen de la manière dont les sociétés sont divisées par classe, genre et richesse, avec un accent sur les inégalités à Maurice.","mfe":"Enn lexamin kouma lasosiete divize par klas, zanr ek larises, avek lafors lor inegalite Moris."}'::jsonb),
('0bda6933-49e6-5a50-b9cf-1fcf54e44380', 'social-modern-studies', 10, 5, '{"en":"Colonisation of Mauritius","fr":"La colonisation de Maurice","mfe":"Kolonizasion Moris"}'::jsonb, '{"en":"A historical study of Dutch, French and British rule in Mauritius and their lasting impact on society.","fr":"Une étude historique de la domination néerlandaise, française et britannique à Maurice et de leur impact durable sur la société.","mfe":"Enn letid istorik lor dominasion Olande, Franse ek Britanik lor Moris ek zot lenpak dirab lor lasosiete."}'::jsonb),
('59388895-79d2-597e-8a25-c60bfa92ddbf', 'social-modern-studies', 10, 6, '{"en":"Path to independence","fr":"Le chemin vers l''indépendance","mfe":"Semin ver lendepandans"}'::jsonb, '{"en":"A study of the political movements and events that led Mauritius to independence in 1968.","fr":"Une étude des mouvements politiques et des événements qui ont conduit Maurice à l''indépendance en 1968.","mfe":"Enn letid bann mouvman politik ek levennman ki''nn amenn Moris ver lendepandans an 1968."}'::jsonb),
('e8594269-9433-5b49-9fcc-8b5b34b88774', 'social-modern-studies', 10, 7, '{"en":"Population and settlement","fr":"Population et peuplement","mfe":"Popilasion ek etablisman"}'::jsonb, '{"en":"A geographical study of population growth, distribution and settlement patterns in Mauritius.","fr":"Une étude géographique de la croissance, de la répartition et des modèles de peuplement de la population à Maurice.","mfe":"Enn letid zeografik lor kwasans, distribision ek modenn etablisman popilasion Moris."}'::jsonb),
('1a6d91b8-e60f-553c-8caa-4715209b4e51', 'social-modern-studies', 10, 8, '{"en":"Environment and sustainable development","fr":"Environnement et développement durable","mfe":"Lanvironnman ek devlopman dirab"}'::jsonb, '{"en":"An examination of Mauritius''s natural resources, environmental challenges and efforts towards sustainable development.","fr":"Un examen des ressources naturelles de Maurice, des défis environnementaux et des efforts vers un développement durable.","mfe":"Enn lexamin resours natirel Moris, defi lanvironnman ek zefor pou devlopman dirab."}'::jsonb),
('676e3e22-2ad7-5250-9fef-70edc9f70d90', 'social-modern-studies', 11, 1, '{"en":"Foundations of social studies","fr":"Fondements des sciences sociales","mfe":"Baz let sians sosial"}'::jsonb, '{"en":"Students are introduced to key sociological concepts, research methods and the processes of socialisation that shape human behaviour in society.","fr":"Les élèves découvrent les concepts sociologiques clés, les méthodes de recherche et les processus de socialisation qui façonnent le comportement humain en société.","mfe":"Bann elev aprann bann konsep sosiolozik prinsipal, bann metod resers ek prosesis sosializasion ki fasonn konportman imin dan lasosiete."}'::jsonb),
('4e4bb817-8b86-5122-867d-dccc35963b6e', 'social-modern-studies', 11, 2, '{"en":"Family and social institutions","fr":"La famille et les institutions sociales","mfe":"Fami ek lenstitisyon sosial"}'::jsonb, '{"en":"This unit examines the changing structure of the family, the role of education and religion as institutions shaping Mauritian society.","fr":"Cette unité examine l''évolution de la structure familiale, ainsi que le rôle de l''éducation et de la religion en tant qu''institutions façonnant la société mauricienne.","mfe":"Sa linite la examinn chanzman dan striktir fami, ek rol ledikasion ek relizion kouma lenstitisyon ki fasonn lasosiete morisien."}'::jsonb),
('470a4da5-f4a8-5ce1-8064-e2a456f9342c', 'social-modern-studies', 11, 3, '{"en":"Culture, identity and multiculturalism","fr":"Culture, identité et multiculturalisme","mfe":"Kiltir, ledantite ek miltikilturalism"}'::jsonb, '{"en":"Learners explore ethnic diversity, national identity, media influence and language as expressions of Mauritius''s multicultural society.","fr":"Les apprenants explorent la diversité ethnique, l''identité nationale, l''influence des médias et la langue comme expressions de la société multiculturelle mauricienne.","mfe":"Bann apran explor diversite etnik, ledantite nasional, lenflians medya ek langaz kouma lexpresion lasosiete miltikiltirel Moris."}'::jsonb),
('ada1871f-5313-518b-aa01-276ec3646346', 'social-modern-studies', 11, 4, '{"en":"Social stratification and inequality","fr":"Stratification sociale et inégalités","mfe":"Stratifikasion sosial ek inegalite"}'::jsonb, '{"en":"This unit analyses class, gender and poverty as forms of social inequality, and examines opportunities for social mobility in Mauritius.","fr":"Cette unité analyse la classe, le genre et la pauvreté comme formes d''inégalité sociale, et examine les opportunités de mobilité sociale à Maurice.","mfe":"Sa linite la analiz kas, zanm ek povrete kouma form inegalite sosial, ek examinn opportinite mobilite sosial dan Moris."}'::jsonb),
('4447e3bc-f1ad-5efb-84d3-3acadc8709d8', 'social-modern-studies', 11, 5, '{"en":"Population and development","fr":"Population et développement","mfe":"Populasion ek devlopman"}'::jsonb, '{"en":"Students study population trends, migration and urbanisation in Mauritius and their links to development challenges.","fr":"Les élèves étudient les tendances démographiques, la migration et l''urbanisation à Maurice ainsi que leurs liens avec les défis du développement.","mfe":"Bann elev etidie tandans demografik, migrasion ek irbanizasion dan Moris ek zot lien avek defi devlopman."}'::jsonb),
('93ab8df9-5be0-5410-96ef-5fdbc7a06b83', 'social-modern-studies', 11, 6, '{"en":"Mauritius''s political and constitutional development","fr":"Développement politique et constitutionnel de Maurice","mfe":"Devlopman politik ek konstitisionel Moris"}'::jsonb, '{"en":"This unit traces Mauritius''s path from colonisation to independence and examines its constitution, government and civic responsibilities.","fr":"Cette unité retrace le parcours de Maurice de la colonisation à l''indépendance et examine sa constitution, son gouvernement et les responsabilités civiques.","mfe":"Sa linite la trase parkour Moris depi kolonizasion ziska lendepandans ek examinn so konstitision, gouvernman ek responsabilite sitwayen."}'::jsonb),
('bc58af01-3499-5c56-a6ce-5625776f7eb9', 'social-modern-studies', 11, 7, '{"en":"Global issues and international relations","fr":"Enjeux mondiaux et relations internationales","mfe":"Problem mondial ek relasion internasional"}'::jsonb, '{"en":"Learners explore globalisation, Mauritius''s place in international organisations, and issues of human rights and conflict.","fr":"Les apprenants explorent la mondialisation, la place de Maurice dans les organisations internationales, ainsi que les questions de droits humains et de conflits.","mfe":"Bann apran explor globalizasion, plas Moris dan bann lorganizasion internasional, ek problem drwa imin ek konfli."}'::jsonb),
('362091e3-8560-576a-9c63-8b3873ae097b', 'social-modern-studies', 11, 8, '{"en":"Environment and sustainable development","fr":"Environnement et développement durable","mfe":"Lanvironnman ek devlopman dirab"}'::jsonb, '{"en":"This unit addresses environmental challenges facing Mauritius, climate change vulnerability, and strategies for sustainable development.","fr":"Cette unité traite des défis environnementaux auxquels Maurice est confrontée, de la vulnérabilité au changement climatique et des stratégies de développement durable.","mfe":"Sa linite la adres bann defi lanvironnman ki Moris fer fas, vilnerabilite anver sanzman klima, ek stratezi pou devlopman dirab."}'::jsonb)
insert into public.lessons (id, unit_id, position, title, objectives) values
('5f7931ee-3d9a-5f66-9bcc-a95e64cca338', 'e49d1028-c688-5e1c-9fb9-3b98b4bfeb2b', 1, '{"en":"Exploring line quality","fr":"Explorer la qualité des lignes","mfe":"Explor kalite liny"}'::jsonb, '["Identify different types of lines used in art","Create a variety of line marks using different tools","Describe the emotional effect of different lines"]'::jsonb),
('35084004-1949-50fc-8d50-2e975b33e6c9', 'e49d1028-c688-5e1c-9fb9-3b98b4bfeb2b', 2, '{"en":"Geometric and organic shapes","fr":"Formes géométriques et organiques","mfe":"Form geometrik ek organik"}'::jsonb, '["Distinguish between geometric and organic shapes","Draw examples of both shape types","Combine shapes to create simple compositions"]'::jsonb),
('43b7e7d6-2ad5-5ee8-9d9b-950823ff27d6', 'e49d1028-c688-5e1c-9fb9-3b98b4bfeb2b', 3, '{"en":"Composing with line and shape","fr":"Composer avec lignes et formes","mfe":"Konpoz avek liny ek form"}'::jsonb, '["Arrange lines and shapes to create balance","Apply repetition and contrast in a composition","Produce a finished artwork using line and shape"]'::jsonb),
